"""Read-only reconstruction of published program/1; never a new compile path."""
from __future__ import annotations

from copy import deepcopy
from typing import Any

from ....methods.definitions.errors import MethodError, MethodFailure
from ....methods.definitions.models import LoadedMethod, SourceResourceView
from ....methods.definitions.models.identity import method_digest


def _resource_ref(resource: SourceResourceView) -> dict[str, str]:
    return {
        "resource_id": resource.declaration["id"],
        "sha256": resource.captured.digest,
        "kind": resource.declaration["kind"],
    }


def _bind_refs(value: Any, resources: dict[str, SourceResourceView]) -> Any:
    if isinstance(value, list):
        return [_bind_refs(child, resources) for child in value]
    if isinstance(value, dict):
        if set(value) == {"resource"}:
            resource_id = value["resource"]
            return _resource_ref(resources[resource_id])
        if "resource" in value:
            resource_id = value["resource"]
            rest = {key: child for key, child in value.items() if key != "resource"}
            return {"resource_ref": _resource_ref(resources[resource_id]), **{
                key: _bind_refs(child, resources) for key, child in rest.items()
            }}
        return {key: _bind_refs(child, resources) for key, child in value.items()}
    return deepcopy(value)


def _first_use_order(loaded: LoadedMethod, kind: str) -> list[str]:
    """Order resources by workflow first use, then by stable resource ID."""
    ids = {key for key, item in loaded.resources.items() if item.declaration.get("kind") == kind}
    found: list[str] = []
    workflow = next((item.value for item in loaded.resources.values()
                     if item.declaration.get("kind") == "workflow" and isinstance(item.value, dict)), {})

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            resource_id = value.get("resource", value.get("resource_id"))
            if isinstance(resource_id, str) and resource_id in ids and resource_id not in found:
                found.append(resource_id)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(workflow)
    found.extend(sorted(ids - set(found)))
    return found


def _decision_order(loaded: LoadedMethod) -> list[str]:
    ids = [key for key, item in loaded.resources.items() if item.declaration.get("kind") == "question_set"]
    # Question-set ordering is semantic and stable: the input contract defines
    # the consumer-facing grouping; ID breaks ties. It does not depend on a host
    # registry's unrelated catalog ordering.
    return sorted(ids, key=lambda key: (
        str((loaded.resources[key].value or {}).get("input_contract", "")), key
    ))


def reconstruct_historical_program_v1(loaded: LoadedMethod, compiler_version: str) -> dict[str, Any]:
    resources = loaded.resources
    workflow_resources = [item for item in resources.values() if item.declaration.get("kind") == "workflow"]
    if len(workflow_resources) != 1 or not isinstance(workflow_resources[0].value, dict):
        raise MethodFailure(MethodError("WORKFLOW_RESOURCE_INVALID", "exactly one parsed workflow resource is required"))

    documents: list[dict[str, Any]] = []
    specs = loaded.manifest.get("documents", [])
    for spec in specs:
        schema_ref = spec["schema"]["resource"]
        schema = resources[schema_ref]
        documents.append({
            "document_type": spec["document_type"],
            "schema_resource": _resource_ref(schema),
            "value_schema": deepcopy(schema.value),
        })

    standards = [
        _bind_refs(resources[resource_id].value, resources)
        for resource_id in _first_use_order(loaded, "standard")
    ]
    decision_templates = [
        _bind_refs(resources[resource_id].value, resources)
        for resource_id in _decision_order(loaded)
    ]
    skill_ids: list[str] = []
    skills = loaded.manifest.get("skills", {})
    if isinstance(skills, dict):
        for skill in skills.values():
            resource_id = skill.get("resource") if isinstance(skill, dict) else None
            if isinstance(resource_id, str) and resource_id in resources and resource_id not in skill_ids:
                skill_ids.append(resource_id)
    skill_ids.extend(sorted({key for key, item in resources.items() if item.declaration.get("kind") == "skill"} - set(skill_ids)))
    skill_resources = [_resource_ref(resources[resource_id]) for resource_id in skill_ids]
    required_capabilities = sorted(
        ({key: item[key] for key in ("capability_id", "kind", "interface_version", "contract_digest")}
         for item in loaded.manifest["requires"]),
        key=lambda item: item["capability_id"],
    )
    # A validated catalog may contain unrelated host capabilities. Only method
    # requirements become part of this immutable program.
    return {
        "schema_version": 1,
        "compiler_version": compiler_version,
        "workflow": _bind_refs(workflow_resources[0].value, resources),
        "documents": documents,
        "standards": standards,
        "decision_templates": decision_templates,
        "skill_resources": skill_resources,
        "capability_bindings": required_capabilities,
    }

"""Immutable RepositoryBaseline and ImplementationPackage records in the active UoW."""
from dataclasses import asdict
import hashlib

from ordessa_infrastructure.encoding import canonical_bytes
from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.domain.common.mechanisms.codec import canonical_value
from ordessa_engineering.domain.common.models.identity import Scope
from ordessa_engineering.domain.common.models.values import Digest
from ordessa_engineering.domain.common.outcomes.diagnostics import ReferenceError
from ordessa_engineering.domain.changes.baselines import RepositorySnapshotRef
from ordessa_engineering.domain.changes.repository_baseline import RepositoryBaseline
from ordessa_engineering.domain.changes.repository_baseline_codec import (
    MAX_REPOSITORY_BASELINE_BYTES, decode_repository_baseline, encode_repository_baseline,
)
from ordessa_engineering.domain.packages.models import ImplementationPackage
from ordessa_engineering.domain.packages.refs import ImplementationPackageRef
from ordessa_engineering.domain.packages.codec import decode_package, encode_package
from .blob_bytes import read_bytes, BlobBytesError
from .implementation_schema import IMPLEMENTATION_SCHEMA_VERSION
from .submission_schema import SUBMISSION_SCHEMA_VERSION, SUBMISSION_DDL, IMPLEMENTATION_APPLY_DDL
from .dispatch_schema import DISPATCH_SCHEMA_VERSION, DISPATCH_DDL
from .acceptance_schema import ACCEPTANCE_SCHEMA_VERSION

_BASELINE_BYTES = ("CASE WHEN typeof(canonical_bytes)='blob' AND "
                   "length(canonical_bytes) BETWEEN 1 AND 2097152 "
                   "THEN canonical_bytes ELSE NULL END")
_PACKAGE_BYTES = ("CASE WHEN typeof(canonical_bytes)='blob' AND "
                  "length(canonical_bytes) BETWEEN 1 AND 2097152 "
                  "THEN canonical_bytes ELSE NULL END")


def _decode(function, raw):
    try:
        return function(raw)
    except (ReferenceError, ValueError, TypeError, KeyError, AttributeError,
            RecursionError, OverflowError):
        raise ApplicationError('RECORD_CORRUPT') from None


def _body_digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def _ref_bytes(ref) -> bytes:
    return canonical_bytes(asdict(ref))


class SQLiteImplementationRepository:
    """Insert-only closed records using the caller's original _RepositoryAccess."""

    def __init__(self, access):
        self.access = access

    def _check(self, *, write=False):
        self.access.check_active()
        if type(self.access.scope) is not Scope:
            raise ApplicationError('SCOPE_MISMATCH')
        row = self.access.execute(
            'SELECT schema_version FROM library_meta WHERE singleton=1').fetchone()
        if row is None or row[0] not in (IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
            raise ApplicationError('IMPLEMENTATION_SCHEMA_REQUIRED')
        if write:
            self.access.require_write()
        return self.access.scope.realm_id, self.access.scope.project_id

    @staticmethod
    def _baseline_key(ref):
        return (ref.realm_id, ref.project_id, ref.repository_id, ref.vcs,
                ref.commit_id or '', ref.tree_digest.hex,
                '' if ref.dirty_overlay_digest is None else ref.dirty_overlay_digest.hex)

    def read_blob(self, ref):
        self._check()
        try:
            return read_bytes(self.access, self.access.authority_id, ref)
        except BlobBytesError as exc:
            raise ApplicationError('IMPLEMENTATION_BLOB_' + exc.code) from exc

    def _verify_files(self, record):
        total = 0
        for file in record.files:
            total += len(self.read_blob(file.blob_ref))
            if total > 16 * 1024 * 1024:
                raise ApplicationError('REPOSITORY_BYTES_BOUND_EXCEEDED')

    def create_repository_baseline(self, record: RepositoryBaseline) -> RepositorySnapshotRef:
        prefix = self._check(write=True)
        if type(record) is not RepositoryBaseline or record.ref.realm_id != prefix[0] or record.ref.project_id != prefix[1]:
            raise ApplicationError('INVALID_ARGUMENT')
        if record.ref.vcs != 'none' or record.ref.dirty_overlay_digest is not None:
            raise ApplicationError('REPOSITORY_CHECKOUT_SOURCE_UNAVAILABLE')
        raw = encode_repository_baseline(record)
        if len(raw) > MAX_REPOSITORY_BASELINE_BYTES or decode_repository_baseline(raw) != record:
            raise ApplicationError('INVALID_ARGUMENT')
        self._verify_files(record)
        ref = record.ref
        key = self._baseline_key(ref)
        existing = self.access.execute(
            'SELECT ref_bytes,body_digest,' + _BASELINE_BYTES +
            ' FROM eng_repository_baselines WHERE realm_id=? AND project_id=? AND repository_id=? AND vcs=? AND commit_key=? AND tree_digest=? AND overlay_key=?',
            key).fetchone()
        encoded_ref = _ref_bytes(ref)
        body_digest = _body_digest(raw)
        if existing is not None:
            if existing[0] != encoded_ref or existing[1] != body_digest or existing[2] != raw:
                raise ApplicationError('REPOSITORY_BASELINE_IDENTITY_CONFLICT')
            self._decode_baseline_row(key, existing)
            return ref
        self.access.execute(
            'INSERT INTO eng_repository_baselines VALUES (?,?,?,?,?,?,?,?,?,?)',
            key + (encoded_ref, body_digest, raw))
        return ref

    def _decode_baseline_row(self, key, row):
        raw = row[2]
        if type(row[0]) is not bytes or type(row[1]) is not str or type(raw) is not bytes or row[1] != _body_digest(raw):
            raise ApplicationError('RECORD_CORRUPT')
        record = _decode(decode_repository_baseline, raw)
        if (record.ref != self._ref_from_baseline_key(key)
                or _ref_bytes(record.ref) != row[0]
                or encode_repository_baseline(record) != raw):
            raise ApplicationError('RECORD_CORRUPT')
        self._verify_files(record)
        return record

    @staticmethod
    def _ref_from_baseline_key(key):
        realm_id, project_id, repository_id, vcs, commit_key, tree_digest, overlay_key = key
        return RepositorySnapshotRef(realm_id, project_id, repository_id, vcs,
            commit_key or None, Digest('sha256', tree_digest),
            None if not overlay_key else Digest('sha256', overlay_key))

    def resolve_repository_baseline(self, ref: RepositorySnapshotRef) -> RepositoryBaseline:
        prefix = self._check()
        if type(ref) is not RepositorySnapshotRef:
            raise ApplicationError('INVALID_ARGUMENT')
        if (ref.realm_id, ref.project_id) != prefix:
            raise ApplicationError('SCOPE_MISMATCH')
        key = self._baseline_key(ref)
        row = self.access.execute(
            'SELECT ref_bytes,body_digest,' + _BASELINE_BYTES +
            ' FROM eng_repository_baselines WHERE realm_id=? AND project_id=? AND repository_id=? AND vcs=? AND commit_key=? AND tree_digest=? AND overlay_key=?',
            key).fetchone()
        if row is None:
            raise ApplicationError('NOT_FOUND')
        return self._decode_baseline_row(key, row)

    def create_package(self, record: ImplementationPackage) -> ImplementationPackageRef:
        prefix = self._check(write=True)
        if type(record) is not ImplementationPackage or (record.scope.realm_id, record.scope.project_id) != prefix:
            raise ApplicationError('INVALID_ARGUMENT')
        raw = encode_package(record)
        if type(raw) is not bytes or not 1 <= len(raw) <= 2097152 or decode_package(raw) != record:
            raise ApplicationError('INVALID_ARGUMENT')
        ref = record.ref
        existing = self.access.execute(
            'SELECT digest,' + _PACKAGE_BYTES +
            ' FROM eng_packages WHERE realm_id=? AND project_id=? AND package_id=?',
            prefix + (record.package_id,)).fetchone()
        if existing is not None:
            if existing[0] != ref.digest.hex or existing[1] != raw:
                raise ApplicationError('PACKAGE_IDENTITY_CONFLICT')
            self._decode_package_row(prefix + (record.package_id,), existing, ref)
            return ref
        self.access.execute('INSERT INTO eng_packages VALUES (?,?,?,?,?)',
            prefix + (record.package_id, ref.digest.hex, raw))
        return ref

    def _decode_package_row(self, key, row, requested_ref=None):
        raw = row[1]
        if type(row[0]) is not str or type(raw) is not bytes:
            raise ApplicationError('RECORD_CORRUPT')
        record = _decode(decode_package, raw)
        if (record.ref.digest.hex != row[0]
                or (record.scope.realm_id, record.scope.project_id, record.package_id) != key
                or requested_ref is not None and record.ref != requested_ref
                or encode_package(record) != raw):
            raise ApplicationError('RECORD_CORRUPT')
        return record

    def resolve_package(self, ref: ImplementationPackageRef) -> ImplementationPackage:
        prefix = self._check()
        if type(ref) is not ImplementationPackageRef:
            raise ApplicationError('INVALID_ARGUMENT')
        if (ref.realm_id, ref.project_id) != prefix:
            raise ApplicationError('SCOPE_MISMATCH')
        key = prefix + (ref.package_id,)
        row = self.access.execute(
            'SELECT digest,' + _PACKAGE_BYTES +
            ' FROM eng_packages WHERE realm_id=? AND project_id=? AND package_id=?', key).fetchone()
        if row is None:
            raise ApplicationError('NOT_FOUND')
        return self._decode_package_row(key, row, ref)

"""Adapter-side per-resolution material access (budget / blob reads / CAS).

This module keeps only transaction access on the caller's original connection.
The source/selector/content closure rules live in
``ordessa_engineering.application.usecases.material_closure`` (coordinating reads
through the declared ``MaterialAccessPort``) with their pure rules owned by
``domain`` / ``methods``. No business acceptance decision is made here.
"""
from __future__ import annotations

from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.domain.common.mechanisms.selection import (SelectorChecks)
from ordessa_engineering.domain.common.models.refs import (BlobRef)
from ordessa_engineering.domain.common.models.values import (Digest)
from ordessa_engineering.domain.common.outcomes.diagnostics import (ReferenceError)
from ordessa_engineering.methods.definitions.errors import MethodFailure
from ordessa_engineering.methods.definitions.models import MethodRef as SnapshotRef
from .blob_bytes import BlobBytesError, read_bytes, validate_ref
from .snapshot_store import load_snapshot

MAX_MATERIAL_BYTES = 64 * 1024 * 1024


def _deny(code):
    raise ApplicationError(code)


class MaterialBudget:
    """Private per-resolution/TX budget, not a new byte store or authority.

    Implements the application ``MaterialAccessPort``: every read happens on the
    caller's own connection/scope; nothing is retained for cross-transaction reuse.
    """
    def __init__(self, access):
        self.access = access
        self.total = 0
        self.reserved = set()
        self.validated = set()
        self.validated_results = {}
        self.bodies = {}
        self.methods = {}
        self.snapshot_digests = set()
        self.record_keys = set()
        self.proposals = {}
        self.revisions = {}
        self.proposal_rows = {}
        self.selectors = SelectorChecks()

    def mark_validated(self, key):
        self.validated.add(key)

    def is_validated(self, key):
        return key in self.validated

    def bind_validated_result(self, key, result):
        """Bind the validated result to the same per-operation key.

        The adapter write consumes this bound result; a caller cannot substitute
        or empty the value without a key mismatch.
        """
        self.validated_results[key] = result

    def validated_result(self, key):
        return self.validated_results.get(key)

    def record(self, key, raw):
        if key not in self.record_keys:
            self.total += len(raw)
            if self.total > MAX_MATERIAL_BYTES:
                _deny('MATERIAL_LIMIT')
            self.record_keys.add(key)

    def reserve(self, refs):
        for ref in refs:
            try:
                validate_ref(self.access.authority_id, ref)
            except (BlobBytesError, ReferenceError):
                _deny('MATERIAL_BLOB_INVALID')
            key = (ref.digest.hex, ref.byte_length)
            if key not in self.reserved:
                self.total += ref.byte_length
                if self.total > MAX_MATERIAL_BYTES:
                    _deny('MATERIAL_LIMIT')
                self.reserved.add(key)

    def read(self, ref):
        # Validate every locator even when identical bytes have been cached.
        self.reserve((ref,))
        key = (ref.digest.hex, ref.byte_length)
        if key not in self.bodies:
            try:
                self.bodies[key] = read_bytes(self.access, self.access.authority_id, ref)
            except BlobBytesError as exc:
                _deny('MATERIAL_BLOB_' + exc.code)
        return self.bodies[key]

    def method(self, ref):
        if ref not in self.methods:
            converted = SnapshotRef(ref.method_id, ref.release_version,
                                    ref.schema_version, ref.snapshot_digest.hex)
            def budget(snapshot):
                # Metadata is bounded before any source body is read.
                refs = (snapshot.manifest_ref,) + tuple(r.blob_ref for r in snapshot.resources)
                from .snapshot_codec import encode_snapshot
                if snapshot.snapshot_digest not in self.snapshot_digests:
                    self.total += len(encode_snapshot(snapshot))
                    if self.total > MAX_MATERIAL_BYTES:
                        _deny('MATERIAL_LIMIT')
                    self.snapshot_digests.add(snapshot.snapshot_digest)
                self.reserve(tuple(BlobRef(Digest('sha256', r.digest), r.byte_length,
                                           r.media_type, r.storage_object_id) for r in refs))
            try:
                self.methods[ref] = load_snapshot(self.access, self.access.authority_id,
                                                 converted, budget=budget)
            except MethodFailure as exc:
                _deny('MATERIAL_METHOD_' + exc.error.code)
        return self.methods[ref]

"""Public method guards share the original library lock and UoW CAS.

The temporary thread-local expectations are fences, never another state store.
Every consuming original UoW rechecks them after BEGIN; BEGIN IMMEDIATE then
prevents another SQLite connection changing the state before its COMMIT.
"""
from contextlib import contextmanager
import threading
from ordessa_engineering.application.contracts.commands import CommandContext
from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.domain.artifacts.method_binding import MethodRef
from ordessa_engineering.methods.definitions.models import MethodRef as SnapshotRef
from .unit_of_work import SQLiteUoWFactory
from .snapshot_store import SQLiteSnapshotStore


class SQLiteMethodControl:
    def __init__(self, factory, snapshots):
        if type(factory) is not SQLiteUoWFactory or type(snapshots) is not SQLiteSnapshotStore or snapshots.library is not factory.library:
            raise ApplicationError('METHOD_AUTHORITY_MISMATCH')
        self.factory,self.snapshots=factory,snapshots
        with factory.library._lock:
            if not hasattr(factory.library,'_method_guard_fences'):
                factory.library._method_guard_fences=threading.local()

    @contextmanager
    def _guard(self, context, method, expected_version, selected):
        if type(context) is not CommandContext or (method is not None and type(method) is not MethodRef):
            raise ApplicationError('INVALID_INPUT')
        if expected_version is not None and (type(expected_version) is not int or not 0 <= expected_version <= (1<<63)-1):
            raise ApplicationError('INVALID_INPUT')
        library=self.factory.library
        with library._lock:
            with self.factory.begin(context.scope,'read') as uow:
                adoption=uow.methods.selected() if selected else None
                ref=adoption.method_ref if selected else method
                control=uow.methods.control(ref)
                if not control.enabled:
                    raise ApplicationError('METHOD_DISABLED')
                current=adoption.version if selected else control.version
                if expected_version is not None and expected_version != current:
                    raise ApplicationError('METHOD_SELECTION_CHANGED' if selected else 'METHOD_CONTROL_CHANGED')
            snapshot=self.snapshots.get(SnapshotRef(ref.method_id,ref.release_version,ref.schema_version,ref.snapshot_digest.hex))
            if adoption is not None:
                from ordessa_engineering.methods.compilation.encoding import program_plan_digest
                if program_plan_digest(snapshot.program).removeprefix('sha256:') != adoption.compiled_plan_digest.hex:
                    raise ApplicationError('METHOD_STATE_CORRUPT')
            fences=library._method_guard_fences
            previous=getattr(fences,'values',())
            fences.values=previous+((control,adoption),)
            try:
                yield snapshot
            finally:
                fences.values=previous

    def guard_method(self, context, method_ref, *, expected_version=None):
        """Historical work stays pinned: newer adoption does not disable M1."""
        return self._guard(context,method_ref,expected_version,False)

    def guard_selected(self, context, *, expected_version=None):
        """Resolve the explicitly selected project method for new work."""
        return self._guard(context,None,expected_version,True)

"""Method histories and CAS on the original Engineering UoW, not a catalog."""
from dataclasses import asdict
from ordessa_infrastructure.encoding import canonical_bytes
from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.application.contracts.method_controls import MethodControl, MethodAdoption
from ordessa_engineering.domain.common.models.values import Digest, MAX_VERSION
from ordessa_engineering.domain.common.mechanisms.codec import canonical_value
from ordessa_engineering.domain.artifacts.method_binding import MethodRef
from .method_schema import METHOD_SCHEMA_VERSION
from .implementation_schema import IMPLEMENTATION_SCHEMA_VERSION, IMPLEMENTATION_DDL, IMPLEMENTATION_TABLES
from .submission_schema import SUBMISSION_SCHEMA_VERSION, SUBMISSION_DDL, IMPLEMENTATION_APPLY_DDL
from .dispatch_schema import DISPATCH_SCHEMA_VERSION, DISPATCH_DDL
from .acceptance_schema import ACCEPTANCE_SCHEMA_VERSION


def _method(value):
    if type(value) is not dict or set(value) != {'method_id','release_version','schema_version','snapshot_digest'}:
        raise ApplicationError('METHOD_STATE_CORRUPT')
    digest=value['snapshot_digest']
    if type(digest) is not dict or set(digest) != {'algorithm','hex'}:
        raise ApplicationError('METHOD_STATE_CORRUPT')
    return MethodRef(value['method_id'],value['release_version'],value['schema_version'],Digest(**digest))


class SQLiteMethodRepository:
    def __init__(self, access):
        self.access=access

    def _check(self):
        self.access.check_active()
        if getattr(self.access._connection,'_ordessa_schema_version',None) not in (METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
            raise ApplicationError('METHOD_CONTROL_SCHEMA_REQUIRED')

    def _prefix(self):
        self._check()
        return (self.access.scope.realm_id,self.access.scope.project_id)

    def control(self, method):
        row=self.access.execute('SELECT enabled,version,event_ref FROM eng_method_controls WHERE realm_id=? AND project_id=? AND method_snapshot_digest=?',self._prefix()+(method.snapshot_digest.hex,)).fetchone()
        if row is None:
            raise ApplicationError('METHOD_CONTROL_UNAVAILABLE')
        event=self.access.execute('SELECT canonical_bytes FROM eng_method_control_events WHERE realm_id=? AND project_id=? AND method_snapshot_digest=? AND version=?',self._prefix()+(method.snapshot_digest.hex,row[1])).fetchone()
        if event is None:
            raise ApplicationError('METHOD_STATE_CORRUPT')
        value=canonical_value(event[0])
        if type(value) is not dict or set(value) != {'control','reason','occurred_at'}:
            raise ApplicationError('METHOD_STATE_CORRUPT')
        control=MethodControl(self.access.scope,method,bool(row[0]),row[1],Digest('sha256',row[2]))
        if canonical_bytes(value['control']) != canonical_bytes(asdict(control)):
            raise ApplicationError('METHOD_STATE_CORRUPT')
        return control

    def control_by_digest(self, digest):
        row=self.access.execute('SELECT e.canonical_bytes FROM eng_method_control_events e JOIN eng_method_controls c ON e.realm_id=c.realm_id AND e.project_id=c.project_id AND e.method_snapshot_digest=c.method_snapshot_digest AND e.version=c.version WHERE c.realm_id=? AND c.project_id=? AND c.method_snapshot_digest=?',self._prefix()+(digest,)).fetchone()
        if row is None:
            raise ApplicationError('METHOD_CONTROL_UNAVAILABLE')
        value=canonical_value(row[0])
        return self.control(_method(value['control']['method_ref']))

    def selected(self):
        row=self.access.execute('SELECT adoption_id,version,method_snapshot_digest,canonical_bytes FROM eng_method_adoptions WHERE realm_id=? AND project_id=? ORDER BY version DESC LIMIT 1',self._prefix()).fetchone()
        if row is None:
            raise ApplicationError('METHOD_SELECTION_UNAVAILABLE')
        value=canonical_value(row[3])
        if type(value) is not dict or set(value) != {'scope','adoption_id','method_ref','compiled_plan_digest','version','event_ref','occurred_at'}:
            raise ApplicationError('METHOD_STATE_CORRUPT')
        adoption=MethodAdoption(self.access.scope,value['adoption_id'],_method(value['method_ref']),Digest(**value['compiled_plan_digest']),value['version'],Digest(**value['event_ref']),value['occurred_at'])
        if (row[:3] != (adoption.adoption_id,adoption.version,adoption.method_ref.snapshot_digest.hex) or canonical_bytes(asdict(adoption)) != row[3]):
            raise ApplicationError('METHOD_STATE_CORRUPT')
        return adoption

    def select(self, method, adoption_id, expected_version, event_ref, occurred_at, compiled_plan_digest):
        self.access.require_write();self._check()
        try: current=self.selected().version
        except ApplicationError as exc:
            if exc.code != 'METHOD_SELECTION_UNAVAILABLE': raise
            current=0
        if current != expected_version:
            raise ApplicationError('METHOD_SELECTION_CHANGED')
        if current == MAX_VERSION:
            raise ApplicationError('VERSION_EXHAUSTED')
        try: control=self.control(method)
        except ApplicationError as exc:
            if exc.code != 'METHOD_CONTROL_UNAVAILABLE': raise
            control=MethodControl(self.access.scope,method,True,0,event_ref)
            self.access.execute('INSERT INTO eng_method_controls VALUES (?,?,?,?,?,?)',self._prefix()+(method.snapshot_digest.hex,1,0,event_ref.hex))
            self._event(control,'explicit adoption',occurred_at)
        if not control.enabled:
            raise ApplicationError('METHOD_DISABLED')
        adoption=MethodAdoption(self.access.scope,adoption_id,method,compiled_plan_digest,current+1,event_ref,occurred_at)
        self.access.execute('INSERT INTO eng_method_adoptions VALUES (?,?,?,?,?,?)',self._prefix()+(adoption_id,adoption.version,method.snapshot_digest.hex,canonical_bytes(asdict(adoption))))
        return adoption

    def _event(self, control, reason, occurred_at):
        self.access.execute('INSERT INTO eng_method_control_events VALUES (?,?,?,?,?)',self._prefix()+(control.method_ref.snapshot_digest.hex,control.version,canonical_bytes(dict(control=asdict(control),reason=reason,occurred_at=occurred_at))))

    def set_control(self, method, expected_version, enabled, event_ref, reason, occurred_at):
        self.access.require_write()
        current=self.control(method)
        if current.version != expected_version:
            raise ApplicationError('METHOD_CONTROL_CHANGED')
        if current.version == MAX_VERSION:
            raise ApplicationError('VERSION_EXHAUSTED')
        control=MethodControl(self.access.scope,method,enabled,current.version+1,event_ref)
        result=self.access.execute('UPDATE eng_method_controls SET enabled=?,version=?,event_ref=? WHERE realm_id=? AND project_id=? AND method_snapshot_digest=? AND version=?',(int(enabled),control.version,event_ref.hex)+self._prefix()+(method.snapshot_digest.hex,expected_version))
        if result.rowcount != 1:
            raise ApplicationError('METHOD_CONTROL_CHANGED')
        self._event(control,reason,occurred_at)
        return control

    def check_guard(self, control, selection=None):
        if control.scope != self.access.scope:
            return  # different scope UoWs do not consume this temporary guard
        if self.control(control.method_ref) != control:
            raise ApplicationError('METHOD_CONTROL_CHANGED')
        if not control.enabled:
            raise ApplicationError('METHOD_DISABLED')
        if selection is not None and self.selected() != selection:
            raise ApplicationError('METHOD_SELECTION_CHANGED')

"""Explicit schema10: project method selection history and controlled snapshots."""
METHOD_SCHEMA_VERSION = 10
METHOD_TABLES = ('eng_method_adoptions', 'eng_method_controls', 'eng_method_control_events')
METHOD_DDL = """
CREATE TABLE eng_method_adoptions (
 realm_id TEXT NOT NULL, project_id TEXT NOT NULL, adoption_id TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 9223372036854775807),
 method_snapshot_digest TEXT NOT NULL REFERENCES eng_method_snapshots(snapshot_digest),
 canonical_bytes BLOB NOT NULL CHECK(typeof(canonical_bytes)='blob' AND length(canonical_bytes) BETWEEN 1 AND 2097152),
 PRIMARY KEY(realm_id,project_id,adoption_id), UNIQUE(realm_id,project_id,version)
);
CREATE TABLE eng_method_controls (
 realm_id TEXT NOT NULL, project_id TEXT NOT NULL,
 method_snapshot_digest TEXT NOT NULL REFERENCES eng_method_snapshots(snapshot_digest),
 enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),
 version INTEGER NOT NULL CHECK(version BETWEEN 0 AND 9223372036854775807),
 event_ref TEXT NOT NULL,
 PRIMARY KEY(realm_id,project_id,method_snapshot_digest)
);
CREATE TABLE eng_method_control_events (
 realm_id TEXT NOT NULL, project_id TEXT NOT NULL, method_snapshot_digest TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version BETWEEN 0 AND 9223372036854775807),
 canonical_bytes BLOB NOT NULL CHECK(typeof(canonical_bytes)='blob' AND length(canonical_bytes) BETWEEN 1 AND 2097152),
 PRIMARY KEY(realm_id,project_id,method_snapshot_digest,version),
 FOREIGN KEY(realm_id,project_id,method_snapshot_digest) REFERENCES eng_method_controls(realm_id,project_id,method_snapshot_digest)
);
"""
for _table in ('eng_method_adoptions','eng_method_control_events'):
    METHOD_DDL += f"""
CREATE TRIGGER {_table}_no_update BEFORE UPDATE ON {_table}
BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_RECORD'); END;
CREATE TRIGGER {_table}_no_delete BEFORE DELETE ON {_table}
BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_RECORD'); END;
"""

"""Proposal/change/control records on the caller's original Engineering UoW."""
from .submission_schema import SUBMISSION_SCHEMA_VERSION
from .dispatch_schema import DISPATCH_SCHEMA_VERSION, DISPATCH_DDL
from .acceptance_schema import ACCEPTANCE_SCHEMA_VERSION
from dataclasses import asdict
from ordessa_infrastructure.encoding import canonical_bytes
from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.domain.changes.refs import (ProposalRef)
from ordessa_engineering.domain.common.outcomes.diagnostics import (ReferenceError)
from ordessa_engineering.domain.common.models.identity import (Scope)
from ordessa_engineering.domain.common.models.values import (Digest, validate_id)
from ordessa_engineering.domain.common.mechanisms.hashing import (record_digest)
from ordessa_engineering.domain.common.mechanisms.codec import (canonical_value)
from ordessa_engineering.domain.common.models.values import (utc_instant)
from ordessa_engineering.domain.common.models.identity import (ActorRef)
from ordessa_engineering.domain.common.mechanisms.codec import (require_object, decode_actor, decode_digest)
from ordessa_engineering.domain.changes.models import Change, Proposal, ProposalControl
from ordessa_engineering.domain.changes.codec import (
    encode_proposal,
    decode_proposal,
    encode_control,
    decode_control,
)
from ordessa_engineering.domain.changes.operations import validate_change_set
from ordessa_engineering.domain.common.models.values import (validate_version, validate_text, MAX_VERSION)
from .artifact_repository import SQLiteArtifactRepository
from .material_validation import MaterialBudget
from ordessa_engineering.application.usecases.proposal_closure import coordinate_closure
from ordessa_engineering.application.contracts.access import proposal_validation_key

_BYTES="CASE WHEN typeof(canonical_bytes)='blob' AND length(canonical_bytes)<=2097152 THEN canonical_bytes ELSE NULL END"


def _decode(function,raw):
    try:
        return function(raw)
    except (ValueError,TypeError,KeyError,AttributeError,RecursionError,OverflowError):
        raise ApplicationError('RECORD_CORRUPT') from None


def _event(control,at,actor,reason):
    utc_instant(at)
    if type(actor) is not ActorRef:
        raise ReferenceError('INVALID_SCHEMA')
    validate_text(reason)
    data={'control':asdict(control),'created_at':at,'created_by':asdict(actor),'reason':reason}
    return canonical_bytes({**data,'digest':asdict(record_digest('proposal-control-event',data))})


def _decode_event(raw):
    value=canonical_value(raw)
    require_object(value,{'control','created_at','created_by','reason','digest'}, code='INVALID_REVISION')
    control=decode_control(canonical_bytes(value['control']))
    actor=decode_actor(value['created_by'])
    if _event(control,value['created_at'],actor,value['reason'])!=raw:
        raise ReferenceError('INVALID_SCHEMA')
    return control,value['created_at'],actor,value['reason']


class SQLiteProposalRepository:
    def __init__(self,access):
        self.access=access
        self.artifacts=SQLiteArtifactRepository(access)

    def _prefix(self):
        self.access.check_active()
        if type(self.access.scope) is not Scope:
            raise ApplicationError('SCOPE_MISMATCH')
        return self.access.scope.realm_id,self.access.scope.project_id

    def _ref(self,ref):
        if type(ref) is not ProposalRef:
            raise ApplicationError('INVALID_ARGUMENT')
        if (ref.realm_id,ref.project_id)!=self._prefix():
            raise ApplicationError('SCOPE_MISMATCH')

    def create_change(self,change):
        self.access.require_write()
        if type(change) is not Change or change.scope!=self.access.scope or change.version!=0 or change.proposal_ids or change.selected_proposal_id is not None:
            raise ApplicationError('INVALID_ARGUMENT')
        self.access.execute('INSERT INTO eng_changes VALUES (?,?,?,?,NULL,0)',self._prefix()+(change.change_id,change.created_at))

    def get_change(self,change_id):
        try:
            validate_id(change_id)
        except ReferenceError:
            raise ApplicationError('INVALID_ARGUMENT') from None
        row=self.access.execute('SELECT created_at,selected_proposal_id,version FROM eng_changes WHERE realm_id=? AND project_id=? AND change_id=?',self._prefix()+(change_id,)).fetchone()
        if row is None:
            raise ApplicationError('NOT_FOUND')
        proposals=self.access.execute('SELECT proposal_id FROM eng_proposals WHERE realm_id=? AND project_id=? AND change_id=? ORDER BY proposal_id LIMIT 4097',self._prefix()+(change_id,)).fetchall()
        try:
            return Change(self.access.scope,change_id,row[0],tuple(p[0] for p in proposals),row[1],row[2])
        except (ReferenceError,TypeError,ValueError):
            raise ApplicationError('RECORD_CORRUPT') from None

    def read_proposal(self,ref,budget):
        """Read + canonical-decode one proposal record on this active scope.

        Adapter read primitive only (no business validation). The application
        closure consumes it through ``ProposalReadPort``.
        """
        self._ref(ref)
        if ref in budget.proposal_rows:
            return budget.proposal_rows[ref]
        row=self.access.execute('SELECT change_id,digest,schema_version,'+_BYTES+' FROM eng_proposals WHERE realm_id=? AND project_id=? AND proposal_id=?',self._prefix()+(ref.proposal_id,)).fetchone()
        if row is None:
            raise ApplicationError('NOT_FOUND')
        record=_decode(decode_proposal,row[3])
        if record.ref!=ref or row[:3]!=(record.change_id,record.digest.hex,record.schema_version):
            raise ApplicationError('RECORD_CORRUPT')
        budget.record(('proposal',ref),row[3])
        rows=self.access.execute('SELECT position,artifact_id,operation,base_revision_id,proposed_revision_id FROM eng_proposal_mutations WHERE realm_id=? AND project_id=? AND proposal_id=? ORDER BY position LIMIT 4097',self._prefix()+(ref.proposal_id,)).fetchall()
        expected=[(i,m.artifact_id,m.operation,None if m.base_ref is None else m.base_ref.revision_id,m.proposed_ref.revision_id) for i,m in enumerate(record.mutations)]
        if rows!=expected:
            raise ApplicationError('RECORD_CORRUPT')
        budget.proposal_rows[ref]=record
        return record

    def resolve_revision_graph(self,roots,budget):
        """Adapter read primitive: resolve the exact revision graph on this scope."""
        return self.artifacts.resolve_graph(roots,budget=budget)

    def select_artifact(self,scope,artifact_id):
        """Adapter read primitive: select one artifact owner on this scope."""
        return self.artifacts._select_artifact(scope,artifact_id)

    def get_proposal(self,ref,*,budget=None):
        budget=MaterialBudget(self.access) if budget is None else budget
        if type(budget) is not MaterialBudget or budget.access is not self.access:
            raise ApplicationError('INVALID_ARGUMENT')
        self._ref(ref)
        if ref in budget.proposals:
            return budget.proposals[ref]
        record=self.read_proposal(ref,budget)
        try:
            # Read-integrity closure, orchestrated by the application coordinate.
            _,validated=coordinate_closure(record,self,budget)
        except ReferenceError as exc:
            raise ApplicationError('RECORD_CORRUPT') from exc
        budget.proposals.update({ref:value for ref,value in validated.items() if ref in budget.proposal_rows})
        budget.proposals[ref]=record
        return record

    def resolve_repository_baseline(self, ref, budget):
        from .implementation_schema import IMPLEMENTATION_SCHEMA_VERSION
        from .implementation_repository import SQLiteImplementationRepository
        from ordessa_engineering.domain.changes.repository_baseline_codec import encode_repository_baseline
        if getattr(self.access._connection, '_ordessa_schema_version', None) not in (IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
            raise ApplicationError('IMPLEMENTATION_BASELINE_AUTHORITY_UNAVAILABLE')
        if type(budget) is not MaterialBudget or budget.access is not self.access:
            raise ApplicationError('INVALID_ARGUMENT')
        record = SQLiteImplementationRepository(self.access).resolve_repository_baseline(ref)
        budget.record(('repository-baseline', ref), encode_repository_baseline(record))
        for file in record.files:
            budget.read(file.blob_ref)
        return record

    def validated_budget(self):
        """Open a short-lived per-operation validation budget on this UoW/readset.

        The application triggers ``validate_create`` (proposal_closure) against
        it; ``create_proposal`` then requires the same budget to carry the
        marker. One UoW may open several independent budgets (per-operation
        accounting preserved).
        """
        budget=MaterialBudget(self.access)
        self._material_budget=budget
        return budget

    def create_proposal(self,record,*,expected_version,budget,requirements):
        self.access.require_write()
        if type(record) is not Proposal or record.scope!=self.access.scope:
            raise ApplicationError('INVALID_ARGUMENT')
        validate_version(expected_version)
        raw=encode_proposal(record)
        if decode_proposal(raw)!=record:
            raise ApplicationError('INVALID_ARGUMENT')
        key=proposal_validation_key(record)
        if type(budget) is not MaterialBudget or budget.access is not self.access or not budget.is_validated(key):
            raise ApplicationError('PROPOSAL_VALIDATION_REQUIRED')
        bound=budget.validated_result(key)
        if bound is None or requirements!=bound:
            # The write consumes only the validated result; a substituted or
            # emptied argument cannot match the bound value.
            raise ApplicationError('PROPOSAL_VALIDATION_REQUIRED')
        budget.record(('proposal',record.ref),raw)
        change=self.get_change(record.change_id)
        existing=self.access.execute('SELECT '+_BYTES+' FROM eng_proposals WHERE realm_id=? AND project_id=? AND proposal_id=?',self._prefix()+(record.proposal_id,)).fetchone()
        if existing is not None:
            if existing[0]!=raw:
                raise ApplicationError('PROPOSAL_IDENTITY_CONFLICT')
            return self.get_proposal(record.ref).ref
        if change.version!=expected_version:
            raise ApplicationError('VERSION_CONFLICT')
        if change.version==MAX_VERSION or len(change.proposal_ids)>=4096:
            raise ApplicationError('VERSION_EXHAUSTED')
        self.access.execute('INSERT INTO eng_proposals VALUES (?,?,?,?,?,?,?)',self._prefix()+(record.proposal_id,record.change_id,record.digest.hex,record.schema_version,raw))
        for i,m in enumerate(record.mutations):
            self.access.execute('INSERT INTO eng_proposal_mutations VALUES (?,?,?,?,?,?,?,?)',self._prefix()+(record.proposal_id,i,m.artifact_id,m.operation,None if m.base_ref is None else m.base_ref.revision_id,m.proposed_ref.revision_id))
        control=ProposalControl(record.ref)
        self.access.execute('INSERT INTO eng_proposal_controls VALUES (?,?,?,0,?)',self._prefix()+(record.proposal_id,encode_control(control)))
        self.access.execute('INSERT INTO eng_proposal_control_events VALUES (?,?,?,0,?)',self._prefix()+(record.proposal_id,_event(control,record.created_at,record.created_by,'created')))
        cursor=self.access.execute('UPDATE eng_changes SET version=version+1 WHERE realm_id=? AND project_id=? AND change_id=? AND version=?',self._prefix()+(record.change_id,expected_version))
        if cursor.rowcount!=1:
            raise ApplicationError('VERSION_CONFLICT')
        # Freeze only a reread of the actual immutable row/index in this TX.
        self.read_proposal(record.ref,budget)
        budget.proposals[record.ref]=record
        from .review_repository import SQLiteReviewRepository
        reviews=SQLiteReviewRepository(self.access)
        for requirement in bound:
            reviews.ensure_requirement(requirement,budget=budget)
        return record.ref

    def get_control(self,ref,*,budget=None):
        record=self.get_proposal(ref,budget=budget)
        row=self.access.execute('SELECT version,'+_BYTES+' FROM eng_proposal_controls WHERE realm_id=? AND project_id=? AND proposal_id=?',self._prefix()+(ref.proposal_id,)).fetchone()
        if row is None:
            raise ApplicationError('RECORD_CORRUPT')
        control=_decode(decode_control,row[1])
        if control.proposal_ref!=ref or control.version!=row[0] or control.version>1:
            raise ApplicationError('RECORD_CORRUPT')
        events=self.access.execute('SELECT version,'+_BYTES+' FROM eng_proposal_control_events WHERE realm_id=? AND project_id=? AND proposal_id=? ORDER BY version LIMIT 3',self._prefix()+(ref.proposal_id,)).fetchall()
        if len(events)!=control.version+1:
            raise ApplicationError('RECORD_CORRUPT')
        for i,(v,raw) in enumerate(events):
            event,at,actor,reason=_decode(_decode_event,raw)
            if v!=i or event.version!=i or event.proposal_ref!=ref:
                raise ApplicationError('RECORD_CORRUPT')
            if i==0 and (event!=ProposalControl(ref) or at!=record.created_at or actor!=record.created_by or reason!='created'):
                raise ApplicationError('RECORD_CORRUPT')
            if i==control.version and event!=control:
                raise ApplicationError('RECORD_CORRUPT')
        return control

    def select(self,ref,*,expected_version):
        self.access.require_write()
        validate_version(expected_version)
        self.get_proposal(ref)
        change=self.get_change(ref.change_id)
        if change.version!=expected_version:
            raise ApplicationError('VERSION_CONFLICT')
        if change.version==MAX_VERSION:
            raise ApplicationError('VERSION_EXHAUSTED')
        cursor=self.access.execute('UPDATE eng_changes SET selected_proposal_id=?,version=version+1 WHERE realm_id=? AND project_id=? AND change_id=? AND version=?',(ref.proposal_id,)+self._prefix()+(ref.change_id,expected_version))
        if cursor.rowcount!=1:
            raise ApplicationError('VERSION_CONFLICT')
        return self.get_change(ref.change_id)

    def control(self,ref,*,expected_version,disposition,replacement_ref,evidence,at,actor,reason):
        self.access.require_write()
        validate_version(expected_version)
        current=self.get_control(ref)
        if current.version!=expected_version:
            raise ApplicationError('PROPOSAL_CONTROL_CHANGED')
        if current.disposition!='available':
            raise ApplicationError('PROPOSAL_UNAVAILABLE')
        if replacement_ref is not None:
            self.get_proposal(replacement_ref)
        updated=ProposalControl(ref,disposition,replacement_ref,evidence,current.version+1)
        event=_event(updated,at,actor,reason)
        cursor=self.access.execute('UPDATE eng_proposal_controls SET version=?,canonical_bytes=? WHERE realm_id=? AND project_id=? AND proposal_id=? AND version=?',(updated.version,encode_control(updated))+self._prefix()+(ref.proposal_id,expected_version))
        if cursor.rowcount!=1:
            raise ApplicationError('PROPOSAL_CONTROL_CHANGED')
        self.access.execute('INSERT INTO eng_proposal_control_events VALUES (?,?,?,?,?)',self._prefix()+(ref.proposal_id,updated.version,event))
        return self.get_control(ref)

    def validate_change_set(self,refs):
        if type(refs) is not tuple or not refs or len(refs)>4096:
            raise ApplicationError('INVALID_ARGUMENT')
        budget=MaterialBudget(self.access)
        result=validate_change_set(tuple(self.get_proposal(ref,budget=budget) for ref in refs),
            tuple(self.get_control(ref,budget=budget) for ref in refs))
        if result.error is not None:
            # Preserve this repository port's existing exception boundary.
            raise ReferenceError(result.error.code.value)
        return result.value

"""Frozen plans, complete review predicates and controls on the original UoW.

This adapter owns neither a connection nor authentication. Callers isolate
mutations in their active UoW, and trusted application ports admit evidence.
"""
from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.domain.artifacts.refs import (ArtifactRevisionRef)
from ordessa_engineering.domain.changes.refs import (ProposalRef)
from ordessa_engineering.domain.reviews.refs import (ReviewRef)
from ordessa_engineering.domain.common.models.values import (Digest, validate_id)
from ordessa_engineering.domain.common.models.identity import (Scope)
from ordessa_engineering.domain.common.outcomes.diagnostics import (ReferenceError)
from ordessa_engineering.domain.reviews.models import (
    ControlledReview,
    ReviewControl,
    ReviewControlExpectation,
    ReviewPlan,
    ReviewRecord,
    ReviewRequirement,
    ReviewSetExpectation,
    ReviewSetKey,
    ReviewSetSnapshot,
    ReviewRequestState,
    ReviewRequestExpectation,
)
from ordessa_engineering.domain.common.models.values import (MAX_VERSION)
from .artifact_repository import SQLiteArtifactRepository
from .material_validation import MaterialBudget
from .blob_bytes import BlobBytesError, read_bytes, validate_ref
from .acceptance_schema import ACCEPTANCE_SCHEMA_VERSION
from ordessa_engineering.domain.reviews.codec import (
    decode_control, decode_key, decode_plan, decode_record, decode_requirement,
    encode_control, encode_key, encode_plan, encode_record, encode_requirement,
)

_MAX_ROWS = 4096
_MAX_SET_BYTES = 64 * 1024 * 1024
_MAX_RAW_SET_BYTES = 64 * 1024 * 1024
# SQLite returns at most the bounded record; corrupt CHECK-bypass rows never
# materialize an unbounded BLOB in Python. Invalid types/lengths decode closed.
_BYTES = "CASE WHEN typeof(canonical_bytes)='blob' AND length(canonical_bytes)<=2097152 THEN canonical_bytes ELSE NULL END"
_KEY_BYTES = "CASE WHEN typeof(canonical_key)='blob' AND length(canonical_key)<=2097152 THEN canonical_key ELSE NULL END"


def _fail(code):
    raise ApplicationError(code)


def _version(value):
    if type(value) is not int or not 0 <= value <= MAX_VERSION:
        _fail('INVALID_ARGUMENT')


def _decode(function, raw):
    try:
        return function(raw)
    except (ReferenceError, TypeError, ValueError, OverflowError, RecursionError):
        _fail('RECORD_CORRUPT')


def _encode(function, value):
    try:
        return function(value)
    except (ReferenceError, TypeError, ValueError, OverflowError, RecursionError):
        _fail('INVALID_ARGUMENT')


class SQLiteReviewRepository:
    def __init__(self, access):
        self.access = access
        self.artifacts = SQLiteArtifactRepository(access)

    def _scope(self):
        self.access.check_active()
        scope = self.access.scope
        if type(scope) is not Scope:
            _fail('SCOPE_MISMATCH')
        return scope

    def _prefix(self):
        scope = self._scope()
        return scope.realm_id, scope.project_id

    def _scoped(self, value_scope):
        if value_scope != self._scope():
            _fail('SCOPE_MISMATCH')

    @staticmethod
    def validate_id(value):
        try:
            validate_id(value)
        except (ReferenceError, TypeError, ValueError):
            _fail('INVALID_ARGUMENT')

    def _targets(self, requirement, *, budget=None, checks=None):
        budget=MaterialBudget(self.access) if budget is None else budget
        if type(budget) is not MaterialBudget or budget.access is not self.access:
            _fail('INVALID_ARGUMENT')
        # Exact references resolve against their actual same-TX owners.
        revisions={}
        artifact_refs=tuple(t.ref for t in requirement.expected_targets.targets if type(t.ref) is ArtifactRevisionRef)
        if artifact_refs:
            revisions={r.ref:r for r in self.artifacts.resolve_graph(artifact_refs,budget=budget)}
        for target in requirement.expected_targets.targets:
            if type(target.ref) is ProposalRef:
                if getattr(self.access._connection,'_ordessa_schema_version',None) not in (7, 8, 9, 10, 11, 12, 13, ACCEPTANCE_SCHEMA_VERSION):
                    _fail('UNSUPPORTED_REFERENCE_KIND')
                from .proposal_repository import SQLiteProposalRepository
                SQLiteProposalRepository(self.access).get_proposal(target.ref,budget=budget)
            elif type(target.ref) is not ArtifactRevisionRef:
                _fail('UNSUPPORTED_REFERENCE_KIND')
        for key in requirement.required_check_keys if checks is None else checks:
            if key.claim_id is not None:
                revision=revisions.get(key.target.ref)
                if revision is None or not any(c.claim_id==key.claim_id for c in revision.claims):
                    _fail('UNSUPPORTED_CLAIM')
        return budget

    def _resolve_record(self, record, *, stored=False, verified_raw=None, budget=None):
        budget=MaterialBudget(self.access) if budget is None else budget
        try:
            if record.raw_response_ref is not None:
                try:
                    ref = validate_ref(self.access.authority_id, record.raw_response_ref)
                    identity = (ref.digest.hex, ref.byte_length)
                    budget.reserve((ref,))
                    if verified_raw is None or identity not in verified_raw:
                        read_bytes(self.access,self.access.authority_id,ref)
                        if verified_raw is not None:
                            verified_raw.add(identity)
                except BlobBytesError:
                    _fail("RECORD_CORRUPT" if stored else "REVIEW_RAW_RESPONSE_INVALID")
            self._targets(record.plan.requirement,budget=budget,checks=record.plan.check_keys)
            refs = [r for obs in record.observations for r in obs.evidence_refs]
            refs.extend(r for proof in record.applicability_proofs for r in proof.evidence_refs)
            if record.body_ref is not None:
                refs.append(record.body_ref)
            if refs:
                self.artifacts.resolve_graph(tuple(dict.fromkeys(refs)),budget=budget)
        except ApplicationError as exc:
            if stored and exc.code in {"NOT_FOUND", "UNSUPPORTED_REFERENCE_KIND", "UNSUPPORTED_CLAIM",
                                       "SCOPE_MISMATCH", "RECORD_CORRUPT"}:
                _fail("RECORD_CORRUPT")
            raise

    def _requirement(self, identifier, version):
        row = self.access.execute(
            'SELECT digest,' + _BYTES + ' FROM eng_review_requirements '
            'WHERE realm_id=? AND project_id=? AND requirement_id=? AND requirement_version=?',
            self._prefix() + (identifier, version)).fetchone()
        if row is None:
            _fail('NOT_FOUND')
        requirement = _decode(decode_requirement, row[1])
        if (requirement.scope != self._scope() or requirement.requirement_id != identifier
                or requirement.requirement_version != version or requirement.digest.hex != row[0]):
            _fail('RECORD_CORRUPT')
        return requirement, row[1]

    def get_requirement(self, identifier, requirement_version):
        self.validate_id(identifier)
        _version(requirement_version)
        if requirement_version == 0:
            _fail("INVALID_ARGUMENT")
        return self._requirement(identifier, requirement_version)[0]

    def ensure_requirement(self, requirement, *, budget=None):
        self.access.require_write()
        raw = _encode(encode_requirement, requirement)
        self._scoped(requirement.scope)
        self._targets(requirement,budget=budget)
        prefix = self._prefix()
        identity = prefix + (requirement.requirement_id, requirement.requirement_version)
        existing = self.access.execute(
            'SELECT digest,' + _BYTES + ' FROM eng_review_requirements '
            'WHERE realm_id=? AND project_id=? AND requirement_id=? AND requirement_version=?', identity).fetchone()
        if existing is None:
            self.access.execute('INSERT INTO eng_review_requirements VALUES (?,?,?,?,?,?)',
                identity + (requirement.digest.hex, raw))
            key = ReviewSetKey.for_requirement(requirement)
            self.access.execute('INSERT INTO eng_review_sets VALUES (?,?,?,?,?,?,0)',
                prefix + (key.digest.hex, requirement.requirement_id, requirement.requirement_version,
                          _encode(encode_key, key)))
        else:
            self._requirement(requirement.requirement_id, requirement.requirement_version)
            if existing != (requirement.digest.hex, raw):
                _fail('REQUIREMENT_CONFLICT')
        key = ReviewSetKey.for_requirement(requirement)
        self._set(key)
        return key

    def _set(self, key):
        if type(key) is not ReviewSetKey:
            _fail('INVALID_ARGUMENT')
        self._scoped(key.scope)
        row = self.access.execute(
            'SELECT requirement_id,requirement_version,' + _KEY_BYTES + ',set_version '
            'FROM eng_review_sets WHERE realm_id=? AND project_id=? AND set_digest=?',
            self._prefix() + (key.digest.hex,)).fetchone()
        if row is None:
            _fail('NOT_FOUND')
        stored_key = _decode(decode_key, row[2])
        requirement, _ = self._requirement(row[0], row[1])
        if (stored_key != key or ReviewSetKey.for_requirement(requirement) != key
                or type(row[3]) is not int or not 0 <= row[3] <= MAX_VERSION):
            _fail('RECORD_CORRUPT')
        return requirement, row[3]

    def create_plan(self, plan):
        self.access.require_write()
        raw = _encode(encode_plan, plan)
        self._scoped(plan.scope)
        budget=self._targets(plan.requirement,checks=plan.check_keys)
        key = self.ensure_requirement(plan.requirement,budget=budget)
        existing = self.access.execute('SELECT ' + _BYTES + ' FROM eng_review_plans '
            'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (plan.review_id,)).fetchone()
        if existing is not None:
            stored = self.get_plan(plan.review_id)
            if stored != plan or existing[0] != raw:
                _fail('REVIEW_IDENTITY_CONFLICT')
            return self.get_request(plan.review_id)
        self.access.execute('INSERT INTO eng_review_plans VALUES (?,?,?,?,?,?)',
            self._prefix() + (plan.review_id, key.digest.hex, plan.plan_digest.hex, raw))
        self.access.execute('INSERT INTO eng_review_requests VALUES (?,?,?,\'requested\',1,0)',
            self._prefix() + (plan.review_id,))
        return self.get_request(plan.review_id)

    def get_plan(self, review_id):
        self.validate_id(review_id)
        row = self.access.execute('SELECT set_digest,plan_digest,' + _BYTES + ' FROM eng_review_plans '
            'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (review_id,)).fetchone()
        if row is None:
            _fail('NOT_FOUND')
        plan = _decode(decode_plan, row[2])
        key = ReviewSetKey.for_requirement(plan.requirement)
        if (plan.review_id != review_id or plan.scope != self._scope()
                or plan.plan_digest.hex != row[1] or key.digest.hex != row[0]):
            _fail('RECORD_CORRUPT')
        requirement, _ = self._set(key)
        if plan.requirement != requirement:
            _fail('RECORD_CORRUPT')
        return plan

    def get_request(self, review_id):
        self.get_plan(review_id)
        row = self.access.execute('SELECT state,fence,version FROM eng_review_requests '
            'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (review_id,)).fetchone()
        if (row is None or row[0] not in {'requested', 'recorded', 'withdrawn'}
                or type(row[1]) is not int or not 1 <= row[1] <= MAX_VERSION
                or type(row[2]) is not int or not 0 <= row[2] <= MAX_VERSION):
            _fail('RECORD_CORRUPT')
        return ReviewRequestState(self._scope(), review_id, *row)

    def withdraw_request(self, review_id, *, expected_version, fence):
        self.access.require_write()
        _version(expected_version)
        _version(fence)
        request = self.get_request(review_id)
        if request.state != 'requested' or request.version != expected_version or request.fence != fence:
            _fail('REVIEW_REQUEST_CHANGED')
        if max(request.version, request.fence) == MAX_VERSION:
            _fail('VERSION_EXHAUSTED')
        cursor = self.access.execute('UPDATE eng_review_requests SET state=\'withdrawn\',fence=fence+1,version=version+1 '
            'WHERE realm_id=? AND project_id=? AND review_id=? AND state=\'requested\' AND fence=? AND version=?',
            self._prefix() + (review_id, fence, expected_version))
        if cursor.rowcount != 1:
            _fail('REVIEW_REQUEST_CHANGED')
        return self.get_request(review_id)

    def _bump(self, key, expected):
        if expected == MAX_VERSION:
            _fail('VERSION_EXHAUSTED')
        cursor = self.access.execute('UPDATE eng_review_sets SET set_version=set_version+1 '
            'WHERE realm_id=? AND project_id=? AND set_digest=? AND set_version=?',
            self._prefix() + (key.digest.hex, expected))
        if cursor.rowcount != 1:
            _fail('REVIEW_SET_CHANGED')

    def insert_review(self, record, *, expected_request_version, fence):
        self.access.require_write()
        raw = _encode(encode_record, record)
        self._scoped(record.plan.scope)
        _version(expected_request_version)
        _version(fence)
        plan = self.get_plan(record.plan.review_id)
        if plan != record.plan:
            _fail('REVIEW_STALE')
        existing = self.access.execute('SELECT ' + _BYTES + ' FROM eng_reviews '
            'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (plan.review_id,)).fetchone()
        if existing is not None:
            current = self.get_review(record.ref)
            if existing[0] != raw or current.record != record:
                _fail('REVIEW_IDENTITY_CONFLICT')
            return current.record.ref
        request = self.get_request(plan.review_id)
        if request.state != 'requested' or request.version != expected_request_version or request.fence != fence:
            _fail('REVIEW_REQUEST_CHANGED')
        if request.version == MAX_VERSION:
            _fail('VERSION_EXHAUSTED')
        self._resolve_record(record)
        key = ReviewSetKey.for_requirement(plan.requirement)
        _, set_version = self._set(key)
        if set_version == MAX_VERSION:
            _fail('VERSION_EXHAUSTED')
        control = ReviewControl(self._scope(), plan.review_id)
        control_bytes = _encode(encode_control, control)
        self.access.execute('INSERT INTO eng_reviews VALUES (?,?,?,?,?,?)',
            self._prefix() + (plan.review_id, key.digest.hex, record.digest.hex, raw))
        self.access.execute('INSERT INTO eng_review_controls VALUES (?,?,?,\'active\',0,?)',
            self._prefix() + (plan.review_id, control_bytes))
        self.access.execute('INSERT INTO eng_review_control_events VALUES (?,?,?,0,?)',
            self._prefix() + (plan.review_id, control_bytes))
        cursor = self.access.execute('UPDATE eng_review_requests SET state=\'recorded\',version=version+1 '
            'WHERE realm_id=? AND project_id=? AND review_id=? AND state=\'requested\' AND fence=? AND version=?',
            self._prefix() + (plan.review_id, fence, expected_request_version))
        if cursor.rowcount != 1:
            _fail('REVIEW_REQUEST_CHANGED')
        self._bump(key, set_version)
        return record.ref

    def _control(self, record):
        prefix = self._prefix() + (record.plan.review_id,)
        row = self.access.execute('SELECT state,version,' + _BYTES + ' FROM eng_review_controls '
            'WHERE realm_id=? AND project_id=? AND review_id=?', prefix).fetchone()
        if row is None:
            _fail('RECORD_CORRUPT')
        control = _decode(decode_control, row[2])
        if (control.scope != self._scope() or control.review_id != record.plan.review_id
                or (control.state, control.version) != row[:2]):
            _fail('RECORD_CORRUPT')
        # The only permitted lifecycle is active v0 -> terminal v1. History
        # and its materialized projection must agree, including their bytes.
        events = self.access.execute('SELECT version,' + _BYTES + ' FROM eng_review_control_events '
            'WHERE realm_id=? AND project_id=? AND review_id=? ORDER BY version LIMIT 3', prefix).fetchall()
        if control.version not in {0, 1} or len(events) != control.version + 1:
            _fail('RECORD_CORRUPT')
        initial = _encode(encode_control, ReviewControl(self._scope(), record.plan.review_id))
        if events[0] != (0, initial) or events[-1] != (control.version, row[2]):
            _fail('RECORD_CORRUPT')
        if control.version == 1 and control.state == 'active':
            _fail('RECORD_CORRUPT')
        return control

    def get_review(self, ref):
        return self._get_review(ref)

    def _get_review(self, ref, verified_raw=None, *, budget=None):
        if type(ref) is not ReviewRef:
            _fail('INVALID_ARGUMENT')
        self._scoped(Scope(ref.realm_id, ref.project_id))
        row = self.access.execute('SELECT set_digest,digest,' + _BYTES + ' FROM eng_reviews '
            'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (ref.review_id,)).fetchone()
        if row is None:
            _fail('NOT_FOUND')
        record = _decode(decode_record, row[2])
        if (record.plan.review_id != ref.review_id or record.plan.scope != self._scope()
                or record.digest.hex != row[1] or ReviewSetKey.for_requirement(record.plan.requirement).digest.hex != row[0]
                or record.plan != self.get_plan(ref.review_id)):
            _fail('RECORD_CORRUPT')
        self._resolve_record(record, stored=True, verified_raw=verified_raw,budget=budget)
        if record.ref != ref:
            _fail('REVIEW_IDENTITY_CONFLICT')
        request = self.get_request(ref.review_id)
        if request.state != 'recorded':
            _fail('RECORD_CORRUPT')
        return ControlledReview(record, self._control(record))

    def read_set(self, key, *, budget=None):
        budget=MaterialBudget(self.access) if budget is None else budget
        requirement, set_version = self._set(key)
        cursor = self.access.execute('SELECT review_id,digest,length(canonical_bytes) FROM eng_reviews '
            'WHERE realm_id=? AND project_id=? AND set_digest=? ORDER BY review_id LIMIT ?',
            self._prefix() + (key.digest.hex, _MAX_ROWS + 1))
        rows = cursor.fetchall()
        if (len(rows) > _MAX_ROWS or any(type(row[2]) is not int or not 0 <= row[2] <= 2097152 for row in rows)
                or sum(row[2] for row in rows) > _MAX_SET_BYTES):
            _fail('REVIEW_SET_LIMIT')
        # Before reading any response bodies, bound the distinct content set.
        # A tiny record must not multiply 2 MiB blobs into an unbounded query.
        raw_sizes = {}
        for identifier, _, _ in rows:
            body = self.access.execute('SELECT ' + _BYTES + ' FROM eng_reviews '
                'WHERE realm_id=? AND project_id=? AND review_id=?', self._prefix() + (identifier,)).fetchone()
            if body is None:
                _fail('RECORD_CORRUPT')
            record = _decode(decode_record, body[0])
            ref = record.raw_response_ref
            if ref is not None:
                previous = raw_sizes.setdefault(ref.digest.hex, ref.byte_length)
                if previous != ref.byte_length:
                    _fail('RECORD_CORRUPT')
        if sum(raw_sizes.values()) > _MAX_RAW_SET_BYTES:
            _fail('REVIEW_SET_LIMIT')
        reviews = []
        verified_raw = set()
        for identifier, digest, _ in rows:
            try:
                ref = ReviewRef(*self._prefix(), identifier, Digest('sha256', digest))
            except (ReferenceError, TypeError, ValueError):
                _fail('RECORD_CORRUPT')
            item = self._get_review(ref, verified_raw,budget=budget)
            if item.record.plan.requirement != requirement:
                _fail('RECORD_CORRUPT')
            reviews.append(item)
        try:
            return ReviewSetSnapshot(key, set_version, tuple(reviews))
        except ReferenceError:
            _fail('RECORD_CORRUPT')

    def check_expectations(self, sets=(), controls=(), requests=()):
        budget=MaterialBudget(self.access)
        if (type(sets) is not tuple or type(controls) is not tuple
                or any(type(item) is not ReviewSetExpectation for item in sets)
                or any(type(item) is not ReviewControlExpectation for item in controls)
                or len({item.key for item in sets}) != len(sets)
                or len({item.review_ref for item in controls}) != len(controls)):
            _fail('INVALID_ARGUMENT')
        if (type(requests) is not tuple or len(requests) > _MAX_ROWS
                or any(type(item) is not ReviewRequestExpectation for item in requests)
                or len({item.review_id for item in requests}) != len(requests)):
            _fail('INVALID_ARGUMENT')
        for item in requests:
            if item.scope != self._scope():
                _fail('SCOPE_MISMATCH')
            plan = self.get_plan(item.review_id)
            request = self.get_request(item.review_id)
            if (plan.plan_digest != item.expected_plan_digest
                    or request.version != item.expected_request_version
                    or request.fence != item.expected_fence
                    or request.state != item.expected_state):
                _fail('REVIEW_REQUEST_CHANGED')
        for item in sets:
            if self.read_set(item.key,budget=budget).set_version != item.set_version:
                _fail('REVIEW_SET_CHANGED')
        for item in controls:
            if self._get_review(item.review_ref,budget=budget).control.version != item.version:
                _fail('REVIEW_CONTROL_CHANGED')

    def control_group(self, expectations, *, state, reason, evidence, replacement_ref=None):
        """Trusted control command; all members change or caller rolls back."""
        self.access.require_write()
        if (type(expectations) is not tuple or not expectations or len(expectations) > _MAX_ROWS
                or any(type(item) is not ReviewControlExpectation for item in expectations)
                or len({item.review_ref for item in expectations}) != len(expectations)
                or type(state) is not str or state not in {'voided', 'replaced'}):
            _fail('INVALID_ARGUMENT')
        budget=MaterialBudget(self.access)
        originals = tuple(self._get_review(item.review_ref,budget=budget) for item in expectations)
        requirement = originals[0].record.plan.requirement
        if any(item.record.plan.requirement != requirement for item in originals):
            _fail('REVIEW_STALE')
        key = ReviewSetKey.for_requirement(requirement)
        _, set_version = self._set(key)
        if set_version == MAX_VERSION:
            _fail('VERSION_EXHAUSTED')
        if state == 'replaced':
            replacement = self._get_review(replacement_ref,budget=budget)
            if (replacement.record.plan.requirement != requirement or replacement.control.state != 'active'
                    or replacement_ref in {item.review_ref for item in expectations}):
                _fail('REVIEW_STALE')
        elif replacement_ref is not None:
            _fail('INVALID_ARGUMENT')
        mutations = []
        for expected, original in zip(expectations, originals):
            control = original.control
            if control.state != 'active' or control.version != expected.version:
                _fail('REVIEW_CONTROL_CHANGED')
            try:
                new_control = ReviewControl(self._scope(), control.review_id, state,
                    replacement_ref, reason, evidence, control.version + 1)
            except (ReferenceError, TypeError, ValueError):
                _fail('INVALID_ARGUMENT')
            mutations.append((control, new_control, _encode(encode_control, new_control)))
        for old, new, raw in mutations:
            self.access.execute('INSERT INTO eng_review_control_events VALUES (?,?,?,?,?)',
                self._prefix() + (old.review_id, new.version, raw))
            cursor = self.access.execute('UPDATE eng_review_controls SET state=?,version=?,canonical_bytes=? '
                'WHERE realm_id=? AND project_id=? AND review_id=? AND state=\'active\' AND version=?',
                (new.state, new.version, raw) + self._prefix() + (old.review_id, old.version))
            if cursor.rowcount != 1:
                _fail('REVIEW_CONTROL_CHANGED')
        self._bump(key, set_version)
        return self.read_set(key,budget=budget)

"""Additive schema3; original schema2 tables retain their bytes and identities."""
SNAPSHOT_SCHEMA_VERSION = 3
SNAPSHOT_DDL = """
CREATE TABLE eng_method_blobs (
  digest TEXT PRIMARY KEY,
  byte_length INTEGER NOT NULL CHECK (byte_length >= 0),
  body BLOB NOT NULL CHECK (length(body) = byte_length)
);
CREATE TABLE eng_method_snapshots (
  snapshot_digest TEXT PRIMARY KEY,
  canonical_bytes BLOB NOT NULL
);
CREATE TABLE eng_method_releases (
  method_id TEXT NOT NULL,
  release_version TEXT NOT NULL,
  schema_version INTEGER NOT NULL CHECK (schema_version > 0),
  snapshot_digest TEXT NOT NULL REFERENCES eng_method_snapshots(snapshot_digest),
  PRIMARY KEY (method_id, release_version)
);
CREATE TABLE eng_schema_migrations (
  target_version INTEGER PRIMARY KEY,
  source_digest TEXT NOT NULL,
  backup_sha256 TEXT NOT NULL,
  backup_path TEXT NOT NULL
);
"""

"""Strict snapshot DTO codec; source bytes and host trust belong to the store."""
from __future__ import annotations

from dataclasses import asdict, fields
import re

from ordessa_infrastructure.encoding import canonical_bytes, decode_json

from ....methods.definitions.models.identity import method_digest
from ....methods.compilation.encoding import (
    stored_program_from_canonical, program_to_canonical, program_plan_digest, program_encoding,
)
from ....methods.definitions.errors import MethodError, MethodFailure
from ....methods.definitions.models import (
    BlobRef, MethodIdentity, MethodSnapshot, ResourceSnapshot, StoredSourceBundle, StoredSnapshot,
)
from ....methods.definitions.models.compiled import StoredProgram
from ....methods.validation.references import validate_logical_path


_VERSION = "engineering-method-snapshot/1"
_SNAPSHOT_FIELDS = {"identity", "engine_contract_version", "manifest_ref", "resources", "workflow", "document_specs", "standard_specs", "decision_specs", "skill_snapshots", "compiler_version", "compiled_plan_digest", "compiled_plan", "snapshot_digest"}
_RESOURCE_FIELDS = {"resource_id", "logical_path", "media_type", "byte_length", "digest", "blob_ref"}
_COMPILED_FIELDS = {"compiler_version", "plan_digest", "program"}
_SHA256 = re.compile(r"[0-9a-f]{64}\Z")
_PROGRAM_FIELDS = {
    "schema_version", "compiler_version", "workflow", "documents", "standards",
    "decision_templates", "skill_resources", "capability_bindings",
}
_PROJECTIONS = {
    "document_specs": "documents", "standard_specs": "standards",
    "decision_specs": "decision_templates", "skill_snapshots": "skill_resources",
}


def _invalid() -> MethodFailure:
    return MethodFailure(MethodError(
        "SNAPSHOT_CODEC_INVALID", "method snapshot encoding or identity is invalid",
    ))


def _object(value, expected=None):
    if type(value) is not dict or (expected is not None and set(value) != expected):
        raise _invalid()
    return value


def _dto_object(value, cls):
    return _object(value, {field.name for field in fields(cls)})


def _text(value):
    # Method/resource IDs have no additional regex in the current loader.
    if type(value) is not str or not value.strip():
        raise _invalid()
    return value


def _digest(value):
    if type(value) is not str or _SHA256.fullmatch(value) is None:
        raise _invalid()
    return value


def _integer(value, minimum):
    if type(value) is not int or value < minimum:
        raise _invalid()
    return value


def _objects(value):
    if type(value) is not list:
        raise _invalid()
    for item in value:
        _object(item)
    return value


def _blob(value):
    value = _dto_object(value, BlobRef)
    return BlobRef(
        _digest(value["digest"]), _integer(value["byte_length"], 0),
        _text(value["media_type"]), _text(value["storage_object_id"]),
    )


def _decode(envelope):
    envelope = _object(envelope, {"codec_version", "snapshot"})
    if envelope["codec_version"] != _VERSION:
        raise _invalid()
    value = _object(envelope["snapshot"], _SNAPSHOT_FIELDS)
    identity = _dto_object(value["identity"], MethodIdentity)
    identity = MethodIdentity(
        _text(identity["method_id"]), _text(identity["release_version"]),
        _integer(identity["schema_version"], 1),
    )
    if value["engine_contract_version"] != "ordessa.methods/v1":
        raise _invalid()
    manifest = _blob(value["manifest_ref"])
    if manifest.media_type != "application/yaml":
        raise _invalid()
    resources = []
    ids, paths = set(), set()
    for resource in _objects(value["resources"]):
        resource = _object(resource, _RESOURCE_FIELDS)
        resource_id = _text(resource["resource_id"])
        path = validate_logical_path(_text(resource["logical_path"]))
        # The loader rejects case-insensitive path collisions too.
        if resource_id in ids or path.casefold() in paths:
            raise _invalid()
        ids.add(resource_id)
        paths.add(path.casefold())
        blob = _blob(resource["blob_ref"])
        digest = _digest(resource["digest"])
        size = _integer(resource["byte_length"], 0)
        media_type = _text(resource["media_type"])
        if (blob.digest, blob.byte_length, blob.media_type) != (digest, size, media_type):
            raise _invalid()
        resources.append(ResourceSnapshot(resource_id, path, blob))

    compiled = _object(value["compiled_plan"], _COMPILED_FIELDS)
    compiler = _text(value["compiler_version"])
    plan_digest = _digest(value["compiled_plan_digest"])
    program = _object(compiled["program"])
    fields = _PROGRAM_FIELDS | ({"schema_resources"} if program.get("schema_version") == 2 else set())
    program = _object(program, fields)
    if (_integer(program["schema_version"], 1) not in (1, 2)
            or compiled["compiler_version"] != compiler
            or program["compiler_version"] != compiler
            or _digest(compiled["plan_digest"]) != plan_digest
            or method_digest("compiled-method-program", program) != plan_digest):
        raise _invalid()
    workflow = _object(value["workflow"])
    if workflow != _object(program["workflow"]):
        raise _invalid()
    projections = {}
    for snapshot_key, program_key in _PROJECTIONS.items():
        items = _objects(value[snapshot_key])
        if items != _objects(program[program_key]):
            raise _invalid()
        projections[snapshot_key] = tuple(items)
    capabilities = _objects(program["capability_bindings"])
    capability_ids = set()
    for capability in capabilities:
        _object(capability, {"capability_id", "kind", "interface_version", "contract_digest"})
        capability_id = _text(capability["capability_id"])
        if capability_id in capability_ids or capability["kind"] not in {"operation", "check"}:
            raise _invalid()
        capability_ids.add(capability_id)
        _text(capability["interface_version"])
        _digest(capability["contract_digest"])
    if [item["capability_id"] for item in capabilities] != sorted(capability_ids):
        raise _invalid()
    snapshot_digest = _digest(value["snapshot_digest"])
    expected_digest = method_digest("method-snapshot", {
        "schema_version": identity.schema_version,
        "method_id": identity.method_id,
        "release_version": identity.release_version,
        "manifest_sha256": manifest.digest,
        "resource_digests": [
            {"id": item.resource_id, "sha256": item.digest}
            for item in sorted(resources, key=lambda item: item.resource_id)
        ],
        "required_capabilities": capabilities,
        "compiler_version": compiler,
        "compiled_plan_digest": {"algorithm": "sha256", "hex": plan_digest},
    })
    if expected_digest != snapshot_digest:
        raise _invalid()
    return StoredSnapshot(StoredSourceBundle(identity, manifest, tuple(resources)), stored_program_from_canonical(program), snapshot_digest)


def encode_snapshot(snapshot: MethodSnapshot) -> bytes:
    """Encode a detached, internally consistent snapshot as canonical JSON."""
    try:
        if type(snapshot) not in (MethodSnapshot, StoredSnapshot):
            raise _invalid()
        if type(snapshot.source_bundle) is not StoredSourceBundle or type(snapshot.manifest_ref) is not BlobRef:
            raise _invalid()
        program = program_encoding(snapshot.program)
        canonical_program = program_to_canonical(program)
        value = {
            "identity": asdict(snapshot.identity), "engine_contract_version": snapshot.engine_contract_version,
            "manifest_ref": asdict(snapshot.manifest_ref),
            "resources": [{"resource_id": r.resource_id, "logical_path": r.logical_path, "media_type": r.media_type,
                "byte_length": r.byte_length, "digest": r.digest, "blob_ref": asdict(r.blob_ref)} for r in snapshot.resources],
            "workflow": canonical_program["workflow"],
            **{key: list(canonical_program[field]) for key, field in _PROJECTIONS.items()},
            "compiler_version": snapshot.compiler_version, "compiled_plan_digest": program_plan_digest(snapshot.program),
            "compiled_plan": {"compiler_version": program.compiler_version, "plan_digest": program_plan_digest(program), "program": canonical_program},
            "snapshot_digest": snapshot.snapshot_digest,
        }
        raw = canonical_bytes({"codec_version": _VERSION, "snapshot": value})
        _decode(decode_json(raw))
        return raw
    except (MethodFailure, ValueError, TypeError, KeyError, AttributeError, RecursionError, OverflowError):
        raise _invalid() from None


def decode_snapshot(raw: bytes) -> StoredSnapshot:
    """Decode a lossless immutable stored representation; no source materialization or IO."""
    try:
        if type(raw) is not bytes:
            raise _invalid()
        envelope = decode_json(raw)
        if canonical_bytes(envelope) != raw:
            raise _invalid()
        return _decode(envelope)
    except (MethodFailure, ValueError, TypeError, KeyError, AttributeError, RecursionError, OverflowError):
        raise _invalid() from None


__all__ = ["encode_snapshot", "decode_snapshot"]

"""Immutable method publication on the sole EngineeringLibrary connection.

Source integrity is checked here; capability admission belongs to the injected
application catalog at freeze_method. This adapter does not invent a catalog.
"""
from __future__ import annotations

import re
import sqlite3
from contextlib import contextmanager
from pathlib import Path

from ordessa_engineering.methods.compilation.compiler import bind_program
from ordessa_engineering.methods.compilation.encoding import program_to_canonical
from ordessa_engineering.application.orchestration.method_snapshot import verify_stored_snapshot_source
from ordessa_engineering.methods.definitions.errors import MethodError, MethodFailure
from ordessa_engineering.methods.definitions.models import (
    BlobRef, LoadedMethod, MethodRef, MethodSnapshot, MethodSource,
    ResourceBytes, CapturedResource, SourceBundle, StoredSnapshot, StoredSourceBundle,
)
from ordessa_engineering.methods.loading.captured import captured_manifest, parse_captured_resource
from ordessa_engineering.domain.common.outcomes.library_failures import EngineeringError
from .engineering_library import EngineeringLibrary
from .schema import SNAPSHOT_SCHEMA_VERSION
from .historical_method_program import reconstruct_historical_program_v1
