class _RollbackOnly(Exception):
    pass


def _read_cleanup_error(library, primary):
    error = ApplicationError("TRANSACTION_UNCERTAIN", retry="reconcile")
    error.primary = primary
    try:
        library.close()
    except BaseException as close_error:
        error.close_error = close_error
    finally:
        library._closed = True
    return error


class _RepositoryAccess:
    def __init__(self, connection, scope, mode, authority_id):
        self._connection = connection
        self.scope = scope
        self.authority_id = authority_id
        self._mode = mode
        self._thread = threading.get_ident()
        self._active = True

    def check_active(self):
        if not self._active or threading.get_ident() != self._thread:
            raise ApplicationError("UOW_NOT_ACTIVE")
        try:
            active = self._connection.in_transaction
        except sqlite3.DatabaseError:
            raise ApplicationError("UOW_NOT_ACTIVE") from None
        if not active:
            raise ApplicationError("UOW_NOT_ACTIVE")

    def require_write(self):
        self.check_active()
        if self._mode != "write":
            raise ApplicationError("READ_ONLY_UOW")

    def execute(self, sql, parameters=()):
        self.check_active()
        try:
            return self._connection.execute(sql, parameters)
        except sqlite3.IntegrityError as exc:
            raise ApplicationError("STORAGE_CONSTRAINT") from exc
        except sqlite3.DatabaseError as exc:
            raise ApplicationError("STORAGE_UNAVAILABLE", retry="reconcile") from exc


@contextmanager
def _read_transaction(library):
    with library._read_connection() as connection:
        if connection.in_transaction:
            raise ApplicationError("UOW_NESTED")
        previous = connection.execute("PRAGMA query_only").fetchone()[0]
        primary = None
        try:
            # SQLite itself enforces no writes, including accidental adapter
            # SQL that bypasses the public repository require_write guard.
            connection.execute("PRAGMA query_only=ON")
            connection.execute("BEGIN")
            yield connection
            library._check_bound_state(allow_journal=True)
        except BaseException as exc:
            primary = exc
            library._rollback_failure(exc)
            raise
        else:
            try:
                connection.rollback()
            except BaseException as exc:
                primary = exc
                library._rollback_failure(exc)
                raise _read_cleanup_error(library, primary) from exc
        finally:
            if not library._closed:
                try:
                    connection.execute("PRAGMA query_only=" + str(int(previous)))
                except BaseException as cleanup:
                    raise _read_cleanup_error(library, primary) from cleanup


class SQLiteUoWFactory:
    def __init__(self, library: EngineeringLibrary):
        if not isinstance(library, EngineeringLibrary):
            raise ApplicationError("UOW_AUTHORITY_REQUIRED")
        with library._read_connection():
            if library._schema_version not in {APPLICATION_SCHEMA_VERSION, REVIEW_SCHEMA_VERSION, MATERIAL_SCHEMA_VERSION, PROPOSAL_SCHEMA_VERSION, AUTHORIZATION_SCHEMA_VERSION, APPLY_SCHEMA_VERSION, METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION}:
                raise ApplicationError("APPLICATION_SCHEMA_REQUIRED")
        self.library = library
        self.authority_id = library.library_id

    def begin(self, scope: Scope, mode: str = "write"):
        if type(scope) is not Scope or type(mode) is not str or mode not in {"read", "write"}:
            raise ApplicationError("INVALID_ARGUMENT")
        return SQLiteEngineeringUoW(self.library, scope, mode)

    def begin_effect_cut(self, scope: Scope):
        """Same original authority/connection, fail-fast writable acquisition."""
        if type(scope) is not Scope:
            raise ApplicationError("INVALID_ARGUMENT")
        return SQLiteEngineeringUoW(self.library, scope, "write", effect_cut=True)


class SQLiteEngineeringUoW:
    def __init__(self, library, scope, mode, *, effect_cut=False):
        if not isinstance(library, EngineeringLibrary):
            raise ApplicationError("UOW_AUTHORITY_REQUIRED")
        if type(scope) is not Scope or type(mode) is not str or mode not in {"read", "write"}:
            raise ApplicationError("INVALID_ARGUMENT")
        self._library = library
        self.scope = scope
        self.authority_id = library.library_id
        self._mode = mode
        self._effect_cut = effect_cut
        self._manager = None
        self._access = None
        self._done = False
        self._savepoint = False
        self._poison = None

    def __enter__(self):
        if self._manager is not None or self._done:
            raise ApplicationError("UOW_REUSED")
        self._manager = self._library.transaction(nonblocking=self._effect_cut) if self._mode == "write" else _read_transaction(self._library)
        entered = False
        try:
            connection = self._manager.__enter__()
            entered = True
            self._access = _RepositoryAccess(connection, self.scope, self._mode, self.authority_id)
            from .artifact_repository import SQLiteArtifactRepository
            from .command_journal import SQLiteCommandJournal
            self.engineering = SQLiteArtifactRepository(self._access)
            self.commands = SQLiteCommandJournal(self._access)
            from .method_repository import SQLiteMethodRepository
            self._methods = SQLiteMethodRepository(self._access) if self._library._schema_version in (METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION) else None
            fences = getattr(self._library, "_method_guard_fences", None)
            for control, selection in getattr(fences, "values", ()):
                if self._methods is None:
                    raise ApplicationError("METHOD_CONTROL_SCHEMA_REQUIRED")
                self._methods.check_guard(control, selection)
            self._reviews = None
            self._proposals = None
            self._authorization = None
            if self._library._schema_version in (AUTHORIZATION_SCHEMA_VERSION, APPLY_SCHEMA_VERSION, METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
                from .authorization_repository import SQLiteAuthorizationRepository
                self._authorization = SQLiteAuthorizationRepository(self._access)
            if self._library._schema_version in (PROPOSAL_SCHEMA_VERSION, AUTHORIZATION_SCHEMA_VERSION, APPLY_SCHEMA_VERSION, METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
                from .proposal_repository import SQLiteProposalRepository
                self._proposals = SQLiteProposalRepository(self._access)
            if self._library._schema_version in (REVIEW_SCHEMA_VERSION, MATERIAL_SCHEMA_VERSION, PROPOSAL_SCHEMA_VERSION, AUTHORIZATION_SCHEMA_VERSION, APPLY_SCHEMA_VERSION, METHOD_SCHEMA_VERSION, IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION):
                from .review_repository import SQLiteReviewRepository
                self._reviews = SQLiteReviewRepository(self._access)
            from .implementation_repository import SQLiteImplementationRepository
            from .dispatch_repository import SQLiteDispatchRepository
            from .workflow_transactions import _TransactionScope
            self._workflow = _TransactionScope(self._library, connection)
            self._dispatch = SQLiteDispatchRepository(self._access) if self._library._schema_version in (DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION) else None
            self._submissions = SQLiteSubmissionRepository(self._access) if self._library._schema_version in (SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION) else None
            self._implementation = SQLiteImplementationRepository(self._access) if self._library._schema_version in (IMPLEMENTATION_SCHEMA_VERSION, SUBMISSION_SCHEMA_VERSION, DISPATCH_SCHEMA_VERSION, ACCEPTANCE_SCHEMA_VERSION) else None
            from .acceptance_repository import SQLiteAcceptanceRepository
            self._acceptance = SQLiteAcceptanceRepository(self._access) if self._library._schema_version == ACCEPTANCE_SCHEMA_VERSION else None
            return self
        except BaseException as exc:
            try:
                if entered:
                    try:
                        self._manager.__exit__(type(exc), exc, exc.__traceback__)
                    except EngineeringError as cleanup:
                        code = "COMMIT_UNKNOWN" if cleanup.code == "library_rollback_failed" else "STORAGE_UNAVAILABLE"
                        raise ApplicationError(code, retry="reconcile") from cleanup
            finally:
                # Cleanup itself may fail. Leaked repository handles must
                # remain invalid and this failed UoW must never be reusable.
                if self._access is not None:
                    self._access._active = False
                self._done = True
            if isinstance(exc, EngineeringError):
                code = ("EFFECT_WRITE_BUSY" if exc.code == "library_effect_busy" else
                        "UOW_NESTED" if exc.code == "library_transaction_nested" else "STORAGE_UNAVAILABLE")
                raise ApplicationError(code) from exc
            raise

    @property
    def workflow(self):
        self._access.check_active()
        return self._workflow

    @property
    def dispatch(self):
        self._access.check_active()
        if self._dispatch is None:
            raise ApplicationError('DISPATCH_SCHEMA_REQUIRED')
        return self._dispatch

    @property
    def implementation(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._implementation is None:
            raise ApplicationError('IMPLEMENTATION_SCHEMA_REQUIRED')
        return self._implementation

    @property
    def submissions(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._submissions is None:
            raise ApplicationError('SUBMISSION_SCHEMA_REQUIRED')
        return self._submissions

    @property
    def acceptance(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._acceptance is None:
            raise ApplicationError('ACCEPTANCE_SCHEMA_REQUIRED')
        return self._acceptance

    @property
    def methods(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._methods is None:
            raise ApplicationError('METHOD_CONTROL_SCHEMA_REQUIRED')
        return self._methods

    @property
    def authorization(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._authorization is None:
            raise ApplicationError('AUTHORIZATION_SCHEMA_REQUIRED')
        return self._authorization

    @property
    def reviews(self):
        if self._access is None:
            raise ApplicationError("UOW_NOT_ACTIVE")
        self._access.check_active()
        if self._reviews is None:
            raise ApplicationError("REVIEW_SCHEMA_REQUIRED")
        return self._reviews

    @property
    def proposals(self):
        if self._access is None:
            raise ApplicationError('UOW_NOT_ACTIVE')
        self._access.check_active()
        if self._proposals is None:
            raise ApplicationError('PROPOSAL_SCHEMA_REQUIRED')
        return self._proposals

    def _finish(self, error=None):
        if self._done or self._access is None:
            raise ApplicationError("UOW_NOT_ACTIVE")
        if threading.get_ident() != self._access._thread:
            raise ApplicationError("UOW_NOT_ACTIVE")
        if self._savepoint:
            raise ApplicationError("UOW_SAVEPOINT_ACTIVE")
        poison = self._poison
        try:
            if error is None and poison is not None:
                self._manager.__exit__(type(poison), poison, poison.__traceback__)
                raise ApplicationError("TRANSACTION_UNCERTAIN", retry="reconcile") from poison
            if error is None:
                self._manager.__exit__(None, None, None)
            else:
                self._manager.__exit__(type(error), error, error.__traceback__)
        except EngineeringError as exc:
            if exc.code in {"library_commit_unknown", "library_rollback_failed"}:
                raise ApplicationError("COMMIT_UNKNOWN", retry="reconcile") from exc
            raise ApplicationError("STORAGE_UNAVAILABLE", retry="reconcile") from exc
        finally:
            self._done = True
            self._access._active = False

    def commit(self):
        self._finish()

    def rollback(self):
        self._finish(_RollbackOnly())

    def _poison_transaction(self, error):
        self._poison = error
        self._access._active = False

    @contextmanager
    def isolate(self):
        """Rollback refused mutations; uncertain savepoints poison the whole UoW."""
        if self._access is None:
            raise ApplicationError("UOW_NOT_ACTIVE")
        self._access.require_write()
        if self._savepoint:
            raise ApplicationError("UOW_SAVEPOINT_NESTED")
        try:
            self._access.execute("SAVEPOINT engineering_mutation")
        except BaseException as exc:
            self._poison_transaction(exc)
            raise ApplicationError("TRANSACTION_UNCERTAIN", retry="reconcile") from exc
        self._savepoint = True
        try:
            yield
        except BaseException as primary:
            try:
                self._access.execute("ROLLBACK TO engineering_mutation")
                self._access.execute("RELEASE engineering_mutation")
            except BaseException as cleanup:
                error = ApplicationError("TRANSACTION_UNCERTAIN", retry="reconcile")
                error.primary = primary
                self._poison_transaction(error)
                raise error from cleanup
            raise
        else:
            try:
                self._access.execute("RELEASE engineering_mutation")
            except BaseException as exc:
                self._poison_transaction(exc)
                raise ApplicationError("TRANSACTION_UNCERTAIN", retry="reconcile") from exc
        finally:
            self._savepoint = False

    def __exit__(self, exc_type, exc, tb):
        if not self._done:
            self._finish(exc or _RollbackOnly())
        return False

"""Adapter unit-of-work provider for the original engineering library transaction.

This module opens the **same original** library transaction and exposes only
transaction-scoped storage primitives (via ``_TransactionScope``). It holds no
run/review/apply business decision, does not import application use-cases, and
does not create a second UoW implementation. The application opens this UoW and
coordinates business inside the scope.
"""
from __future__ import annotations

from contextlib import contextmanager

from ordessa_engineering.domain.artifacts.library_material_codec import (
    canonical_json, material_ref_to_dict,
)


class _TransactionScope:
    """The application ``TransactionScope`` bound to the live connection."""

    def __init__(self, library, connection):
        self._library = library
        self._connection = connection

    # reads (same original transaction/connection) -----------------------------
    def read(self, ref):
        return self._library.read(ref)

    def require_current(self, ref):
        return self._library.require_current(self._connection, ref)

    def head_ref(self, kind, stable_id):
        return self._library.head(kind, stable_id)

    def head_revision(self, kind, stable_id):
        return self._connection.execute(
            "SELECT revision, digest FROM heads WHERE kind=? AND stable_id=?",
            (kind, stable_id)).fetchone()

    def run_row(self, run_id):
        return self._library.run_row(run_id)

    def idempotency_row(self, operation_id):
        return self._connection.execute(
            "SELECT payload_digest, receipt_ref_json FROM idempotency WHERE operation_id=?",
            (operation_id,)).fetchone()

    def next_step_ordinal(self, run_id):
        return self._connection.execute(
            "SELECT COALESCE(MAX(ordinal), -1) + 1 FROM step_log WHERE run_id=?", (run_id,)).fetchone()[0]

    # atomic write primitives --------------------------------------------------
    def write_material(self, *, kind, stable_id, revision, body, generated):
        return self._library._write_material(self._connection, kind=kind, stable_id=stable_id,
                                             revision=revision, body=body, generated=generated)

    def create_generated(self, *, kind, stable_id, body):
        return self._library._create_generated(self._connection, kind=kind, stable_id=stable_id, body=body)

    def insert_idempotency(self, operation_id, payload_digest, ref):
        self._connection.execute(
            "INSERT INTO idempotency VALUES (?, ?, ?)",
            (operation_id, payload_digest, canonical_json(material_ref_to_dict(ref))))

    def insert_run(self, *, run_id, method_ref, registry_ref, inputs, now):
        self._connection.execute(
            "INSERT INTO runs VALUES (?, ?, ?, ?, 'RUNNING', 0, NULL, ?, ?)",
            (run_id, canonical_json(material_ref_to_dict(method_ref)), canonical_json(registry_ref),
             canonical_json(inputs), now, now))

    def insert_step_log(self, *, run_id, ordinal, step_id, operation, attempt, status, receipt_ref):
        self._connection.execute(
            "INSERT INTO step_log (run_id,ordinal,step_id,operation,attempt,status,receipt_ref_json) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (run_id, ordinal, step_id, operation, attempt, status, canonical_json(material_ref_to_dict(receipt_ref))))

    def replace_run_inputs(self, *, run_id, expected_inputs, inputs):
        from ordessa_engineering.application.contracts.errors import ApplicationError
        cursor = self._connection.execute(
            'UPDATE runs SET input_json=? WHERE run_id=? AND input_json=?',
            (canonical_json(inputs), run_id, canonical_json(expected_inputs)))
        if cursor.rowcount != 1:
            raise ApplicationError('RUN_WAIT_CHANGED')

    def update_run(self, *, run_id, status, cursor, wait_reason, now):
        if cursor is None:
            self._connection.execute(
                "UPDATE runs SET status=?, wait_reason=?, updated_at=? WHERE run_id=?",
                (status, wait_reason, now, run_id))
        else:
            self._connection.execute(
                "UPDATE runs SET status=?, cursor=?, wait_reason=?, updated_at=? WHERE run_id=?",
                (status, cursor, wait_reason, now, run_id))


class WorkflowTransactions:
    """Adapter implementation of the application ``UnitOfWork`` port."""

    def __init__(self, library):
        self.library = library

    @contextmanager
    def open(self):
        with self.library.transaction() as connection:
            yield _TransactionScope(self.library, connection)

    def transaction_scope(self, connection):
        """Bind a scope to an already-open connection (used inside ``open`` and by callers)."""
        return _TransactionScope(self.library, connection)

"""Finite application entry point over the existing command/UoW owners.

Composition supplies authentication and control admission. No method policy,
dynamic handler lookup, legacy workflow fallback or second journal lives here.
The async surface follows E6; handlers currently perform bounded synchronous
SQLite work and never suspend with an open transaction.
"""
from ..usecases.artifacts import ArtifactUseCases, input_schema as artifact_schema
from ..usecases.changes.proposals import ProposalUseCases, input_schema as proposal_schema
from ordessa_engineering.application.contracts.commands import CommandContext
from ordessa_engineering.application.contracts.errors import ApplicationError
from ..usecases.queries.service import EngineeringQueries, SUPPORTED_QUERIES as OWNER_QUERIES
from ..usecases.queries.run_waits import CurrentRunWaitUseCases
from ..usecases.queries.method_work import CurrentMethodWorkUseCases, CurrentMethodWorkBindings
from ..usecases.reviews.service import ReviewUseCases, input_schema as review_schema, command_input_schema as review_command_schema
from ..usecases.approvals.service import ApprovalUseCases, SUPPORTED_APPROVAL_COMMANDS, input_schema as approval_schema
from ..usecases.changes.apply import ChangeApplyUseCases
from ..usecases.changes.acceptance_adopt import AcceptanceUseCases
from ..usecases.changes.submissions import SubmissionUseCases
from ..contracts.submissions import report_input_schema
from ..contracts.commands import ReadSet
from ...domain.changes.submission_codec import decode_submission
from ...domain.changes.dispatch_codec import decode_dispatch
from ordessa_infrastructure.encoding import canonical_bytes
from ..contracts.implementation_routes import IMPLEMENTATION_COMMANDS, IMPLEMENTATION_QUERIES


SUPPORTED_COMMANDS = (
    "engineering.artifacts.create",
    "engineering.artifacts.append_revision",
    "engineering.proposals.create",
    "engineering.proposals.withdraw",
    "engineering.proposals.supersede",
    "engineering.reviews.request",
    "engineering.reviews.record",
    "engineering.submissions.record_report",
) + SUPPORTED_APPROVAL_COMMANDS

SUPPORTED_QUERIES = OWNER_QUERIES + (
    "engineering.work.get", "engineering.work.current_condition", "engineering.runs.get_wait",
)

_ARTIFACT_COMMANDS = frozenset({
    "engineering.artifacts.create",
    "engineering.artifacts.append_revision",
})
_PROPOSAL_COMMANDS = frozenset({
    "engineering.proposals.create",
    "engineering.proposals.withdraw",
    "engineering.proposals.supersede",
})
_REVIEW_COMMANDS = frozenset({
    "engineering.reviews.request",
    "engineering.reviews.record",
})


class EngineeringService:
    supported_commands = SUPPORTED_COMMANDS
    supported_queries = SUPPORTED_QUERIES
    conditional_commands = IMPLEMENTATION_COMMANDS
    conditional_queries = IMPLEMENTATION_QUERIES

    @staticmethod
    def operation_capabilities():
        """Detached descriptions of actual handlers, never access grants.

        Binding these descriptions to a published method is the registered
        catalog owner's responsibility; this service does not publish a method.
        """
        from ..orchestration.method_bridge import command_capabilities
        return command_capabilities()

    def __init__(self, factory, access, *, proposal_control_admission=None,
                 review_admission=None, review_control=None, blobs=None, conversation_admission=None,
                 acceptance_admission=None, submission_source=None, current_wait_bindings=None,
                 submission_report_source=None, execution_records=None, execution_query_factory=None,
                 implementation_routes=None):
        if implementation_routes is not None and (
                getattr(implementation_routes, "factory", None) is not factory
                or getattr(implementation_routes, "access", None) is not access
                or not callable(getattr(implementation_routes, "invoke", None))):
            raise ApplicationError("IMPLEMENTATION_AUTHORITY_MISMATCH")
        self._implementation_routes = implementation_routes
        self._access = access
        self._blobs = blobs
        artifacts = ArtifactUseCases(factory, access)
        proposals = ProposalUseCases(factory, access, proposal_control_admission)
        reviews = ReviewUseCases(factory, access, review_admission, review_control, blobs=blobs)
        approvals = ApprovalUseCases(factory, access, conversation_admission, review_admission)
        changes = ChangeApplyUseCases(factory, access, conversation_admission, review_admission)
        acceptance = AcceptanceUseCases(factory, access, conversation_admission, review_admission,
            acceptance_admission=acceptance_admission, submission_source=submission_source)
        self._waits = CurrentRunWaitUseCases(factory, access, current_wait_bindings, review_admission)
        self._work = CurrentMethodWorkUseCases(factory, access,
            current_wait_bindings if type(current_wait_bindings) is CurrentMethodWorkBindings else None)
        self._factory = factory
        self._execution_records = execution_records
        self._execution_query_factory = execution_query_factory
        self._submission_reports = SubmissionUseCases(factory, access, approval_usecases=approvals,
            report_source=submission_report_source)
        self._commands = {
            "engineering.submissions.record_report": self._record_report,
            "engineering.work.start": self._work.start,
            "engineering.work.record_command_step": self._work.record_command_step,
            "engineering.runs.resume": self._waits.resume,
            "engineering.acceptance.adopt": acceptance.adopt,
            "engineering.changes.apply": changes.apply,
            "engineering.artifacts.create": artifacts.create,
            "engineering.artifacts.append_revision": artifacts.append_revision,
            "engineering.proposals.create": proposals.create,
            "engineering.proposals.withdraw": proposals.withdraw,
            "engineering.proposals.supersede": proposals.supersede,
            "engineering.reviews.request": reviews.request,
            "engineering.reviews.record": reviews.record_command,
            "engineering.notices.publish": approvals.publish_notice,
            "engineering.approvals.prepare_intent": approvals.prepare_intent,
            "engineering.approvals.request": approvals.request,
            "engineering.approvals.record_conversation": approvals.record_conversation,
            "engineering.approvals.revoke": approvals.revoke,
        }
        self._queries = EngineeringQueries(factory, access)

    @staticmethod
    def input_schema(operation):
        if type(operation) is not str or operation not in SUPPORTED_COMMANDS:
            raise ApplicationError("OPERATION_UNAVAILABLE")
        if operation == "engineering.submissions.record_report":
            return report_input_schema()
        if operation in _ARTIFACT_COMMANDS:
            return artifact_schema(operation)
        if operation in _REVIEW_COMMANDS:
            if operation == "engineering.reviews.record":
                return review_command_schema(operation)
            return review_schema(operation)
        if operation in _PROPOSAL_COMMANDS:
            return proposal_schema(operation)
        if operation in SUPPORTED_APPROVAL_COMMANDS:
            return approval_schema(operation)
        # Membership and schema ownership are deliberately checked separately:
        # adding a handler without its owning schema is an unavailable contract,
        # never an accidental proposal-schema alias.
        raise ApplicationError("OPERATION_SCHEMA_UNAVAILABLE")

    def _record_report(self, parameters, context, *, read_set=None):
        if self._access is None:
            raise ApplicationError('ACCESS_AUTHORITY_UNAVAILABLE')
        self._access.require(context, 'engineering.submissions.record_report')
        if read_set is not None and read_set != ReadSet(context.scope,()):
            raise ApplicationError('SUBMISSION_REPORT_READ_SET_UNSUPPORTED')
        if (type(parameters) is not dict or set(parameters) != {'record'}
                or self._execution_records is None or not callable(self._execution_query_factory)):
            raise ApplicationError('SUBMISSION_REPORT_SOURCE_UNAVAILABLE')
        try:
            raw = canonical_bytes(parameters['record'])
            if len(raw) > 2*1024*1024:
                raise ApplicationError('INVALID_INPUT')
            record = decode_submission(raw)
        except ApplicationError:
            raise
        except Exception as exc:
            raise ApplicationError('INVALID_INPUT') from exc
        with self._factory.begin(context.scope, 'read') as uow:
            row = uow.dispatch.by_operation(record.execution_ref.operation_ref, context.scope)
            binding = decode_dispatch(row['binding_bytes'])
        invocation = self._execution_query_factory(binding)
        return self._submission_reports.record_report(record, context,
            records=self._execution_records, blobs=self._blobs, query_invocation=invocation)

    async def execute(self, operation, parameters, context, *, read_set=None):
        if type(context) is not CommandContext:
            raise ApplicationError("INVALID_CONTEXT")
        if type(operation) is not str:
            raise ApplicationError("INVALID_ARGUMENT")
        if operation in IMPLEMENTATION_COMMANDS:
            if read_set is not None:
                raise ApplicationError("IMPLEMENTATION_READ_SET_UNSUPPORTED")
            return self._implementation_invoke(operation, parameters, context)
        handler = self._commands.get(operation)
        if handler is None:
            # Consent callbacks, missing dispatch/Work contracts and unknown
            # methods cannot become arbitrary dynamically imported handlers.
            if self._access is None:
                raise ApplicationError("ACCESS_AUTHORITY_UNAVAILABLE")
            self._access.require(context, operation)
            raise ApplicationError("OPERATION_UNAVAILABLE")
        return handler(parameters, context, read_set=read_set)

    async def query(self, query, parameters, context):
        if query in IMPLEMENTATION_QUERIES:
            return self._implementation_invoke(query, parameters, context)
        if query == "engineering.work.get":
            return self._work.read(parameters,context)
        if query == "engineering.work.current_condition":
            return self._waits.read(parameters, context, query_operation=query)
        if query == "engineering.runs.get_wait":
            return self._waits.read(parameters, context)
        return self._queries.query(query, parameters, context)

    def _implementation_invoke(self, operation, parameters, context):
        if type(context) is not CommandContext:
            raise ApplicationError("INVALID_CONTEXT")
        if self._access is None:
            raise ApplicationError("ACCESS_AUTHORITY_UNAVAILABLE")
        self._access.require(context, operation)
        if self._implementation_routes is None:
            raise ApplicationError("OPERATION_UNAVAILABLE")
        return self._implementation_routes.invoke(operation, parameters, context)

"""Application command and journal values; contexts are internal inputs."""
from dataclasses import asdict, dataclass

from ...domain.common.models.values import (Digest, validate_id)
from ...domain.common.models.identity import (Scope)
from ...domain.common.outcomes.diagnostics import (ReferenceError)
from ...domain.common.mechanisms.hashing import (record_digest)
from ...domain.common.models.identity import (ActorRef)
from ...domain.common.models.values import (utc_instant)
from ...domain.common.mechanisms.codec import (canonical_value)
from ...domain.reviews.models import (ReviewSetExpectation, ReviewControlExpectation, ReviewRequestExpectation)
from .preconditions import (VersionExpectation)

__all__ = ['CommandKey', 'CommandContext', 'request_digest', 'JournalEntry', 'Reservation',
           'CommandResult', 'ReadVersion', 'ReadSet', 'read_set_projection', 'artifact_read_set_projection']


@dataclass(frozen=True)
class CommandKey:
    realm_id: str
    principal_id: str
    request_id: str

    def __post_init__(self):
        for value in (self.realm_id, self.principal_id, self.request_id):
            validate_id(value)


@dataclass(frozen=True)
class CommandContext:
    scope: Scope
    principal_id: str
    authenticated_actor: ActorRef
    request_id: str
    received_at: str
    trace_id: str

    def __post_init__(self):
        if type(self.scope) is not Scope or type(self.authenticated_actor) is not ActorRef:
            raise ReferenceError("INVALID_CONTEXT")
        for value in (self.principal_id, self.request_id, self.trace_id):
            validate_id(value)
        utc_instant(self.received_at)

    @property
    def key(self):
        return CommandKey(self.scope.realm_id, self.principal_id, self.request_id)


def request_digest(operation: str, ctx: CommandContext, parameters, preconditions, *,
                   input_schema_id: str, input_schema_digest: Digest, interface_version: str) -> Digest:
    validate_id(operation)
    validate_id(input_schema_id)
    validate_id(interface_version)
    if type(input_schema_digest) is not Digest:
        raise ReferenceError("INVALID_SCHEMA")
    return record_digest("engineering-command", {"operation": operation,
        "input_schema_id": input_schema_id, "input_schema_digest": asdict(input_schema_digest),
        "interface_version": interface_version,
        "realm_id": ctx.scope.realm_id, "project_id": ctx.scope.project_id,
        "principal_id": ctx.principal_id, "parameters": parameters, "preconditions": preconditions})


@dataclass(frozen=True)
class JournalEntry:
    key: CommandKey
    project_id: str
    operation: str
    operation_id: str
    request_digest: Digest
    state: str
    result_bytes: bytes | None
    version: int

    def __post_init__(self):
        if type(self.key) is not CommandKey or type(self.request_digest) is not Digest:
            raise ReferenceError("INVALID_JOURNAL")
        for value in (self.project_id, self.operation, self.operation_id):
            validate_id(value)
        if (self.state not in {"pending", "completed", "rejected"} or type(self.version) is not int
                or not 0 <= self.version <= (1 << 63) - 1 or (self.state == "pending") != (self.result_bytes is None)):
            raise ReferenceError("INVALID_JOURNAL")
        if self.result_bytes is not None:
            canonical_value(self.result_bytes)


@dataclass(frozen=True)
class Reservation:
    entry: JournalEntry
    created: bool

    def __post_init__(self):
        if type(self.entry) is not JournalEntry or type(self.created) is not bool:
            raise ReferenceError("INVALID_RESERVATION")


@dataclass(frozen=True)
class CommandResult:
    authority_id: str
    operation_id: str
    status: str
    result_bytes: bytes | None

    def __post_init__(self):
        validate_id(self.authority_id)
        validate_id(self.operation_id)
        if (self.status not in {"pending", "completed", "rejected"}
                or (self.status == "pending") != (self.result_bytes is None)):
            raise ReferenceError("INVALID_RESULT")
        if self.result_bytes is not None:
            canonical_value(self.result_bytes)

    @property
    def result(self):
        return canonical_value(self.result_bytes) if self.result_bytes is not None else None


@dataclass(frozen=True)
class ReadVersion:
    kind: str
    identifier: str
    version: int

    def __post_init__(self):
        validate_id(self.kind)
        validate_id(self.identifier)
        if type(self.version) is not int or not 0 <= self.version <= (1 << 63) - 1:
            raise ReferenceError("INVALID_VERSION")

    def expectation(self, scope: Scope) -> VersionExpectation:
        return VersionExpectation(self.kind, scope.realm_id, scope.project_id,
                                  self.identifier, self.version)


@dataclass(frozen=True)
class ReadSet:
    scope: Scope
    versions: tuple[ReadVersion, ...]
    review_sets: tuple[ReviewSetExpectation, ...] = ()
    review_controls: tuple[ReviewControlExpectation, ...] = ()

    review_requests: tuple[ReviewRequestExpectation, ...] = ()

    @property
    def version_expectations(self) -> tuple[VersionExpectation, ...]:
        return tuple(item.expectation(self.scope) for item in self.versions)

    def __post_init__(self):
        if type(self.scope) is not Scope or type(self.versions) is not tuple or any(type(v) is not ReadVersion for v in self.versions):
            raise ReferenceError("INVALID_READ_SET")
        if len({(v.kind, v.identifier) for v in self.versions}) != len(self.versions):
            raise ReferenceError("READ_SET_DUPLICATE")
        object.__setattr__(self, "versions", tuple(sorted(self.versions, key=lambda v: (v.kind, v.identifier))))
        if (type(self.review_sets) is not tuple or type(self.review_controls) is not tuple
                or any(type(item) is not ReviewSetExpectation for item in self.review_sets)
                or any(type(item) is not ReviewControlExpectation for item in self.review_controls)):
            raise ReferenceError("INVALID_REVIEW_READ_SET")
        if (len({item.key for item in self.review_sets}) != len(self.review_sets)
                or len({item.review_ref for item in self.review_controls}) != len(self.review_controls)):
            raise ReferenceError("READ_SET_DUPLICATE")
        if (any(item.key.scope != self.scope for item in self.review_sets)
                or any((item.review_ref.realm_id, item.review_ref.project_id) !=
                       (self.scope.realm_id, self.scope.project_id) for item in self.review_controls)):
            raise ReferenceError("REALM_MISMATCH")
        if (type(self.review_requests) is not tuple or len(self.review_requests) > 4096
                or any(type(item) is not ReviewRequestExpectation for item in self.review_requests)):
            raise ReferenceError("INVALID_REVIEW_READ_SET")
        if len({item.review_id for item in self.review_requests}) != len(self.review_requests):
            raise ReferenceError("READ_SET_DUPLICATE")
        if any(item.scope != self.scope for item in self.review_requests):
            raise ReferenceError("REALM_MISMATCH")
        object.__setattr__(self, "review_requests", tuple(sorted(self.review_requests, key=lambda i: i.review_id)))
        object.__setattr__(self, "review_sets", tuple(sorted(self.review_sets, key=lambda i: i.key.digest.hex)))
        object.__setattr__(self, "review_controls", tuple(sorted(self.review_controls, key=lambda i: i.review_ref.review_id)))


def read_set_projection(reads: ReadSet):
    """Keep historical command identities when no pending-request predicate exists."""
    value = asdict(reads)
    if not reads.review_requests:
        value.pop('review_requests')
    return value


def artifact_read_set_projection(reads: ReadSet):
    """Original interface2 Artifact projection, including historical list form."""
    versions=[{"resource":{"kind":r.kind,"id":r.identifier},"expected_version":r.version}
              for r in reads.versions]
    value=versions
    if reads.review_sets or reads.review_controls or reads.review_requests:
        value={"versions":versions,"review_sets":[asdict(r) for r in reads.review_sets],
               "review_controls":[asdict(r) for r in reads.review_controls]}
    if reads.review_requests:
        value["review_requests"]=[asdict(r) for r in reads.review_requests]
    return value

"""Operation-registry contract: registry-ref shape, results and input typing.

The active registry data is a packaged resource read by a runtime loader; the
application depends on this contract (injected loader), never on a concrete
adapter.
"""
from __future__ import annotations

from typing import Any, Mapping, Protocol

from ...domain.common.outcomes.library_failures import EngineeringError
from ...domain.artifacts.library_materials import MaterialRef

__all__ = ['RegistryLoader', 'registry_ref', 'require_registry_ref', 'operation_results',
           'validate_operation_inputs']


class RegistryLoader(Protocol):
    """Injected active-registry loader; the application depends on this contract."""

    def __call__(self) -> Mapping[str, Any]: ...


def registry_ref(registry: Mapping[str, Any]) -> dict[str, Any]:
    value = registry
    return {'registry_id': value['registry_id'], 'revision': value['revision'], 'digest': value['registry_digest']}


def require_registry_ref(value: Any, registry) -> dict[str, Any]:
    expected = registry_ref(registry)
    if not isinstance(value, Mapping) or set(value) != set(expected) or dict(value) != expected:
        raise EngineeringError('operation_registry_ref_mismatch')
    return expected


def operation_results(registry: Mapping[str, Any]) -> dict[str, set[str]]:
    value = registry
    return {name: set(contract['results']) for name, contract in value['operations'].items()}


def validate_operation_inputs(operation: str, context: Mapping[str, Any], registry: Mapping[str, Any]) -> None:
    contract = registry['operations'].get(operation)
    if contract is None:
        raise EngineeringError('method_operation_unknown')
    for path, expected_type in contract['inputs'].items():
        value: Any = context
        for segment in path.split('.'):
            if not isinstance(value, Mapping) or segment not in value:
                raise EngineeringError('operation_input_missing')
            value = value[segment]
        if expected_type == 'MaterialRef' and (not isinstance(value, MaterialRef)):
            raise EngineeringError('operation_input_type')
        if expected_type == 'MaterialRef[]' and (not isinstance(value, (tuple, list)) or any((not isinstance(item, MaterialRef) for item in value))):
            raise EngineeringError('operation_input_type')
        if expected_type == 'Mapping' and (not isinstance(value, Mapping)):
            raise EngineeringError('operation_input_type')
        if expected_type == 'str' and type(value) is not str:
            raise EngineeringError('operation_input_type')
        if expected_type not in {'MaterialRef', 'MaterialRef[]', 'Mapping', 'str'}:
            raise EngineeringError('operation_registry_input_type_unknown')

