         'reason':{'type':'string','minLength':1,'maxLength':16384}},
        ['proposal_ref','expected_version','replacement_ref','reason'])}
_SCHEMA_BYTES={operation:canonical_bytes(value) for operation,value in _SCHEMAS.items()}
