def input_schema(operation):
    try:
        return canonical_value(_SCHEMA_BYTES[operation])
    except KeyError:
        raise ApplicationError('OPERATION_UNAVAILABLE') from None


class ProposalUseCases:
    def __init__(self,factory,access,control_admission=None):
        self.factory=factory
        self.access=access
        self.control_admission=control_admission

    def _authorize(self,context,operation):
        if type(context) is not CommandContext:
            raise ApplicationError('INVALID_CONTEXT')
        if self.access is None:
            raise ApplicationError('ACCESS_AUTHORITY_UNAVAILABLE')
        self.access.require(context,operation)

    def create(self,parameters,context,*,read_set=None):
        return self._command('engineering.proposals.create',parameters,context,read_set)

    def select(self,parameters,context,*,read_set=None):
        return self._command('engineering.proposals.select',parameters,context,read_set)

    def withdraw(self,parameters,context,*,read_set=None):
        return self._command('engineering.proposals.withdraw',parameters,context,read_set)

    def supersede(self,parameters,context,*,read_set=None):
        return self._command('engineering.proposals.supersede',parameters,context,read_set)

    def _command(self,operation,parameters,context,read_set):
        self._authorize(context,operation)
        try:
            value=canonical_value(canonical_bytes(parameters))
            schema=input_schema(operation)
            if not Draft202012Validator(schema).is_valid(value):
                raise ReferenceError('INVALID_SCHEMA')
            if operation=='engineering.proposals.create':
                if value['change_id'] is None and value['expected_version']!=0:
                    raise ReferenceError('INVALID_VERSION')
                decode_draft(context.scope,'draft',context.received_at,context.authenticated_actor,
                    value['change_id'] or 'new-change',value['draft'])
            else:
                decode_proposal_ref(value['proposal_ref'])
                if 'replacement_ref' in value:
                    decode_proposal_ref(value['replacement_ref'])
                if 'reason' in value:
                    validate_text(value['reason'])
            reads=ReadSet(context.scope,()) if read_set is None else read_set
            if type(reads) is not ReadSet or reads.scope!=context.scope:
                raise ReferenceError('INVALID_SCHEMA')
            digest=request_digest(operation,context,value,read_set_projection(reads),input_schema_id=schema['$id'],
                input_schema_digest=Digest('sha256',hashlib.sha256(_SCHEMA_BYTES[operation]).hexdigest()),interface_version='1')
        except (ReferenceError,ValueError,TypeError,KeyError,RecursionError,OverflowError):
            raise ApplicationError('INVALID_INPUT') from None
        # Query the same durable key before any control callback, never dispatch
        # a pending retry. Access is rechecked above on every call.
        with self.factory.begin(context.scope,'read') as uow:
            repository=uow.proposals
            previous=uow.commands.get(context.key)
            if previous is not None:
                if previous.request_digest!=digest or previous.project_id!=context.scope.project_id:
                    raise ApplicationError('REQUEST_IDENTITY_CONFLICT')
                return CommandResult(uow.authority_id,previous.operation_id,previous.state,previous.result_bytes)
            if operation in {'engineering.proposals.withdraw','engineering.proposals.supersede'}:
                if self.control_admission is None:
                    raise ApplicationError('PROPOSAL_CONTROL_AUTHORITY_UNAVAILABLE')
                proposal=repository.get_proposal(decode_proposal_ref(value['proposal_ref']))
                control=repository.get_control(proposal.ref)
                replacement=repository.get_proposal(decode_proposal_ref(value['replacement_ref'])) if 'replacement_ref' in value else None
            else:
                proposal=control=replacement=None
        disposition='superseded' if operation=='engineering.proposals.supersede' else 'withdrawn'
        guard=nullcontext(()) if proposal is None else self.control_admission.guard_control(context,proposal,control,disposition,replacement)
        with guard as evidence:
            if proposal is not None and (type(evidence) is not tuple or not evidence or any(type(e) is not Digest for e in evidence)):
                raise ApplicationError('PROPOSAL_CONTROL_AUTHORITY_INVALID')
            with self.factory.begin(context.scope) as uow:
                repository=uow.proposals
                reservation=uow.commands.reserve(context.key,project_id=context.scope.project_id,operation=operation,
                    operation_id=str(uuid4()),request_digest=digest)
                entry=reservation.entry
                if not reservation.created:
                    return CommandResult(uow.authority_id,entry.operation_id,entry.state,entry.result_bytes)
                state='completed'
                try:
                    with uow.isolate():
                        uow.engineering.check_read_set(reads)
                        result=self._mutate(repository,operation,value,context,evidence)
                except ReferenceError:
                    state,result='rejected',{'code':'INVALID_INPUT'}
                except ApplicationError as exc:
                    if exc.code not in _REFUSALS:
                        raise
                    state,result='rejected',{'code':exc.code}
                final=uow.commands.complete(context.key,expected_version=entry.version,result_bytes=canonical_bytes(result),state=state)
                answer=CommandResult(uow.authority_id,final.operation_id,final.state,final.result_bytes)
                uow.commit()
                return answer

    @staticmethod
    def _mutate(repository,operation,value,context,evidence):
        if operation=='engineering.proposals.create':
            change_id=value['change_id']
            if change_id is None:
                change_id=str(uuid4())
                repository.create_change(Change(context.scope,change_id,context.received_at))
            proposal=decode_draft(context.scope,str(uuid4()),context.received_at,context.authenticated_actor,change_id,value['draft'])
            budget=repository.validated_budget()
            requirements=validate_create(proposal,repository,budget)
            ref=repository.create_proposal(proposal,expected_version=value['expected_version'],budget=budget,requirements=requirements)
            return {'proposal_ref':asdict(ref),'change':asdict(repository.get_change(change_id))}
        ref=decode_proposal_ref(value['proposal_ref'])
        if operation=='engineering.proposals.select':
            return {'change':asdict(repository.select(ref,expected_version=value['expected_version']))}
        control=repository.control(ref,expected_version=value['expected_version'],
            disposition='superseded' if operation=='engineering.proposals.supersede' else 'withdrawn',
            replacement_ref=decode_proposal_ref(value['replacement_ref']) if 'replacement_ref' in value else None,
            evidence=evidence,at=context.received_at,actor=context.authenticated_actor,reason=value['reason'])
        return {'control':asdict(control)}

    def get(self,ref,context):
        self._authorize(context,'engineering.proposals.get')
        with self.factory.begin(context.scope,'read') as uow:
            return uow.proposals.get_proposal(ref)

    def get_change(self,change_id,context):
        self._authorize(context,'engineering.changes.get')
        with self.factory.begin(context.scope,'read') as uow:
            return uow.proposals.get_change(change_id)

    def get_control(self,ref,context):
        self._authorize(context,'engineering.proposals.get_control')
        with self.factory.begin(context.scope,'read') as uow:
            return uow.proposals.get_control(ref)

"""Application material-closure coordination over the caller's transaction.

The read/blob/budget/CAS work stays in the adapter (``MaterialBudget``, which
implements ``MaterialAccessPort``). This module coordinates those reads with the
pure source/selector/content rules owned by ``domain`` and ``methods``; it does
not re-implement those rules and does not pre-read to reuse across transactions.
"""
from __future__ import annotations

from urllib.parse import urljoin

from jsonschema import Draft202012Validator
from referencing import Registry, Resource
from referencing.exceptions import NoSuchResource
from referencing.jsonschema import DRAFT202012

from ...domain.artifacts.models import BlobPayload, MethodPayload
from ...domain.artifacts.provenance import VersionCapture
from ...domain.common.outcomes.diagnostics import ReferenceError
from ...methods.definitions.errors import MethodFailure
from ...methods.validation.schema import validate_document_schemas

from ordessa_engineering.application.contracts.errors import ApplicationError
from ordessa_engineering.application.contracts.access import MaterialAccessPort, revision_validation_key


def _deny(code):
    raise ApplicationError(code)


def _no_retrieval(uri):
    # Never fetch a schema, including a declared https $id, from the network.
    raise NoSuchResource(ref=uri)


def _source_refs(sources):
    refs = []
    for source in sources:
        if type(source.capture) is VersionCapture:
            _deny('SOURCE_VERSION_UNAVAILABLE')
        if source.kind == 'artifact':
            _deny('SOURCE_OWNER_UNAVAILABLE')
        refs.append(source.capture.blob_ref)
    return tuple(refs)


def verify_sources(sources, links, budget: MaterialAccessPort):
    """Proposal sources use exactly the same byte/selector authority as revisions."""
    budget.reserve(_source_refs(sources))
    try:
        selected = {source.source_id: budget.selectors.check(budget.read(source.capture.blob_ref),
                    source.capture.selector, source.capture.excerpt_digest) for source in sources}
        for link in links:
            budget.selectors.check(selected[link.source_ref.source_id], link.source_selector)
    except ReferenceError as exc:
        _deny('MATERIAL_LIMIT' if exc.code == 'SELECTOR_WORK_LIMIT' else 'MATERIAL_CONTENT_INVALID')
    except KeyError:
        _deny('MATERIAL_CONTENT_INVALID')


def verify_material(revision, budget: MaterialAccessPort):
    if revision.schema_version == 1:
        return  # Historical decoding keeps its original semantics and bytes.
    if revision.generation_origin is not None:
        _deny('GENERATION_ORIGIN_UNAVAILABLE')
    refs = []
    payload = revision.payload
    if type(payload) is BlobPayload:
        refs.append(payload.blob_ref)
    elif type(payload) is MethodPayload and payload.content.rendered_body_ref is not None:
        refs.append(payload.content.rendered_body_ref)
    refs.extend(_source_refs(revision.sources))
    budget.reserve(refs)
    if type(payload) is BlobPayload:
        content = budget.read(payload.blob_ref)
    else:
        content = payload.content_bytes()
    try:
        for claim in revision.claims:
            budget.selectors.check(content, claim.selector, claim.statement_digest)
    except ReferenceError as exc:
        if exc.code == 'SELECTOR_WORK_LIMIT':
            _deny('MATERIAL_LIMIT')
        _deny('MATERIAL_CONTENT_INVALID')
    verify_sources(revision.sources, revision.evidence_links, budget)
    if type(payload) is MethodPayload and payload.content.rendered_body_ref is not None:
        budget.read(payload.content.rendered_body_ref)
    for method in revision.method_refs:
        budget.method(method)
    if type(payload) is MethodPayload:
        _verify_method_content(payload, budget)
    budget.mark_validated(revision_validation_key(revision))


def _verify_method_content(payload, budget: MaterialAccessPort):
    exact = payload.content.schema_ref
    snapshot, loaded = budget.method(exact.method_ref)
    resource = loaded.resources.get(exact.resource_id)
    stored = next((r for r in snapshot.resources if r.resource_id == exact.resource_id), None)
    if (resource is None or stored is None or stored.logical_path != exact.logical_path
            or stored.digest != exact.resource_digest.hex
            or resource.declaration.get('kind') != 'document_schema'):
        _deny('METHOD_RESOURCE_MISMATCH')
    if any(d.severity == 'error' for d in validate_document_schemas(loaded)):
        _deny('METHOD_SCHEMA_INVALID')
    schemas = {rid: r for rid, r in loaded.resources.items()
               if r.declaration.get('kind') == 'document_schema'}
    registry = Registry(retrieve=_no_retrieval)
    for rid, r in schemas.items():
        location = 'https://ordessa.invalid/method/' + r.captured.logical_path
        base = urljoin(location, r.value.get('$id', location))
        document = dict(r.value)
        document['$id'] = base
        resolved = Resource.from_contents(document, default_specification=DRAFT202012)
        registry = registry.with_resource(location, resolved).with_resource(base, resolved)
    location = 'https://ordessa.invalid/method/' + exact.logical_path
    schema = dict(resource.value)
    schema['$id'] = urljoin(location, schema.get('$id', location))
    if payload.schema_id != schema['$id']:
        _deny('METHOD_SCHEMA_ID_MISMATCH')
    try:
        if not Draft202012Validator(schema, registry=registry.crawl()).is_valid(payload.content.value):
            _deny('METHOD_CONTENT_INVALID')
    except ApplicationError:
        raise
    except (ValueError, TypeError, RecursionError, LookupError) as exc:
        raise ApplicationError('METHOD_SCHEMA_INVALID') from exc


__all__ = ['verify_material', 'verify_sources']

"""Narrow typed adapters over the three original Engineering owners.

Composition dependencies (factory, context, native execution records and blob
store) are deliberately not accepted from the operation payload.
"""
from dataclasses import asdict, dataclass
from typing import Any

from ordessa_infrastructure.encoding import canonical_bytes, decode_json

from ..contracts.commands import CommandContext, CommandResult
from ..contracts.errors import ApplicationError
from ..orchestration.steps.implementation_dispatch import ImplementationDispatch
from .packages.implementation import ImplementationUseCases
from .changes.submissions import SubmissionUseCases
from ...domain.packages.codec import decode_package, decode_package_ref
from ...domain.changes.submission_codec import decode_submission
from ...domain.changes.dispatch_codec import decode_dispatch
from ...domain.common.mechanisms.codec import decode_blob_ref


MAX_RECORD_BYTES = 2 * 1024 * 1024


@dataclass(frozen=True)
class OwnerOperationResult:
    operation: str
    outcome: str
    value: Any = None
    engineering_completed: bool = False
    accepted: bool = False
    dispatch_phase: str | None = None
    reason: str | None = None


def _closed_record(value, decoder):
    try:
        raw = canonical_bytes(value)
        if len(raw) > MAX_RECORD_BYTES:
            raise ApplicationError('OWNER_OPERATION_INPUT_TOO_LARGE')
        return decoder(raw)
    except ApplicationError:
        raise
    except Exception as exc:
        raise ApplicationError('OWNER_OPERATION_RECORD_INVALID') from exc


def _result_json(result, factory):
    if type(result) is not CommandResult or result.authority_id != factory.authority_id:
        raise ApplicationError('OWNER_OPERATION_RESULT_AUTHORITY_MISMATCH')
    if result.result_bytes is None:
        return None
    return decode_json(result.result_bytes)


def _journal_matches(factory, context, operation, result):
    with factory.begin(context.scope, 'read') as uow:
        entry = uow.commands.get(context.key)
        return (entry is not None and entry.operation == operation
                and entry.operation_id == result.operation_id
                and entry.project_id == context.scope.project_id
                and entry.state == result.status
                and entry.result_bytes == result.result_bytes)


class EngineeringOwnerOperations:
    """Call package freeze, native dispatch and submission recording owners."""
    def __init__(self, factory, *, packages: ImplementationUseCases,
                 dispatch: ImplementationDispatch, submissions: SubmissionUseCases,
                 records, blobs):
        if any(getattr(owner, 'factory', None) is not factory
               for owner in (packages, dispatch, submissions)):
            raise ApplicationError('OWNER_OPERATION_FACTORY_MISMATCH')
        execution = getattr(dispatch, 'execution', None)
        if (getattr(blobs, 'authority_id', None) != factory.authority_id
                or getattr(dispatch, 'blobs', None) is not blobs
                or records is None or getattr(execution, 'records', None) is not records
                or not callable(getattr(execution, 'query_factory', None))):
            raise ApplicationError('OWNER_OPERATION_SOURCE_AUTHORITY_UNAVAILABLE')
        self.factory, self.packages, self.dispatch = factory, packages, dispatch
        self.submissions, self.records, self.blobs = submissions, records, blobs

    def execute(self, operation: str, parameters, context: CommandContext) -> OwnerOperationResult:
        if type(context) is not CommandContext or type(parameters) is not dict:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        try:
            raw = canonical_bytes(parameters)
        except Exception as exc:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID') from exc
        if len(raw) > MAX_RECORD_BYTES:
            raise ApplicationError('OWNER_OPERATION_INPUT_TOO_LARGE')
        if operation == 'engineering.packages.freeze':
            return self.freeze_package(parameters, context)
        if operation == 'engineering.executions.dispatch':
            return self.dispatch_execution(parameters, context)
        if operation == 'engineering.submissions.record_report':
            return self.record_report(parameters, context)
        if operation == 'engineering.submissions.record':
            return self.record_submission(parameters, context)
        raise ApplicationError('OWNER_OPERATION_UNKNOWN')

    def record_report(self, parameters, context):
        if set(parameters) != {'record'}:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        record = _closed_record(parameters['record'], decode_submission)
        operation = 'engineering.submissions.record_report'
        with self.factory.begin(context.scope, 'read') as uow:
            row = uow.dispatch.by_operation(record.execution_ref.operation_ref, context.scope)
            binding = decode_dispatch(row['binding_bytes'])
        invocation = self.dispatch.execution.query_factory(binding)
        result = self.submissions.record_report(record, context, records=self.records,
            blobs=self.blobs, query_invocation=invocation)
        value = _result_json(result, self.factory)
        if (result.status != 'completed' or type(value) is not dict
                or not _journal_matches(self.factory, context, operation, result)):
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_INCOMPLETE')
        if (set(value) != {'submission_ref', 'workflow_state', 'review_status', 'accepted'}
                or value['workflow_state'] != 'submitted' or value['review_status'] != 'pending_review'
                or value['accepted'] is not False):
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_SHAPE_MISMATCH')
        from ...domain.reviews.target_codec import decode_subject_ref
        ref = decode_subject_ref(value['submission_ref'])
        with self.factory.begin(context.scope, 'read') as uow:
            stored = uow.submissions.resolve(ref)
        if stored != record or stored.ref != ref:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RECORD_MISMATCH')
        return OwnerOperationResult(operation, 'submitted', value, accepted=False)

    def freeze_package(self, parameters, context):
        if set(parameters) != {'record'}:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        record = _closed_record(parameters['record'], decode_package)
        operation = 'engineering.packages.freeze'
        result = self.packages.freeze_package(record, context)
        value = _result_json(result, self.factory)
        if result.status != 'completed' or type(value) is not dict:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_INCOMPLETE')
        if not _journal_matches(self.factory, context, operation, result):
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_JOURNAL_MISMATCH')
        if (set(value) != {'package_ref', 'binding_proof', 'action_instance_id', 'dispatchable'}
                or value['dispatchable'] is not False):
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_SHAPE_MISMATCH')
        ref = decode_package_ref(value['package_ref'])
        with self.factory.begin(context.scope, 'read') as uow:
            stored = uow.implementation.resolve_package(ref)
        if stored != record:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RECORD_MISMATCH')
        return OwnerOperationResult(operation, 'completed', {'package_ref': ref, 'record': stored})

    def dispatch_execution(self, parameters, context):
        if set(parameters) != {'dispatch'} or type(parameters['dispatch']) is not dict:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        request = parameters['dispatch']
        required = {'run_id', 'step_id', 'attempt', 'unit_ref', 'params', 'actions', 'timeout'}
        if set(request) != required or type(request['actions']) is not list:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        if (type(request['attempt']) is not int or not 1 <= request['attempt'] <= 4096
                or type(request['timeout']) not in (int, float) or not 0 < request['timeout'] <= 60
                or not request['actions'] or any(type(a) is not str or not a for a in request['actions'])
                or len(set(request['actions'])) != len(request['actions'])
                or type(request['unit_ref']) is not dict or type(request['params']) is not dict):
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        operation = 'engineering.executions.dispatch'
        returned = self.dispatch.dispatch(request['run_id'], request['step_id'], request['attempt'],
            request['unit_ref'], request['params'], tuple(request['actions']), context,
            timeout=request['timeout'])
        with self.factory.begin(context.scope, 'read') as uow:
            row = uow.dispatch.get(request['run_id'], request['step_id'], request['attempt'], context.scope)
            binding = decode_dispatch(row['binding_bytes'])
            package = ImplementationDispatch._run(uow, request['run_id'])
        if (binding.run_id != request['run_id'] or binding.step_id != request['step_id']
                or binding.attempt != request['attempt']
                or binding.unit_ref_bytes != canonical_bytes(request['unit_ref'])
                or tuple(action for action, _ in binding.action_instances) != tuple(request['actions'])
                or binding.scope != context.scope or binding.package_ref != package.ref):
            return OwnerOperationResult(operation, 'unknown', engineering_completed=False,
                                        reason='OWNER_BINDING_MISMATCH')
        phase = row['dispatch_phase']
        outcome = phase if phase in {'completed', 'failed'} else 'unknown'
        result_ref = None
        if row['result_blob_json'] is not None:
            result_ref = decode_blob_ref(decode_json(row['result_blob_json']))
            # The original UoW verifies the observed bytes under the same
            # authority before this adapter reports a native record outcome.
            with self.factory.begin(context.scope, 'read') as uow:
                uow.implementation.read_blob(result_ref)
        # Compare the owner's immediate view with its durable row. A caller
        # cannot substitute an outcome after the transaction has committed.
        if (type(returned) is not dict or returned.get('phase') != phase
                or returned.get('run_id') != request['run_id']
                or returned.get('step_id') != request['step_id']
                or returned.get('attempt') != request['attempt']
                or returned.get('binding_digest') != {'algorithm': binding.digest.algorithm,
                                                       'hex': binding.digest.hex}
                or returned.get('engineering_completed') is not False
                or canonical_bytes(returned.get('result_blob_ref')) !=
                   (b'null' if result_ref is None else canonical_bytes(decode_json(row['result_blob_json'])))):
            outcome = 'unknown'
        return OwnerOperationResult(operation, outcome,
            {'binding': binding, 'observation_ref': result_ref}, engineering_completed=False,
            accepted=False, dispatch_phase=phase,
            reason=None if outcome == phase else 'OWNER_RESULT_MISMATCH')

    def record_submission(self, parameters, context):
        if set(parameters) != {'record'}:
            raise ApplicationError('OWNER_OPERATION_INPUT_INVALID')
        record = _closed_record(parameters['record'], decode_submission)
        operation = 'engineering.submissions.record'
        # The invocation is created by the same composition-owned query factory
        # used by dispatch capture, from the exact original attempt binding.
        with self.factory.begin(context.scope, 'read') as uow:
            dispatch_row = uow.dispatch.by_operation(record.execution_ref.operation_ref, context.scope)
            binding = decode_dispatch(dispatch_row['binding_bytes'])
        invocation = self.dispatch.execution.query_factory(binding)
        if invocation is None:
            raise ApplicationError('EXECUTION_QUERY_AUTHORITY_REQUIRED')
        result = self.submissions.record(record, context, records=self.records, blobs=self.blobs,
                                         query_invocation=invocation)
        value = _result_json(result, self.factory)
        if result.status != 'completed' or type(value) is not dict:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_INCOMPLETE')
        if not _journal_matches(self.factory, context, operation, result):
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_JOURNAL_MISMATCH')
        if (set(value) == {'state', 'reason', 'quarantined_submission_draft_ref',
                           'execution_observation_ref', 'normal_submission_sealed'}
                and value.get('state') == 'quarantined'
                and value.get('normal_submission_sealed') is False
                and value.get('execution_observation_ref') ==
                    asdict(record.execution_ref.captured_observation_ref)):
            from ...domain.artifacts.ref_codec import decode_artifact_ref
            from ...domain.artifacts.models import BlobPayload
            draft_ref = decode_artifact_ref(value['quarantined_submission_draft_ref'])
            with self.factory.begin(context.scope, 'read') as uow:
                revision = uow.engineering.resolve_revision(draft_ref)
                payload = revision.payload
                if type(payload) is not BlobPayload or payload.schema_id != 'urn:ordessa:quarantined-submission-draft:1':
                    return OwnerOperationResult(operation, 'unknown', reason='QUARANTINE_RECORD_MISMATCH')
                envelope = decode_json(uow.implementation.read_blob(payload.blob_ref))
                expected_observation = asdict(record.execution_ref.captured_observation_ref)
                if (type(envelope) is not dict
                        or set(envelope) != {'contract','reason','draft_ref','execution_observation_ref',
                                             'claimed_submission_ref','normal_submission_sealed'}
                        or envelope.get('contract') != 'ordessa.quarantined-submission-draft/1'
                        or envelope.get('reason') != value['reason']
                        or envelope.get('execution_observation_ref') != expected_observation
                        or envelope.get('claimed_submission_ref') != asdict(record.ref)
                        or envelope.get('normal_submission_sealed') is not False):
                    return OwnerOperationResult(operation, 'unknown', reason='QUARANTINE_RECORD_MISMATCH')
                captured_draft = self.blobs.read_verified(decode_blob_ref(envelope['draft_ref']))
            if decode_submission(captured_draft) != record:
                return OwnerOperationResult(operation, 'unknown', reason='QUARANTINE_DRAFT_MISMATCH')
            return OwnerOperationResult(operation, 'quarantined', value, accepted=False,
                                        reason=value['reason'])
        if set(value) != {'submission_ref', 'accepted'} or value.get('accepted') is not False:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_SHAPE_MISMATCH')
        from ...domain.reviews.refs import SubmissionRef
        from ...domain.common.mechanisms.codec import decode_digest, require_object
        ref_value = value['submission_ref']
        require_object(ref_value, {'kind', 'realm_id', 'project_id', 'submission_id', 'digest'},
                       'INVALID_SUBMISSION_REF')
        if ref_value['kind'] != 'submission':
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RESULT_SHAPE_MISMATCH')
        ref = SubmissionRef(ref_value['realm_id'], ref_value['project_id'],
                            ref_value['submission_id'], decode_digest(ref_value['digest']))
        with self.factory.begin(context.scope, 'read') as uow:
            stored = uow.submissions.resolve(ref)
        if stored != record or stored.ref != ref:
            return OwnerOperationResult(operation, 'unknown', reason='OWNER_RECORD_MISMATCH')
        return OwnerOperationResult(operation, 'recorded', {'submission_ref': ref, 'record': stored},
                                    accepted=False)

"""Baseline and package freezing on the original command journal/transaction.

A persisted package is content, never a BindingProof or a dispatch capability.
Full implementation grants remain unavailable until their original owner is bound.
"""
from dataclasses import asdict
from uuid import uuid4
import hashlib
from ordessa_infrastructure.encoding import canonical_bytes
from ...contracts.commands import CommandContext, CommandResult, request_digest
from ...contracts.errors import ApplicationError
from ....domain.common.models.values import Digest
from ....domain.common.outcomes.diagnostics import ReferenceError
from ....domain.changes.repository_baseline import RepositoryBaseline
from ....domain.changes.repository_baseline_codec import encode_repository_baseline
from ....domain.packages.models import ImplementationPackage
from ....domain.packages.codec import encode_package

class ImplementationUseCases:
    def __init__(self, factory, access=None, *, approval_usecases=None):
        self.factory=factory
        self.access=access
        if approval_usecases is not None and getattr(approval_usecases, "factory", None) is not factory:
            raise ApplicationError("AUTHORIZATION_AUTHORITY_MISMATCH")
        self.approvals=approval_usecases

    def _authorize(self, context, operation):
        if type(context) is not CommandContext:
            raise ApplicationError('INVALID_CONTEXT')
        if self.access is None:
            raise ApplicationError('ACCESS_AUTHORITY_UNAVAILABLE')
        self.access.require(context,operation)

    def freeze_baseline(self, record, context):
        operation='engineering.repositories.freeze_baseline'
        self._authorize(context,operation)
        if type(record) is not RepositoryBaseline or (record.ref.realm_id,record.ref.project_id) != (context.scope.realm_id,context.scope.project_id):
            raise ApplicationError('SCOPE_MISMATCH')
        # Current creation captures same-authority content manifests only.
        # A caller-supplied Git commit/overlay is not an authenticated checkout.
        if record.ref.vcs != 'none' or record.ref.dirty_overlay_digest is not None:
            raise ApplicationError('REPOSITORY_CHECKOUT_SOURCE_UNAVAILABLE')
        return self._command(operation,record,encode_repository_baseline(record),context)

    def freeze_package(self, record, context):
        operation='engineering.packages.freeze'
        self._authorize(context,operation)
        if type(record) is not ImplementationPackage or record.scope != context.scope:
            raise ApplicationError('SCOPE_MISMATCH')
        if record.created_at != context.received_at or record.created_by != context.authenticated_actor:
            raise ApplicationError('PACKAGE_ATTRIBUTION_MISMATCH')
        if self.approvals is None:
            raise ApplicationError('IMPLEMENTATION_GRANT_AUTHORITY_UNAVAILABLE')
        from ....domain.approvals.implementation import ImplementationAuthorizationIntent
        from contextlib import ExitStack
        with self.factory.begin(context.scope, 'read') as uow:
            grant = uow.authorization.get_grant(record.payload.authorization_refs[0])
        if type(grant.intent) is not ImplementationAuthorizationIntent:
            raise ApplicationError('ACTION_NOT_AUTHORIZED')
        # Current method, truthful confirmation ingress and full review/trust
        # guards remain held until the original package/action/journal COMMIT.
        with ExitStack() as guards:
            admission = self.approvals._admission()
            guards.enter_context(admission.guard_intent(context, grant.intent))
            guards.enter_context(admission.guard_evidence(context, grant.intent, grant.evidence))
            decisions = guards.enter_context(self.approvals._gates(context, grant.intent))
            return self._command(operation,record,encode_package(record),context,decisions=decisions)

    def _command(self, operation, record, raw, context, *, decisions=()):
        schema='urn:ordessa:engineering:implementation-content:1'
        parameters={'record_sha256':hashlib.sha256(raw).hexdigest()}
        digest=request_digest(operation,context,parameters,[],input_schema_id=schema,
            input_schema_digest=Digest('sha256',hashlib.sha256(schema.encode()).hexdigest()),interface_version='1')
        with self.factory.begin(context.scope) as uow:
            owner=uow.implementation
            reservation=uow.commands.reserve(context.key,project_id=context.scope.project_id,
                operation=operation,operation_id=str(uuid4()),request_digest=digest)
            entry=reservation.entry
            if not reservation.created:
                return CommandResult(uow.authority_id,entry.operation_id,entry.state,entry.result_bytes)
            # Source integrity or binding refusals roll back the reservation;
            # no incomplete package is stored as a successfully bound object.
            if operation=='engineering.repositories.freeze_baseline':
                result={'baseline_ref':asdict(owner.create_repository_baseline(record))}
            else:
                proof = self._resolve_package(uow,record,now=context.received_at)
                self.approvals._check_gates(uow,decisions)
                action_id = str(uuid4())
                uow.authorization.consume_action(record.payload.authorization_refs[0],
                    action='generate_package',action_instance_id=action_id,
                    target_digest=record.digest,now=context.received_at)
                result={'package_ref':asdict(owner.create_package(record)),
                    'binding_proof':asdict(proof),'action_instance_id':action_id,'dispatchable':False}
            result_raw=canonical_bytes(result)
            uow.commands.complete(context.key,state='completed',result_bytes=result_raw,expected_version=entry.version)
            uow.commit()
            return CommandResult(uow.authority_id,entry.operation_id,'completed',result_raw)

    @staticmethod
    def _resolve_package(uow,record,*,now):
        p=record.payload
        baselines={r.repository_id:uow.implementation.resolve_repository_baseline(r) for r in p.baseline_snapshots}
        for row in p.resolved_file_manifest:
            files={f.path:f.blob_ref.digest for f in baselines[row.repository_id].files}
            source=row.rename_from if row.operation=='rename' else row.path
            if row.operation=='add':
                if row.path in files:
                    raise ApplicationError('PACKAGE_BASELINE_FILE_MISMATCH')
            elif files.get(source) != row.before_blob_digest:
                raise ApplicationError('PACKAGE_BASELINE_FILE_MISMATCH')
            if row.operation=='rename' and row.path in files:
                raise ApplicationError('PACKAGE_BASELINE_FILE_MISMATCH')
        blobs=(p.instructions_ref,*p.derivation.input_refs,
            *(b for c in p.proposal_coverage for b in c.instructions))
        for blob in blobs:
            uow.implementation.read_blob(blob)
        budget=uow.proposals.validated_budget()
        proposals=tuple(uow.proposals.get_proposal(ref,budget=budget) for ref in p.change_set.proposal_refs)
        specs=tuple(proposal.implementation_intent for proposal in proposals)
        if not specs or specs[0] is None or any(spec != specs[0] for spec in specs):
            raise ApplicationError('PACKAGE_IMPLEMENTATION_INTENT_MISMATCH')
        spec=specs[0]
        if (spec.implementation_intent_id != p.implementation_intent_id
                or spec.expected_baselines != p.baseline_snapshots
                or not set(p.allowed_actions) <= set(spec.requested_actions)
                or p.acceptance_requirements != spec.acceptance_requirement_refs):
            raise ApplicationError('PACKAGE_IMPLEMENTATION_INTENT_MISMATCH')
        for row in p.resolved_file_manifest:
            if row.operation=='rename':
                allowed=spec.scope.allows_path(row.repository_id,row.rename_from,row.operation,destination=row.path)
            else:
                allowed=spec.scope.allows_path(row.repository_id,row.path,row.operation)
            if not allowed:
                raise ApplicationError('PACKAGE_SCOPE_MISMATCH')
        for ref in p.design_targets:
            uow.engineering.resolve_revision(ref)
        budget.method(p.method_ref)
        if any(proposal.method_ref != p.method_ref for proposal in proposals):
            raise ApplicationError('PACKAGE_METHOD_MISMATCH')
        if p.execution_profile_ref not in spec.scope.environment_refs:
            raise ApplicationError('PACKAGE_EXECUTION_PROFILE_MISMATCH')
        for resource in p.skill_snapshot_refs:
            snapshot=budget.method(resource.method_ref)
            # Exact method resource integrity is checked by the original snapshot owner;
            # no caller-supplied mutable path is executed here.
            if resource.method_ref != p.method_ref:
                raise ApplicationError('PACKAGE_METHOD_MISMATCH')
            actual = next((r for r in snapshot.resources if r.resource_id == resource.resource_id and r.logical_path == resource.logical_path), None)
            if actual is None or actual.digest != resource.resource_digest.hex:
                raise ApplicationError('PACKAGE_RESOURCE_MISMATCH')
        grant=uow.authorization.get_grant(p.authorization_refs[0])
        from .authorization import resolve_implementation_intent
        from ....domain.packages.binding import bind_implementation_package
        resolve_implementation_intent(uow,grant.intent)
        control=uow.authorization.get_control(grant.ref)
        try:
            return bind_implementation_package(record,grant,control_state=control['state'],
                control_version=control['version'],now=now)
        except ReferenceError as exc:
            raise ApplicationError(exc.code) from exc

    def read_baseline(self,ref,context):
        self._authorize(context,'engineering.repositories.get_baseline')
        with self.factory.begin(context.scope,mode='read') as uow:
            return uow.implementation.resolve_repository_baseline(ref)

    def read_package(self,ref,context):
        self._authorize(context,'engineering.packages.get')
        with self.factory.begin(context.scope,mode='read') as uow:
            return uow.implementation.resolve_package(ref)

"""Resolve supported exact identities through public repositories in one UoW.

This is not the missing E5 ResolvedRefGraph: it does not invent approvals,
submissions or repository-baseline authorities, nor reinterpret latest heads.
"""
from ordessa_engineering.domain.artifacts.refs import (ArtifactRevisionRef)
from ordessa_engineering.domain.changes.refs import (ProposalRef)
from ordessa_engineering.domain.reviews.refs import (ReviewRef, SubmissionRef)
from ordessa_engineering.domain.changes.baselines import RepositorySnapshotRef
from ordessa_engineering.domain.packages.refs import ImplementationPackageRef
from ordessa_engineering.domain.approvals.refs import ApprovalRef
from ordessa_engineering.domain.approvals.consent import NoticeRef
from ordessa_engineering.application.contracts.errors import ApplicationError


def resolve_exact(uow, ref):
    if type(ref) is NoticeRef:
        if ref.scope != uow.scope:
            raise ApplicationError("SCOPE_MISMATCH")
        return uow.authorization.get_notice(ref)
    if type(ref) not in (ArtifactRevisionRef, ProposalRef, ReviewRef, ApprovalRef, SubmissionRef, RepositorySnapshotRef, ImplementationPackageRef):
        raise ApplicationError("REFERENCE_OWNER_UNAVAILABLE")
    if (ref.realm_id, ref.project_id) != (uow.scope.realm_id, uow.scope.project_id):
        raise ApplicationError("SCOPE_MISMATCH")
    if type(ref) is ArtifactRevisionRef:
        return uow.engineering.resolve_revision(ref)
    if type(ref) is ProposalRef:
        return uow.proposals.get_proposal(ref)
    if type(ref) is ApprovalRef:
        return uow.authorization.get_grant(ref)
    if type(ref) is SubmissionRef:
        try:
            repository = uow.submissions
        except ApplicationError as exc:
            if exc.code == 'SUBMISSION_SCHEMA_REQUIRED':
                raise ApplicationError('REFERENCE_OWNER_UNAVAILABLE') from exc
            raise
        return repository.resolve(ref)
    if type(ref) is RepositorySnapshotRef:
        return uow.implementation.resolve_repository_baseline(ref)
    if type(ref) is ImplementationPackageRef:
        return uow.implementation.resolve_package(ref)
    return uow.reviews.get_review(ref)

"""One authenticated current-condition read/resume over the original run CAS.

No background executor and no prototype-to-CompiledProgram reinterpretation.
Actual business side effects must still re-admit at their own commit/write cut.
"""
from contextlib import ExitStack, contextmanager
from dataclasses import asdict
from ...contracts.commands import CommandContext
from ...contracts.errors import ApplicationError
from ...contracts.run_waits import BoundRunWait, run_wait_row_digest
from ...contracts.method_work import BoundWorkWait
from ..approvals.service import ApprovalUseCases
from ..support.clock import utc_now
from .references import resolve_exact
from ....domain.changes.adoption import AcceptanceReceiptRef
from ....domain.reviews.refs import SubmissionRef
from ....domain.common.mechanisms.codec import require_object
from ....domain.common.models.values import Digest, validate_id
from ....domain.common.outcomes.diagnostics import ReferenceError
