"""Closed action bounds. String containment is not filesystem attestation."""
from dataclasses import dataclass

from ..common.models.values import (Digest, validate_id)
from ..common.outcomes.diagnostics import (ReferenceError)
from ..common.models.values import (normalized_path)
from ..common.models.values import (validate_items, ordered_unique)
from ordessa_infrastructure.encoding import canonical_bytes
from dataclasses import asdict

ACTIONS = frozenset({'accept_artifact', 'apply_change', 'generate_package',
    'edit_repository', 'run_checks', 'create_local_commit', 'export_bundle',
    'publish_branch', 'deploy'})
FILE_OPERATIONS = frozenset({'add', 'modify', 'delete', 'rename'})


@dataclass(frozen=True)
class PathRule:
    root: str
    match: str
    operations: tuple[str, ...]

    def __post_init__(self):
        normalized_path(self.root)
        if type(self.match) is not str or self.match not in {'exact', 'subtree'}:
            raise ReferenceError('INVALID_ACTION_SCOPE')
        validate_items(self.operations, str, nonempty=True)
        if any(op not in FILE_OPERATIONS for op in self.operations):
            raise ReferenceError('INVALID_ACTION_SCOPE')
        object.__setattr__(self, 'operations', ordered_unique(self.operations, lambda x:x, code='DUPLICATE_CHECK'))

    def contains(self, path, operation):
        normalized_path(path)
        return operation in self.operations and (path == self.root or
            self.match == 'subtree' and path.startswith(self.root + '/'))


@dataclass(frozen=True)
class RepositoryScope:
    repository_id: str
    path_rules: tuple[PathRule, ...]

    def __post_init__(self):
        validate_id(self.repository_id)
        validate_items(self.path_rules, PathRule, nonempty=True)
        object.__setattr__(self, 'path_rules', ordered_unique(self.path_rules, lambda x:canonical_bytes(asdict(x)), code='DUPLICATE_CHECK'))


@dataclass(frozen=True)
class EnvironmentRef:
    environment_id: str
    profile_id: str
    profile_digest: Digest

    def __post_init__(self):
        validate_id(self.environment_id)
        validate_id(self.profile_id)
        if type(self.profile_digest) is not Digest:
            raise ReferenceError('INVALID_ACTION_SCOPE')


@dataclass(frozen=True)
class EffectLimit:
    action: str
    target_id: str
    constraint_digest: Digest

    def __post_init__(self):
        if type(self.action) is not str or self.action not in ACTIONS:
            raise ReferenceError('INVALID_ACTION_SCOPE')
        validate_id(self.target_id)
        if type(self.constraint_digest) is not Digest:
            raise ReferenceError('INVALID_ACTION_SCOPE')


@dataclass(frozen=True)
class ActionScope:
    project_id: str
    repository_scopes: tuple[RepositoryScope, ...]
    environment_refs: tuple[EnvironmentRef, ...]
    effect_limits: tuple[EffectLimit, ...]
    exclusions: tuple[PathRule, ...]
    implementation_intent_id: str

    def __post_init__(self):
        validate_id(self.project_id)
        validate_id(self.implementation_intent_id)
        for name, kind, key in (
            ('repository_scopes', RepositoryScope, lambda x:x.repository_id),
            ('environment_refs', EnvironmentRef, lambda x:x.environment_id),
            ('effect_limits', EffectLimit, lambda x:(x.action,x.target_id)),
            ('exclusions', PathRule, lambda x:canonical_bytes(asdict(x)))):
            value=getattr(self,name)
            validate_items(value,kind)
            object.__setattr__(self,name,ordered_unique(value,key, code='DUPLICATE_CHECK'))

    def allows_path(self, repository_id, path, operation, *, destination=None):
        if type(operation) is not str or operation not in FILE_OPERATIONS:
            raise ReferenceError('INVALID_ACTION_SCOPE')
        normalized_path(path)
        if operation == 'rename':
            if destination is None:
                raise ReferenceError('INVALID_ACTION_SCOPE')
            normalized_path(destination)
            paths=(path,destination)
        elif destination is not None:
            raise ReferenceError('INVALID_ACTION_SCOPE')
        else:
            paths=(path,)
        rules=next((r.path_rules for r in self.repository_scopes if r.repository_id==repository_id),())
        return all(not any(r.contains(p,operation) for r in self.exclusions)
                   and any(r.contains(p,operation) for r in rules) for p in paths)

"""Closed, canonical wire codec for artifact revisions.

This module is deliberately pure domain code: decoding validates the complete
wire shape and reconstructs domain values before accepting their derived hashes.
"""
from __future__ import annotations

from ordessa_infrastructure.encoding import canonical_bytes

from ordessa_engineering.domain.artifacts.provenance import (Claim, EvidenceLink, ExcerptCapture, GenerationOrigin, SourceLocator, SourceRef, VersionCapture)
from ordessa_engineering.domain.common.models.selection import (ContentSelector)
from ordessa_engineering.domain.artifacts.method_binding import (ExactMethodResourceRef)
from ordessa_engineering.domain.artifacts.refs import (ArtifactRevisionRef)
from ordessa_engineering.domain.common.models.refs import (BlobRef)
from ordessa_engineering.domain.artifacts.method_binding import (MethodRef)
from ..common.models.values import (Digest)
from ..common.models.identity import (Scope)
from ..common.outcomes.diagnostics import (ReferenceError)
from ..common.models.identity import (ActorRef)
from ..common.mechanisms.codec import (canonical_value)
from .models import (
    MAX_RECORD_BYTES, ArtifactRevision, BlobPayload, InlinePayload, MethodContent,
    MethodPayload,
)


from ordessa_engineering.domain.common.mechanisms.codec import (require_object, decode_tuple, decode_digest, decode_actor, decode_blob_ref, decode_selector)
from ordessa_engineering.domain.artifacts.method_codec import (decode_method_ref, decode_exact_method_resource)
from ordessa_engineering.domain.artifacts.ref_codec import (decode_artifact_ref)
from ordessa_engineering.domain.artifacts.provenance_codec import (decode_source, decode_claim, decode_evidence_link, decode_generation_origin)


def decode_provenance_fields(value) -> dict:
    """Decode the five required schema-2 provenance fields into typed values."""
    require_object(value, {"sources", "claims", "evidence_links", "method_refs", "generation_origin"}, code='INVALID_REVISION')
    return {
        "sources": decode_tuple(value["sources"], decode_source, code='INVALID_REVISION'),
        "claims": decode_tuple(value["claims"], decode_claim, code='INVALID_REVISION'),
        "evidence_links": decode_tuple(value["evidence_links"], decode_evidence_link, code='INVALID_REVISION'),
        "method_refs": decode_tuple(value["method_refs"], decode_method_ref, code='INVALID_REVISION'),
        "generation_origin": decode_generation_origin(value["generation_origin"]),
    }


def decode_payload(value):
    """Decode a closed inline, blob, or explicitly tagged method payload."""
    if type(value) is not dict:
        raise ReferenceError("INVALID_PAYLOAD")
    common = {"media_type", "schema_id"}
    if "content_kind" in value:
        require_object(value, common | {"content_kind", "inline_value"}, "INVALID_METHOD_CONTENT")
        if value["content_kind"] != "method_content":
            raise ReferenceError("INVALID_METHOD_CONTENT")
        content = value["inline_value"]
        require_object(content, {"schema_ref", "value", "rendered_body_ref"}, "INVALID_METHOD_CONTENT")
        method_data = content["schema_ref"]
        require_object(method_data, {"method_ref", "logical_path", "resource_digest", "resource_id"}, "INVALID_METHOD_RESOURCE")
        schema_ref = decode_exact_method_resource(method_data)
        rendered = content["rendered_body_ref"]
        method_content = MethodContent.from_value(
            schema_ref, content["value"], None if rendered is None else decode_blob_ref(rendered))
        return MethodPayload(value["media_type"], value["schema_id"], method_content)
    if "blob_ref" in value:
        require_object(value, common | {"blob_ref"}, "INVALID_PAYLOAD")
        return BlobPayload(value["media_type"], value["schema_id"], decode_blob_ref(value["blob_ref"]))
    require_object(value, common | {"inline_value"}, "INVALID_PAYLOAD")
    return InlinePayload.from_value(value["media_type"], value["schema_id"], value["inline_value"])


def encode_revision(record: ArtifactRevision) -> bytes:
    if type(record) is not ArtifactRevision:
        raise ReferenceError("INVALID_REVISION")
    raw = canonical_bytes(record.projection())
    if len(raw) > MAX_RECORD_BYTES:
        raise ReferenceError("REVISION_TOO_LARGE")
    return raw


def decode_revision(raw: bytes) -> ArtifactRevision:
    try:
        if type(raw) is not bytes or len(raw) > MAX_RECORD_BYTES:
            raise ReferenceError("INVALID_REVISION")
        data = canonical_value(raw, maximum=MAX_RECORD_BYTES)
        base = {"schema_version", "realm_id", "project_id", "artifact_id", "revision_id", "created_at",
                "created_by", "payload", "body_digest", "parent_revision_refs", "digest"}
        if type(data) is not dict or type(data.get("schema_version")) is not int:
            raise ReferenceError("INVALID_REVISION")
        if data["schema_version"] == 1:
            require_object(data, base, code='INVALID_REVISION')
            provenance = {}
        elif data["schema_version"] == 2:
            require_object(data, base | {"sources", "claims", "evidence_links", "method_refs", "generation_origin"}, code='INVALID_REVISION')
            provenance = decode_provenance_fields({key: data[key] for key in (
                "sources", "claims", "evidence_links", "method_refs", "generation_origin")})
        else:
            raise ReferenceError("INVALID_REVISION")
        parents = decode_tuple(data["parent_revision_refs"], decode_artifact_ref, "INVALID_PARENT",
                         maximum=None if data["schema_version"] == 1 else 4096)
        payload = decode_payload(data["payload"])
        if data["schema_version"] == 1 and type(payload) is not InlinePayload:
            raise ReferenceError("INVALID_PAYLOAD")
        revision = ArtifactRevision(
            Scope(data["realm_id"], data["project_id"]), data["artifact_id"], data["revision_id"],
            data["created_at"], decode_actor(data["created_by"]), payload, parents,
            data["schema_version"], **provenance,
        )
        decode_digest(data["body_digest"])
        decode_digest(data["digest"])
        if encode_revision(revision) != raw:
            raise ReferenceError("REVISION_DIGEST_MISMATCH")
        return revision
    except ReferenceError:
        raise
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError, OverflowError):
        raise ReferenceError("INVALID_REVISION") from None

from __future__ import annotations
import hashlib
from typing import Any, Mapping
from ordessa_infrastructure.encoding.canonical_json import canonical_text, CanonicalJSONError, LIBRARY_JSON_PROFILE
from ordessa_engineering.domain.common.outcomes.library_failures import EngineeringError
from .library_materials import MaterialRef

def canonical_json(value: Any) -> str:
    try:
        return canonical_text(value, profile=LIBRARY_JSON_PROFILE)
    except CanonicalJSONError as exc:
        code = 'json_encode' if exc.stage == 'encode' else {'depth': 'json_depth', 'non_finite': 'json_non_finite', 'key_type': 'json_key_type', 'type': 'json_type'}[exc.reason]
        raise EngineeringError(code) from exc

def content_digest(value: Any) -> str:
    return 'sha256:' + hashlib.sha256(canonical_json(value).encode('utf-8')).hexdigest()

def material_ref_to_dict(ref: MaterialRef) -> dict[str, Any]:
    return {'library_id': ref.library_id, 'kind': ref.kind, 'stable_id': ref.stable_id, 'revision': ref.revision, 'digest': ref.digest}

def material_ref_from_dict(value: Mapping[str, Any]) -> MaterialRef:
    if not isinstance(value, Mapping) or set(value) != {'library_id', 'kind', 'stable_id', 'revision', 'digest'}:
        raise EngineeringError('ref_shape')
    return MaterialRef(**dict(value))

from __future__ import annotations
from dataclasses import dataclass
import re
from ordessa_engineering.domain.common.outcomes.library_failures import EngineeringError
_KINDS = re.compile('^[a-z][a-z0-9-]{0,63}$')
_IDENTIFIER = re.compile('^[A-Za-z0-9][A-Za-z0-9._:/+-]{0,191}$')
_DIGEST = re.compile('^sha256:[0-9a-f]{64}$')

@dataclass(frozen=True)
class MaterialRef:
    library_id: str
    kind: str
    stable_id: str
    revision: int
    digest: str

    def __post_init__(self) -> None:
        if not _IDENTIFIER.fullmatch(self.library_id):
            raise EngineeringError('ref_library_id')
        if not _KINDS.fullmatch(self.kind):
            raise EngineeringError('ref_kind')
        if not _IDENTIFIER.fullmatch(self.stable_id):
            raise EngineeringError('ref_stable_id')
        if type(self.revision) is not int or self.revision < 1:
            raise EngineeringError('ref_revision')
        if not _DIGEST.fullmatch(self.digest):
            raise EngineeringError('ref_digest')

"""Closed captured method/material binding decoders; no methods stage."""
from ordessa_engineering.domain.common.mechanisms.codec import require_object, decode_tuple, decode_digest, decode_actor, decode_blob_ref, decode_selector
from ordessa_engineering.domain.common.outcomes.diagnostics import ReferenceError
from .method_binding import MethodRef, ExactMethodResourceRef

def decode_method_ref(value):
    require_object(value, {"method_id", "release_version", "schema_version", "snapshot_digest"}, "INVALID_SCHEMA")
    return MethodRef(value["method_id"], value["release_version"], value["schema_version"],
                     decode_digest(value["snapshot_digest"]))


def decode_exact_method_resource(value):
    require_object(value, {"method_ref", "logical_path", "resource_digest", "resource_id"}, "INVALID_METHOD_RESOURCE")
    return ExactMethodResourceRef(decode_method_ref(value["method_ref"]), value["logical_path"],
                                  decode_digest(value["resource_digest"]), value["resource_id"])

