        object.__setattr__(self,'proposal_refs',ordered_unique(self.proposal_refs,lambda x:canonical_bytes(asdict(x)), code='DUPLICATE_CHECK'))
        object.__setattr__(self,'digest',record_digest('change-set',{'proposal_refs':[asdict(r) for r in self.proposal_refs]}))

"""Proposal validation consumes exact resolved values; it never applies heads."""
from ordessa_engineering.domain.changes.errors import (DomainError, from_reference_error)
from ordessa_engineering.domain.changes.errors import (DomainErrorCode)
from ordessa_engineering.domain.common.outcomes.diagnostics import (ReferenceError)
from ordessa_engineering.domain.changes.result import (Result)
from ordessa_infrastructure.encoding import canonical_bytes
from ..artifacts.models import ARTIFACT_KINDS, Artifact, ArtifactRevision
from ..reviews.requirements import expand_requirement
from .models import Proposal, ProposalControl, ChangeSet


def validate_proposal(proposal, artifacts, revisions):
    if type(proposal) is not Proposal or type(artifacts) is not tuple or type(revisions) is not tuple:
        raise ReferenceError('INVALID_PROPOSAL')
    if (len(artifacts)>4096 or len(revisions)>10000 or any(type(a) is not Artifact or a.scope!=proposal.scope for a in artifacts)
            or any(type(r) is not ArtifactRevision or r.scope!=proposal.scope for r in revisions)):
        raise ReferenceError('INVALID_RESOLVED_GRAPH')
    owners={a.artifact_id:a for a in artifacts}
    graph={r.ref:r for r in revisions}
    if len(owners)!=len(artifacts) or len({(r.artifact_id,r.revision_id) for r in revisions})!=len(revisions):
        raise ReferenceError('INVALID_RESOLVED_GRAPH')
    if sum(len(canonical_bytes(r.projection())) for r in revisions)>64*1024*1024:
        raise ReferenceError('ANCESTRY_LIMIT')
    # All supplied nodes, including non-mutation claim owners, are a closed DAG.
    completed=set()
    active=set()
    edges=0
    for root in graph:
        stack=[(root,False)]
        while stack:
            ref,leaving=stack.pop()
            if leaving:
                active.remove(ref)
                completed.add(ref)
                continue
            # Count every traversed reference, including cached nodes. A dense
            # supplied graph must not evade the work bound through deduplication.
            edges+=1
            if edges>10000:
                raise ReferenceError('ANCESTRY_LIMIT')
            if ref in active:
                raise ReferenceError('INVALID_RESOLVED_GRAPH')
            if ref in completed:
                continue
            if ref not in graph:
                # Missing a declared mutation base has its stable dedicated code.
                if any(m.base_ref==ref for m in proposal.mutations):
                    raise ReferenceError('UNRESOLVED_MUTATION')
                raise ReferenceError('INVALID_RESOLVED_GRAPH')
            active.add(ref)
            stack.append((ref,True))
            stack.extend((p,False) for p in graph[ref].parent_revision_refs)
    ancestry_work=0
    for mutation in proposal.mutations:
        if mutation.artifact_id not in owners or mutation.proposed_ref not in graph:
            raise ReferenceError('UNRESOLVED_MUTATION')
        if owners[mutation.artifact_id].kind not in ARTIFACT_KINDS:
            raise ReferenceError('UNSUPPORTED_ARTIFACT_KIND')
        if mutation.operation=='revise' and mutation.base_ref not in graph:
            raise ReferenceError('UNRESOLVED_MUTATION')
        seen=set()
        visiting=set()
        stack=[(mutation.proposed_ref,False)]
        while stack:
            ref,leaving=stack.pop()
            if leaving:
                visiting.remove(ref)
                seen.add(ref)
                continue
            ancestry_work+=1
            if ancestry_work>10000:
                raise ReferenceError('ANCESTRY_LIMIT')
            if ref in visiting:
                raise ReferenceError('INVALID_RESOLVED_GRAPH')
            if ref in seen:
                continue
            if ref not in graph:
                raise ReferenceError('INVALID_RESOLVED_GRAPH')
            visiting.add(ref)
            stack.append((ref,True))
            stack.extend((p,False) for p in graph[ref].parent_revision_refs)
        if mutation.operation=='create':
            if owners[mutation.artifact_id].head_revision_id is not None:
                raise ReferenceError('ARTIFACT_ALREADY_ADOPTED')
        else:
            if mutation.base_ref not in seen:
                raise ReferenceError('BASE_NOT_ANCESTOR')
    for ref in proposal.claim_refs:
        revision=graph.get(ref.owner_revision_ref)
        if revision is None or not any(c.claim_id==ref.claim_id and c.statement_digest==ref.statement_digest for c in revision.claims):
            raise ReferenceError('UNRESOLVED_CLAIM')
    return tuple(expand_requirement(t,proposal.ref,proposal.mutations,proposal.claim_refs,graph)
                 for t in proposal.review_requirement_templates if not t.deferred)


def validate_change_set(proposals: tuple[Proposal, ...],
                        controls: tuple[ProposalControl, ...]) -> Result[ChangeSet, DomainError]:
    """Return anticipated validation refusals; constructors remain strict.

    All values are supplied by the caller. This operation neither resolves data
    nor evaluates authorization, and it does not catch programming exceptions.
    """
    if type(proposals) is not tuple or type(controls) is not tuple or any(type(p) is not Proposal for p in proposals):
        return Result.failure(DomainError(DomainErrorCode.INVALID_CHANGE_SET))
    try:
        change_set=ChangeSet(tuple(p.ref for p in proposals))
    except ReferenceError as refusal:
        return Result.failure(from_reference_error(refusal))
    if len(controls)!=len(proposals) or any(type(c) is not ProposalControl for c in controls):
        return Result.failure(DomainError(DomainErrorCode.PROPOSAL_CONTROL_REQUIRED))
    control_map={c.proposal_ref:c for c in controls}
    if len(control_map)!=len(controls) or set(control_map)!=set(change_set.proposal_refs):
        return Result.failure(DomainError(DomainErrorCode.PROPOSAL_CONTROL_REQUIRED))
    if any(c.disposition!='available' for c in controls):
        return Result.failure(DomainError(DomainErrorCode.PROPOSAL_UNAVAILABLE))
    artifacts=[m.artifact_id for p in proposals for m in p.mutations]
    if len(artifacts)!=len(set(artifacts)):
        return Result.failure(DomainError(DomainErrorCode.DUPLICATE_MUTATION))
    specs=[p.implementation_intent for p in proposals if p.implementation_intent is not None]
    if specs and any(spec!=specs[0] for spec in specs):
        return Result.failure(DomainError(DomainErrorCode.IMPLEMENTATION_INTENT_CONFLICT))
    return Result.success(change_set)

"""Closed exact proposal-reference decoder."""
from ordessa_engineering.domain.common.mechanisms.codec import require_object, decode_tuple, decode_digest, decode_actor, decode_blob_ref, decode_selector
from ordessa_engineering.domain.common.outcomes.diagnostics import ReferenceError
from .refs import ProposalRef

def decode_proposal_ref(value):
    require_object(value, {'kind','realm_id','project_id','change_id','proposal_id','digest'}, code='INVALID_REVISION')
    if value['kind'] != 'proposal':
        raise ReferenceError('INVALID_SCHEMA')
    return ProposalRef(value['realm_id'],value['project_id'],value['change_id'],value['proposal_id'],decode_digest(value['digest']))

"""Finite content manifest for an Engineering repository baseline.

The tree digest is Ordessa's manifest digest, not a Git-native tree object ID.
This domain value does not inspect a checkout or verify blob bytes; the calling
application must read bytes through the same BlobStore authority and verify each
BlobRef digest and byte length before sealing.
"""
from __future__ import annotations

from dataclasses import dataclass
import hashlib
import re
from typing import Literal

from ordessa_infrastructure.encoding import canonical_bytes

from ..common.models.identity import Scope
from ..common.models.refs import BlobRef
from ..common.models.values import Digest, normalized_path, validate_id, validate_items
from ..common.outcomes.diagnostics import ReferenceError
from .baselines import RepositoryId, RepositorySnapshotRef


MAX_REPOSITORY_FILES = 4096
TREE_MANIFEST_SCHEMA = 'ordessa.repository-file-manifest/1'


@dataclass(frozen=True)
class RepositoryFile:
    """One normalized path and its content-addressed file blob."""
    path: str
    blob_ref: BlobRef

    def __post_init__(self):
        normalized_path(self.path)
        if type(self.blob_ref) is not BlobRef:
            raise ReferenceError('INVALID_REPOSITORY_FILE')


@dataclass(frozen=True)
class RepositoryBaseline:
    """Exact existing snapshot ref plus the finite manifest that defines its tree digest."""
    ref: RepositorySnapshotRef
    files: tuple[RepositoryFile, ...]

    def __post_init__(self):
        if type(self.ref) is not RepositorySnapshotRef:
            raise ReferenceError('INVALID_REPOSITORY_BASELINE')
        validate_items(self.files, RepositoryFile)
        if len(self.files) > MAX_REPOSITORY_FILES:
            raise ReferenceError('REPOSITORY_MANIFEST_TOO_LARGE')
        paths = tuple(item.path for item in self.files)
        if paths != tuple(sorted(paths)):
            raise ReferenceError('REPOSITORY_MANIFEST_NOT_SORTED')
        if len(paths) != len(set(paths)):
            raise ReferenceError('REPOSITORY_PATH_DUPLICATE')
        if _has_file_prefix_conflict(paths):
            raise ReferenceError('REPOSITORY_PATH_FILE_PREFIX_CONFLICT')
        _validate_content_metadata(self.files)
        expected = _tree_digest(self.files)
        if self.ref.tree_digest != expected:
            raise ReferenceError('REPOSITORY_TREE_DIGEST_MISMATCH')


def _validate_content_metadata(files: tuple[RepositoryFile, ...]) -> None:
    """The same content digest cannot carry contradictory size/media metadata."""
    by_digest: dict[tuple[str, str], tuple[int, str]] = {}
    for item in files:
        blob = item.blob_ref
        key = (blob.digest.algorithm, blob.digest.hex)
        metadata = (blob.byte_length, blob.media_type)
        previous = by_digest.setdefault(key, metadata)
        if previous != metadata:
            raise ReferenceError('REPOSITORY_BLOB_METADATA_MISMATCH')


def _has_file_prefix_conflict(paths: tuple[str, ...]) -> bool:
    present = set(paths)
    return any('/'.join(path.split('/')[:index]) in present
               for path in paths for index in range(1, len(path.split('/'))))


def _manifest_projection(files: tuple[RepositoryFile, ...]) -> dict:
    return {
        'schema': TREE_MANIFEST_SCHEMA,
        'files': [
            {'path': item.path,
             'digest': {'algorithm': item.blob_ref.digest.algorithm,
                        'hex': item.blob_ref.digest.hex},
             'byte_length': item.blob_ref.byte_length,
             'media_type': item.blob_ref.media_type}
            for item in files
        ],
    }


def _tree_digest(files: tuple[RepositoryFile, ...]) -> Digest:
    payload = canonical_bytes(_manifest_projection(files))
    return Digest('sha256', hashlib.sha256(payload).hexdigest())


def seal_repository_baseline(scope: Scope, repository_id: str, vcs: Literal['git', 'none'],
                             commit_id: str | None, files: tuple[RepositoryFile, ...],
                             dirty_overlay_digest: Digest | None = None) -> RepositoryBaseline:
    """Build the current RepositorySnapshotRef from a sorted content manifest.

    ``dirty_overlay_digest`` is caller-supplied evidence identity; this pure rule
    preserves it and does not infer whether a Git worktree is dirty.
    """
    if type(scope) is not Scope:
        raise ReferenceError('REPOSITORY_SCOPE_REQUIRED')
    validate_id(repository_id)
    if type(vcs) is not str or vcs not in {'git', 'none'}:
        raise ReferenceError('INVALID_REPOSITORY_VCS')
    if vcs == 'none' and commit_id is not None:
        raise ReferenceError('INVALID_REPOSITORY_COMMIT')
    if commit_id is not None and (type(commit_id) is not str
                                  or re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', commit_id) is None):
        raise ReferenceError('INVALID_REPOSITORY_COMMIT')
    if dirty_overlay_digest is not None and type(dirty_overlay_digest) is not Digest:
        raise ReferenceError('INVALID_REPOSITORY_OVERLAY_DIGEST')
    validate_items(files, RepositoryFile)
    if len(files) > MAX_REPOSITORY_FILES:
        raise ReferenceError('REPOSITORY_MANIFEST_TOO_LARGE')
    _validate_content_metadata(files)
    ordered = tuple(sorted(files, key=lambda item: item.path))
    paths = tuple(item.path for item in ordered)
    if len(paths) != len(set(paths)):
        raise ReferenceError('REPOSITORY_PATH_DUPLICATE')
    if _has_file_prefix_conflict(paths):
        raise ReferenceError('REPOSITORY_PATH_FILE_PREFIX_CONFLICT')
    ref = RepositorySnapshotRef(
        scope.realm_id, scope.project_id, RepositoryId(repository_id), vcs,
        commit_id, _tree_digest(ordered), dirty_overlay_digest)
    return RepositoryBaseline(ref, ordered)


__all__ = ['RepositoryFile', 'RepositoryBaseline', 'seal_repository_baseline',
           'MAX_REPOSITORY_FILES', 'TREE_MANIFEST_SCHEMA']

"""Closed canonical codec for RepositoryBaseline; no repository access."""
from dataclasses import asdict

from ordessa_infrastructure.encoding import canonical_bytes

from ..common.mechanisms.codec import canonical_value, decode_blob_ref, require_object
from ..common.outcomes.diagnostics import ReferenceError
from .baseline_codec import decode_repository_ref
from .repository_baseline import RepositoryBaseline, RepositoryFile


MAX_REPOSITORY_BASELINE_BYTES = 2 * 1024 * 1024


def repository_baseline_projection(value: RepositoryBaseline) -> dict:
    if type(value) is not RepositoryBaseline:
        raise ReferenceError('INVALID_REPOSITORY_BASELINE')
    return {
        'schema': 'ordessa.repository-baseline/1',
        'ref': asdict(value.ref),
        'files': [{'path': item.path, 'blob_ref': asdict(item.blob_ref)} for item in value.files],
    }


def encode_repository_baseline(value: RepositoryBaseline) -> bytes:
    raw = canonical_bytes(repository_baseline_projection(value))
    if len(raw) > MAX_REPOSITORY_BASELINE_BYTES:
        raise ReferenceError('REPOSITORY_BASELINE_TOO_LARGE')
    return raw


def decode_repository_baseline(raw: bytes) -> RepositoryBaseline:
    try:
        value = canonical_value(raw, maximum=MAX_REPOSITORY_BASELINE_BYTES)
        require_object(value, {'schema', 'ref', 'files'}, 'INVALID_REPOSITORY_BASELINE')
        if value['schema'] != 'ordessa.repository-baseline/1':
            raise ReferenceError('INVALID_REPOSITORY_BASELINE')
        files = value['files']
        if type(files) is not list or len(files) > 4096:
            raise ReferenceError('INVALID_REPOSITORY_BASELINE')
        decoded = []
        for item in files:
            require_object(item, {'path', 'blob_ref'}, 'INVALID_REPOSITORY_FILE')
            decoded.append(RepositoryFile(item['path'], decode_blob_ref(item['blob_ref'])))
        record = RepositoryBaseline(decode_repository_ref(value['ref']), tuple(decoded))
        if encode_repository_baseline(record) != raw:
            raise ReferenceError('INVALID_REPOSITORY_BASELINE')
        return record
    except (KeyError, TypeError, ValueError, AttributeError, OverflowError, RecursionError):
        raise ReferenceError('INVALID_REPOSITORY_BASELINE') from None


__all__ = ['repository_baseline_projection', 'encode_repository_baseline',
           'decode_repository_baseline', 'MAX_REPOSITORY_BASELINE_BYTES']

"""Exact ChangeSet business outcomes; unexpected programming errors still raise."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Generic, TypeVar

from .errors import DomainError

T = TypeVar("T")
E = TypeVar("E", bound=DomainError)


@dataclass(frozen=True)
class Result(Generic[T, E]):
    """A success value (including None) or the original stable DomainError.

    This value does not catch exceptions, serialize output, or confer authority.
    Callers must inspect ok/error rather than the object's truthiness.
    """

    value: T | None = None
    error: E | None = None

    def __post_init__(self) -> None:
        if self.error is not None:
            if type(self.error) is not DomainError:
                raise TypeError("Result failure requires DomainError")
            if self.value is not None:
                raise ValueError("Result cannot contain both value and error")

    @property
    def ok(self) -> bool:
        return self.error is None

    @classmethod
    def success(cls, value: T) -> Result[T, E]:
        return cls(value=value)

    @classmethod
    def failure(cls, error: E) -> Result[T, E]:
        if type(error) is not DomainError:
            raise TypeError("Result failure requires DomainError")
        return cls(error=error)

    def __bool__(self) -> bool:
        raise TypeError("Inspect Result.ok or Result.error explicitly")

