            if set(c.file_change_ids) != {f.change_id for f in self.file_changes if c.proposal_ref in f.proposal_refs} or not set(c.output_refs) <= set(self.output_refs):
                raise ReferenceError('INVALID_SUBMISSION_COVERAGE')
