MAX_SUBMISSION_BYTES = 2 * 1024 * 1024
_CODE = 'INVALID_SUBMISSION'


def _execution_projection(value):
    result = projection(value)
    result['owner_provider_ref_bytes'] = decode_json(value.owner_provider_ref_bytes)
    return result


def _output_projection(value):
    if type(value) is BlobRef:
        return {'kind':'blob', **asdict(value)}
    return asdict(value)


def _coverage_projection(value):
    result = projection(value)
    result['output_refs'] = [_output_projection(x) for x in value.output_refs]
    result['evidence_refs'] = [_output_projection(x) for x in value.evidence_refs]
    return result


def _test_projection(value):
    result = projection(value)
    result['execution_ref'] = _execution_projection(value.execution_ref)
    return result


def submission_projection(value):
    if type(value) is not Submission:
        raise ReferenceError(_CODE)
    body = value.hash_payload()
    # Persist exact opaque blob locations alongside identity digest semantics.
    body.update({name: projection(getattr(value, name)) for name in (
        'authorization_refs','package_ref','execution_ref','baseline_snapshots','resulting_snapshots',
        'commit_refs','file_changes','effect_observations','source_refs','checkpoint_ref')})
    body['test_evidence'] = [_test_projection(x) for x in value.test_evidence]
    body['output_refs'] = [_output_projection(x) for x in value.output_refs]
    body['coverage'] = [_coverage_projection(x) for x in value.coverage]
    body['change_set'] = {'proposal_refs':[asdict(x) for x in value.change_set.proposal_refs], 'digest':asdict(value.change_set.digest)}
    if value.execution_ref is not None:
        body['execution_ref'] = _execution_projection(value.execution_ref)
    if value.method_content is not None:
        body['method_content'] = value.method_content.projection()
    body['digest'] = asdict(value.digest)
    return body


def encode_submission(value: Submission) -> bytes:
    raw = canonical_bytes(submission_projection(value))
    if len(raw) > MAX_SUBMISSION_BYTES:
        raise ReferenceError('SUBMISSION_TOO_LARGE')
    return raw


def _tuple(v, parser):
    return decode_tuple(v, parser, _CODE)


def _execution(v):
    require_object(v, {'environment_namespace','unit_id','owner_provider_ref_bytes','source_revision','operation_ref','prompt_input_digest','captured_observation_ref'}, _CODE)
    owner_bytes = canonical_bytes(v['owner_provider_ref_bytes'])
    return ExecutionRecordRef(v['environment_namespace'],v['unit_id'],owner_bytes,v['source_revision'],v['operation_ref'],decode_digest(v['prompt_input_digest']),decode_blob_ref(v['captured_observation_ref']))


def _changeset(v):
    require_object(v, {'proposal_refs','digest'}, _CODE)
    value = ChangeSet(_tuple(v['proposal_refs'],decode_proposal_ref))
    if value.digest != decode_digest(v['digest']): raise ReferenceError(_CODE)
    return value


def _commit(v):
    require_object(v, {'repository_id','commit_id','tree_digest'}, _CODE)
    return CommitRef(v['repository_id'],v['commit_id'],decode_digest(v['tree_digest']))


def _file_change(v):
    require_object(v, {'change_id','repository_id','normalized_path','operation','before_blob_digest','after_blob_digest','rename_from','proposal_refs'}, _CODE)
    return FileChange(v['change_id'],v['repository_id'],v['normalized_path'],v['operation'],None if v['before_blob_digest'] is None else decode_digest(v['before_blob_digest']),None if v['after_blob_digest'] is None else decode_digest(v['after_blob_digest']),v['rename_from'],_tuple(v['proposal_refs'],decode_proposal_ref))


def _test(v):
    require_object(v, {'check_id','requirement_id','subject_snapshot','execution_ref','result','observation_ref','tool_version','measured_at'}, _CODE)
    return TestEvidence(v['check_id'],v['requirement_id'],decode_repository_ref(v['subject_snapshot']),_execution(v['execution_ref']),v['result'],decode_blob_ref(v['observation_ref']),v['tool_version'],v['measured_at'])


def _effect(v):
    require_object(v, {'effect_id','action','target_ref','observed_state','evidence_refs','reversible','compensation_ref'}, _CODE)
    require_object(v['target_ref'], {'target_id','constraint_digest'}, _CODE)
    target = EffectTargetRef(v['target_ref']['target_id'],decode_digest(v['target_ref']['constraint_digest']))
    return EffectObservation(v['effect_id'],v['action'],target,v['observed_state'],_tuple(v['evidence_refs'],decode_blob_ref),v['reversible'],None if v['compensation_ref'] is None else decode_blob_ref(v['compensation_ref']))


def _output(v):
    if type(v) is not dict: raise ReferenceError(_CODE)
    if v.get('kind') == 'blob':
        require_object(v, {'kind','digest','byte_length','media_type','storage_object_id'}, _CODE)
        return decode_blob_ref({k:v[k] for k in ('digest','byte_length','media_type','storage_object_id')})
    return decode_artifact_ref(v)


def _coverage(v):
    require_object(v, {'proposal_ref','output_refs','file_change_ids','evidence_refs','disposition','reason'}, _CODE)
    return SubmissionCoverage(decode_proposal_ref(v['proposal_ref']),_tuple(v['output_refs'],_output),_tuple(v['file_change_ids'], lambda item: item),_tuple(v['evidence_refs'],_output),v['disposition'],v['reason'])


def _content(v):
    if v is None: return None
    require_object(v, {'schema_ref','value','rendered_body_ref'}, _CODE)
    return MethodContent.from_value(decode_exact_method_resource(v['schema_ref']),v['value'],None if v['rendered_body_ref'] is None else decode_blob_ref(v['rendered_body_ref']))


def decode_submission(raw: bytes) -> Submission:
    try:
        v = canonical_value(raw, maximum=MAX_SUBMISSION_BYTES)
        require_object(v, {'realm_id','project_id','submission_id','created_at','created_by','change_set','authorization_refs','package_ref','execution_ref','baseline_snapshots','resulting_snapshots','commit_refs','file_changes','output_refs','test_evidence','effect_observations','coverage','source_refs','method_content','checkpoint_ref','digest'}, _CODE)
        record = Submission(decode_scope({'realm_id':v['realm_id'],'project_id':v['project_id']}),v['submission_id'],v['created_at'],decode_actor(v['created_by']),_changeset(v['change_set']),_tuple(v['authorization_refs'],decode_approval_ref),decode_package_ref(v['package_ref']),_execution(v['execution_ref']),_tuple(v['baseline_snapshots'],decode_repository_ref),_tuple(v['resulting_snapshots'],decode_repository_ref),_tuple(v['commit_refs'],_commit),_tuple(v['file_changes'],_file_change),_tuple(v['output_refs'],_output),_tuple(v['test_evidence'],_test),_tuple(v['effect_observations'],_effect),_tuple(v['coverage'],_coverage),_tuple(v['source_refs'],decode_source),_content(v['method_content']),None if v['checkpoint_ref'] is None else decode_blob_ref(v['checkpoint_ref']))
        if record.digest != decode_digest(v['digest']) or encode_submission(record) != raw:
            raise ReferenceError(_CODE)
        return record
    except (KeyError,TypeError,ValueError,AttributeError,OverflowError,RecursionError):
        raise ReferenceError(_CODE) from None


__all__ = ['submission_projection','encode_submission','decode_submission','MAX_SUBMISSION_BYTES']

"""Strict common value/canonical helpers; no business type catalog or decoder registry."""
from dataclasses import fields, is_dataclass
from ordessa_infrastructure.encoding import canonical_bytes, decode_json
from ..models.refs import BlobRef
from ..models.values import Digest
from ..models.identity import Scope, ActorRef
from ..models.selection import ContentSelector
from ..outcomes.diagnostics import ReferenceError

def projection(value, *, identity=False):
    if type(value) is BlobRef and identity:
        return value.identity_projection()
    if is_dataclass(value):
        return {f.name: projection(getattr(value, f.name), identity=identity) for f in fields(value)}
    if type(value) is tuple:
        return [projection(item, identity=identity) for item in value]
    return value


def canonical_value(raw: bytes, *, maximum: int = 2 * 1024 * 1024):
    """Decode strict canonical bytes without rewriting their representation."""
    try:
        if type(raw) is not bytes or len(raw) > maximum:
            raise ReferenceError("INVALID_RECORD_BYTES")
        value = decode_json(raw)
        if canonical_bytes(value) != raw:
            raise ReferenceError("INVALID_RECORD_BYTES")
        return value
    except (ValueError, TypeError, RecursionError, OverflowError):
        raise ReferenceError("INVALID_RECORD_BYTES") from None


def require_object(value, keys, code):
    if type(value) is not dict or set(value) != set(keys):
        raise ReferenceError(code)
    return value


def decode_tuple(value, parser, code, *, maximum=4096):
    if type(value) is not list or maximum is not None and len(value) > maximum:
        raise ReferenceError(code)
    return tuple(parser(item) for item in value)


def decode_digest(value):
    require_object(value, {"algorithm", "hex"}, "INVALID_SCHEMA")
    return Digest(value["algorithm"], value["hex"])


def decode_actor(value):
    require_object(value, {"actor_id", "actor_kind", "issuer"}, "INVALID_SCHEMA")
    return ActorRef(**value)


def decode_blob_ref(value):
    require_object(value, {"digest", "byte_length", "media_type", "storage_object_id"}, "INVALID_BLOB_REF")
    return BlobRef(decode_digest(value["digest"]), value["byte_length"], value["media_type"],
                   value["storage_object_id"])


def decode_selector(value):
    require_object(value, {"kind", "start", "end", "pointer", "schema_version"}, "INVALID_SELECTOR")
    return ContentSelector(**value)


def decode_scope(value):
    require_object(value, {'realm_id','project_id'}, 'INVALID_SCHEMA')
    return Scope(value['realm_id'], value['project_id'])

"""Domain-prefixed digest v1 over projections supplied by business owners."""
import re
from ordessa_infrastructure.encoding import canonical_bytes, sha256
from ordessa_engineering.domain.common.outcomes.diagnostics import (ReferenceError)
from ordessa_engineering.domain.common.models.values import (Digest)

def record_digest(record_type: str, payload: object) -> Digest:
    if type(record_type) is not str or not re.fullmatch(r"[a-z][a-z0-9_-]{0,127}", record_type):
        raise ReferenceError("INVALID_SCHEMA")
    try:
        encoded = canonical_bytes(payload)
    except (ValueError, TypeError, RecursionError, OverflowError):
        raise ReferenceError("INVALID_SCHEMA") from None
    return Digest("sha256", sha256(f"ordessa/{record_type}/v1\n".encode() + encoded).hex())

"""Bounded selection and digest checks on supplied bytes; no fetching or trust verdict."""
import hashlib
import re

from ordessa_infrastructure.encoding import canonical_bytes, decode_json
from ordessa_engineering.domain.common.models.selection import (ContentSelector, MAX_CONTENT_BYTES)
from ..models.values import Digest
from ..outcomes.diagnostics import ReferenceError

def select_bytes(raw, selector):
    if type(raw) is not bytes or len(raw) > MAX_CONTENT_BYTES or type(selector) is not ContentSelector:
        raise ReferenceError('INVALID_SELECTOR')
    if selector.kind == 'whole_capture':
        return raw
    if selector.kind == 'byte_range':
        if selector.end > len(raw):
            raise ReferenceError('SELECTOR_OUT_OF_RANGE')
        return raw[selector.start:selector.end]
    try:
        value = decode_json(raw)
        for token in selector.pointer.split('/')[1:] if selector.pointer else ():
            token = token.replace('~1', '/').replace('~0', '~')
            if type(value) is list:
                if not re.fullmatch(r'0|[1-9][0-9]*', token) or len(token) > 10:
                    raise ReferenceError('INVALID_SELECTOR')
                value = value[int(token)]
            elif type(value) is dict:
                value = value[token]
            else:
                raise ReferenceError('SELECTOR_OUT_OF_RANGE')
        return canonical_bytes(value)
    except (ValueError, TypeError, KeyError, IndexError, RecursionError, OverflowError):
        raise ReferenceError('SELECTOR_OUT_OF_RANGE') from None

def verify_selection(raw, selector, expected):
    selected = select_bytes(raw, selector)
    if type(expected) is not Digest or hashlib.sha256(selected).hexdigest() != expected.hex:
        raise ReferenceError('STATEMENT_DIGEST_MISMATCH')
    return selected

class SelectorChecks:
    """Bound pure selection/hash work; cache only within one resolution."""
    def __init__(self):
        self.work = 0
        self.inputs = {}
        self.digests = {}
        self.selected = {}

    def check(self, raw, selector, expected=None):
        key = (id(raw), selector)
        if key not in self.digests:
            self.work += len(raw)
            if self.work > 64 * 1024 * 1024:
                raise ReferenceError('SELECTOR_WORK_LIMIT')
            selected = select_bytes(raw, selector)
            self.work += len(selected)
            if self.work > 64 * 1024 * 1024:
                raise ReferenceError('SELECTOR_WORK_LIMIT')
            self.inputs[id(raw)] = raw  # prevent an id being reused after GC
            self.digests[key] = hashlib.sha256(selected).hexdigest()
            self.selected[key] = selected
        if expected is not None and (type(expected) is not Digest or self.digests[key] != expected.hex):
            raise ReferenceError('STATEMENT_DIGEST_MISMATCH')
        return self.selected[key]

