"""Safe method validation/compilation entry points (pure method kernel orchestration).

These verify a caller-constructible projection against immutable captured bytes and
then delegate to the pure method kernels. They hold no publication or store authority.
"""
from __future__ import annotations

from copy import deepcopy

from .compilation.compiler import _compile_captured_method
from .definitions.contracts.validation import ValidationReport
from .definitions.errors import Diagnostic, MethodError, MethodFailure, MethodResult
from .definitions.models import CompiledMethod, CompilationCapabilities, LoadedMethod
from .loading.captured import verify_loaded_method
from .validation.compatibility import validate_compatibility


def validate_method(loaded: LoadedMethod, capabilities: CompilationCapabilities) -> ValidationReport:
    """Validate structure/references and injected capability compatibility.

    A fixture catalog may support design-time validation, but its warning is
    retained and never upgraded to a production-activation claim.
    """
    try:
        verified = verify_loaded_method(loaded)
        return validate_compatibility(verified, deepcopy(capabilities))
    except MethodFailure as exc:
        error = exc.error
        return ValidationReport(False, "compatibility", (Diagnostic(
            error.code, "error", error.message, error.resource_id,
            error.path, error.pointer,
        ),), registry_snapshot_ref=capabilities.registry_snapshot_ref)
    except (AttributeError, TypeError, ValueError, KeyError):
        return ValidationReport(False, "compatibility", (Diagnostic(
            "METHOD_VALIDATION_FAILED", "error", "method validation failed safely",
        ),), registry_snapshot_ref=capabilities.registry_snapshot_ref)


def compile_method(loaded: LoadedMethod, capabilities: CompilationCapabilities,
                   compiler_version: str) -> MethodResult[CompiledMethod]:
    """Rebuild caller-constructible caches from immutable bytes before compilation."""
    if not isinstance(compiler_version, str) or not compiler_version.strip():
        return MethodResult.failure(MethodError("COMPILER_VERSION_INVALID", "compiler version must be a non-empty string"))
    try:
        rebuilt = verify_loaded_method(loaded)
        captured_capabilities = deepcopy(capabilities)
    except MethodFailure as exc:
        return MethodResult.failure(exc.error)
    except (AttributeError, TypeError, ValueError, KeyError, RecursionError):
        return MethodResult.failure(MethodError("LOADED_PROJECTION_INVALID", "loaded method projection could not be verified against captured bytes"))
    return _compile_captured_method(rebuilt, captured_capabilities, compiler_version)


__all__ = ["validate_method", "compile_method"]

"""Reconstruct parsed projections from immutable captured source bytes."""
from __future__ import annotations

import hashlib
import unicodedata
from typing import Any

from ..definitions.models.identity import method_digest
from ..definitions.errors import MethodError, MethodFailure
from ..definitions.models import (
    LoadedMethod, LoadLimits, MethodIdentity, ResourceBytes, SourceResourceView,
    SourceBundle, ParsedContent, ParsedResource, ParsedSourceBundle,
)
from ..validation.structure import (
    validate_manifest_structure,
    validate_resource_fields, validate_resource_values,
)
from .parsing import parse_document
from ..validation.references import validate_logical_path


def captured_manifest(manifest_capture: ResourceBytes, limits: LoadLimits = LoadLimits()) -> dict[str, Any]:
    """Pure bounded manifest reconstruction, shared by source and stored-blob loading."""
    if any(type(getattr(limits, name)) is not int or getattr(limits, name) <= 0
           for name in limits.__dataclass_fields__):
        raise MethodFailure(MethodError("LOAD_LIMITS_INVALID", "all load limits must be positive integers"))
    manifest_bytes = manifest_capture.data
    if not isinstance(manifest_bytes, bytes) or len(manifest_bytes) > limits.manifest_bytes:
        raise MethodFailure(MethodError("RESOURCE_TOO_LARGE", "captured manifest is invalid or exceeds its byte limit", path="method.yaml"))
    manifest = validate_manifest_structure(parse_document(
        manifest_bytes, "application/yaml", "method.yaml", depth_limit=limits.structure_depth,
    ))
    if len(manifest["resources"]) > limits.total_resources:
        raise MethodFailure(MethodError("RESOURCE_COUNT_INVALID", "captured resource count exceeds its limit", path="method.yaml"))
    return manifest


def parse_captured_resource(capture: ResourceBytes, limits: LoadLimits = LoadLimits()) -> Any:
    """Pure strict syntax checking at each captured-resource read boundary.

    The caller owns byte budgets and declaration checks at their existing stage;
    this helper preserves parser error order without reading another resource.
    """
    return parse_document(capture.data, capture.media_type, capture.logical_path,
                          depth_limit=limits.structure_depth)


def rebuild_source_bundle(bundle: SourceBundle) -> ParsedSourceBundle:
    """Parse the bundle's captured bytes and reject mutable projection drift."""
    limits = bundle.limits
    manifest_bytes = bundle.manifest_bytes
    manifest = captured_manifest(bundle.manifest_capture, limits)
    total = len(manifest_bytes)
    identity = MethodIdentity(manifest["method_id"], manifest["release_version"], manifest["schema_version"])

    captured_by_path: dict[str, ResourceBytes] = {}
    for original in bundle.resources:
        captured = original.captured
        if not isinstance(captured.data, bytes) or len(captured.data) > limits.resource_bytes:
            raise MethodFailure(MethodError("RESOURCE_TOO_LARGE", "captured resource is invalid or exceeds its byte limit", path=captured.logical_path))
        total += len(captured.data)
        if captured.logical_path in captured_by_path:
            raise MethodFailure(MethodError("CAPTURED_RESOURCE_PATH_DUPLICATE", "captured source contains duplicate resource paths", path=captured.logical_path))
        if hashlib.sha256(captured.data).hexdigest() != captured.digest:
            raise MethodFailure(MethodError("CAPTURED_RESOURCE_DIGEST_MISMATCH", "captured resource bytes do not match their digest", path=captured.logical_path))
        captured_by_path[captured.logical_path] = captured

    if total > limits.total_bytes:
        raise MethodFailure(MethodError("RESOURCE_TOTAL_TOO_LARGE", "captured bundle exceeds its byte limit"))
    resources: dict[str, ParsedResource] = {}
    seen_paths: dict[str, str] = {}
    for index, declaration in enumerate(manifest["resources"]):
        pointer = f"/resources/{index}"
        validate_resource_fields(declaration, manifest_path="method.yaml", pointer=pointer)
        resource_id = declaration.get("id")
        path = validate_logical_path(declaration.get("path"))
        media_type = declaration.get("media_type")
        expected_digest = declaration.get("sha256")
        validate_resource_values(declaration, manifest_path="method.yaml", pointer=pointer)
        if resource_id in resources:
            raise MethodFailure(MethodError("DUPLICATE_RESOURCE_ID", "resource ID is duplicated", path="method.yaml", pointer=f"{pointer}/id"))
        path_key = unicodedata.normalize("NFC", path).casefold()
        if path_key in seen_paths:
            raise MethodFailure(MethodError("RESOURCE_PATH_COLLISION", "resource paths collide", resource_id=resource_id, path=path))
        seen_paths[path_key] = resource_id
        captured = captured_by_path.get(path)
        if captured is None:
            raise MethodFailure(MethodError("CAPTURED_RESOURCE_MISSING", "manifest resource has no captured bytes", resource_id=resource_id, path=path))
        if captured.media_type != media_type or captured.digest != expected_digest:
            raise MethodFailure(MethodError("CAPTURED_RESOURCE_DECLARATION_MISMATCH", "captured bytes differ from manifest media type or digest", resource_id=resource_id, path=path))
        value = parse_captured_resource(captured, limits)
        resources[resource_id] = ParsedResource(resource_id, ParsedContent(captured, value))
    if set(captured_by_path) != {item["path"] for item in manifest["resources"]}:
        raise MethodFailure(MethodError("CAPTURED_RESOURCE_SET_MISMATCH", "captured resources do not exactly match the manifest"))
    if set(resources) != {item.resource_id for item in bundle.resources}:
        raise MethodFailure(MethodError("CAPTURED_RESOURCE_SET_MISMATCH", "captured resource ids do not match the manifest"))
    return ParsedSourceBundle(bundle, ParsedContent(bundle.manifest_capture, manifest),
                              tuple(resources[key] for key in sorted(resources)))


def verify_loaded_method(loaded: LoadedMethod) -> LoadedMethod:
    limits = loaded.source_bundle.limits
    all_bytes = [loaded.manifest_bytes, *(item.captured.data for item in loaded.source_bundle.resources)]
    for raw in (loaded.bundle_lock_bytes, loaded.compiled_golden_bytes):
        if raw is not None:
            if not isinstance(raw, bytes) or len(raw) > limits.resource_bytes:
                raise MethodFailure(MethodError("RESOURCE_TOO_LARGE", "captured build evidence exceeds its byte limit"))
            all_bytes.append(raw)
    if sum(len(raw) for raw in all_bytes) > limits.total_bytes:
        raise MethodFailure(MethodError("RESOURCE_TOTAL_TOO_LARGE", "captured bundle including build evidence exceeds its byte limit"))
    expected = rebuild_source_bundle(loaded.source_bundle)
    if loaded.parsed_source != expected:
        raise MethodFailure(MethodError("LOADED_PROJECTION_INVALID", "parsed source view differs from captured bytes"))
    manifest = expected.manifest
    digest = loaded.manifest_digest
    lock = None
    golden = None
    if loaded.bundle_lock_bytes is None:
        if loaded.bundle_lock is not None or loaded.compiled_golden is not None or loaded.compiled_golden_bytes is not None:
            raise MethodFailure(MethodError("LOADED_LOCK_PROJECTION_MUTATED", "lock projection has no captured source bytes"))
    else:
        lock = parse_document(loaded.bundle_lock_bytes, "application/json", "bundle-lock.json", depth_limit=limits.structure_depth)
        if not isinstance(lock, dict) or loaded.bundle_lock != lock:
            raise MethodFailure(MethodError("LOADED_LOCK_PROJECTION_MUTATED", "bundle lock projection differs from captured bytes", path="bundle-lock.json"))
        if lock.get("manifest_sha256") != digest:
            raise MethodFailure(MethodError("BUNDLE_LOCK_MANIFEST_MISMATCH", "captured bundle lock does not bind the manifest", path="bundle-lock.json"))
        expected_resources = [{"id": item["id"], "sha256": item["sha256"]}
                              for item in sorted(manifest["resources"], key=lambda row: row["id"])]
        payload = lock.get("snapshot_payload")
        if (not isinstance(payload, dict)
                or payload.get("resource_digests") != expected_resources
                or payload.get("manifest_sha256") != digest
                or payload.get("required_capabilities") != manifest["requires"]
                or lock.get("method_ref", {}).get("snapshot_digest", {}).get("hex") != method_digest("method-snapshot", payload)):
            raise MethodFailure(MethodError("BUNDLE_LOCK_INVALID", "captured bundle lock does not match the captured method", path="bundle-lock.json"))
        if loaded.compiled_golden_bytes is None:
            if loaded.compiled_golden is not None:
                raise MethodFailure(MethodError("LOADED_GOLDEN_PROJECTION_MUTATED", "golden projection has no captured bytes"))
        else:
            golden = parse_document(loaded.compiled_golden_bytes, "application/json", lock["compiled_plan_path"], depth_limit=limits.structure_depth)
            if not isinstance(golden, dict) or loaded.compiled_golden != golden:
                raise MethodFailure(MethodError("LOADED_GOLDEN_PROJECTION_MUTATED", "compiled golden projection differs from captured bytes", path=lock["compiled_plan_path"]))
            expected_golden = lock.get("compiled_plan_digest", {}).get("hex")
            if expected_golden != method_digest("compiled-method-program", golden):
                raise MethodFailure(MethodError("COMPILED_GOLDEN_DIGEST_MISMATCH", "captured compiled golden digest is invalid", path=lock["compiled_plan_path"]))

    return LoadedMethod(loaded.source, loaded.source_bundle, expected, loaded.verification)

"""Bounded, strict loader for immutable method source bundles."""
from __future__ import annotations

import hashlib
import unicodedata
from pathlib import Path
from typing import Any

from ..definitions.errors import MethodError, MethodFailure, MethodResult
from ..definitions.models import (
    LoadLimits, LoadedMethod, MethodSource, ResourceBytes,
    CapturedResource, SourceBundle, VerificationInputs, ParsedContent, ParsedResource, ParsedSourceBundle,
)
from ..validation.structure import (
    validate_entry_structure, validate_manifest_structure,
    validate_requirement_structure, validate_requires_structure,
    validate_resource_fields, validate_resource_values,
)
from .parsing import parse_document
from ..validation.references import validate_logical_path
from ..definitions.models.identity import method_digest
from ..definitions.contracts.sources import ResourceReader


def _valid_json_object(value: Any, code: str, message: str, path: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise MethodFailure(MethodError(code, message, path=path))
    return value


def _read(reader: ResourceReader, source: MethodSource, path: str, max_bytes: int) -> bytes:
    logical = validate_logical_path(path)
    try:
        raw = reader.read(source, logical, max_bytes)
        if not isinstance(raw, bytes):
            raise MethodFailure(MethodError("RESOURCE_READER_INVALID", "resource reader must return immutable bytes", path=logical))
        if len(raw) > max_bytes:
            raise MethodFailure(MethodError("RESOURCE_TOO_LARGE", "resource exceeds its byte limit", path=logical))
        return raw
    except MethodFailure:
        raise
    except OSError as exc:
        raise MethodFailure(MethodError("RESOURCE_READ_FAILED", "method resource could not be read", path=logical)) from exc


class _ReadBudget:
    """Account every captured input, including manifest and build evidence."""

    def __init__(self, maximum: int):
        self.maximum = maximum
        self.used = 0

    def account(self, raw: bytes, path: str) -> None:
        self.used += len(raw)
        if self.used > self.maximum:
            raise MethodFailure(MethodError("RESOURCE_TOTAL_TOO_LARGE", "method bundle exceeds its byte limit", path=path))


def _load_optional_lock(reader: ResourceReader, source: MethodSource, manifest_bytes: bytes,
                        manifest: dict[str, Any], resources: dict[str, CapturedResource], limits: LoadLimits, budget: _ReadBudget
                        ) -> tuple[dict[str, Any] | None, dict[str, Any] | None, bytes | None, bytes | None]:
    try:
        lock_bytes = _read(reader, source, "bundle-lock.json", limits.resource_bytes)
    except MethodFailure as exc:
        if exc.error.code == "RESOURCE_NOT_FOUND":
            return None, None, None, None
        raise
    budget.account(lock_bytes, "bundle-lock.json")
    lock = _valid_json_object(parse_document(lock_bytes, "application/json", "bundle-lock.json", depth_limit=limits.structure_depth),
                              "BUNDLE_LOCK_INVALID", "bundle lock must be an object", "bundle-lock.json")
    actual_manifest_digest = hashlib.sha256(manifest_bytes).hexdigest()
    if lock.get("manifest_sha256") != actual_manifest_digest:
        raise MethodFailure(MethodError("MANIFEST_DIGEST_MISMATCH", "bundle lock does not match method.yaml", path="method.yaml"))
    expected_resources = [{"id": item["id"], "sha256": item["sha256"]} for item in sorted(manifest["resources"], key=lambda row: row["id"])]
    if lock.get("snapshot_payload", {}).get("resource_digests") != expected_resources:
        raise MethodFailure(MethodError("BUNDLE_LOCK_RESOURCE_MISMATCH", "bundle lock resource list differs from manifest", path="bundle-lock.json"))
    if lock.get("snapshot_payload", {}).get("manifest_sha256") != actual_manifest_digest:
        raise MethodFailure(MethodError("BUNDLE_LOCK_MANIFEST_MISMATCH", "bundle lock snapshot does not bind method.yaml", path="bundle-lock.json"))
    if lock.get("snapshot_payload", {}).get("required_capabilities") != manifest["requires"]:
        raise MethodFailure(MethodError("BUNDLE_LOCK_CAPABILITY_MISMATCH", "bundle lock capabilities differ from manifest", path="bundle-lock.json"))
    expected_snapshot = lock.get("method_ref", {}).get("snapshot_digest", {}).get("hex")
    if expected_snapshot != method_digest("method-snapshot", lock.get("snapshot_payload")):
        raise MethodFailure(MethodError("METHOD_SNAPSHOT_MISMATCH", "bundle lock snapshot digest is invalid", path="bundle-lock.json"))

    golden: dict[str, Any] | None = None
    golden_bytes: bytes | None = None
    plan_path = lock.get("compiled_plan_path")
    plan_digest = lock.get("compiled_plan_digest")
    if plan_path is not None:
        logical_plan_path = validate_logical_path(plan_path)
        golden_bytes = _read(reader, source, logical_plan_path, limits.resource_bytes)
        budget.account(golden_bytes, logical_plan_path)
        golden = _valid_json_object(parse_document(golden_bytes, "application/json", logical_plan_path, depth_limit=limits.structure_depth),
                                    "COMPILED_GOLDEN_INVALID", "compiled plan golden must be an object", logical_plan_path)
        if not isinstance(plan_digest, dict) or plan_digest.get("hex") != method_digest("compiled-method-program", golden):
            raise MethodFailure(MethodError("COMPILED_GOLDEN_DIGEST_MISMATCH", "compiled plan golden digest is invalid", path=logical_plan_path))
    return lock, golden, lock_bytes, golden_bytes


def load_method(source: MethodSource, reader: ResourceReader | None = None,
                limits: LoadLimits | None = None) -> MethodResult[LoadedMethod]:
    if reader is None:
        return MethodResult.failure(MethodError("RESOURCE_READER_UNAVAILABLE", "method loading requires an injected resource reader"))
    limits = limits or LoadLimits()
    try:
        if any(type(getattr(limits, name)) is not int or getattr(limits, name) <= 0
               for name in limits.__dataclass_fields__):
            raise MethodFailure(MethodError("LOAD_LIMITS_INVALID", "all load limits must be positive integers"))
        budget = _ReadBudget(limits.total_bytes)
        manifest_path = validate_logical_path(source.manifest_path)
        manifest_bytes = _read(reader, source, manifest_path, limits.manifest_bytes)
        budget.account(manifest_bytes, manifest_path)
        manifest = validate_manifest_structure(parse_document(manifest_bytes, "application/yaml", manifest_path,
                                                     depth_limit=limits.structure_depth))
        declarations = manifest.get("resources")
        if not isinstance(declarations, list) or not declarations or len(declarations) > limits.total_resources:
            raise MethodFailure(MethodError("RESOURCE_COUNT_INVALID", "method resource count is empty or exceeds its limit", path=manifest_path, pointer="/resources"))
        ids: set[str] = set()
        paths: dict[str, str] = {}
        loaded: dict[str, CapturedResource] = {}
        parsed_resources = {}
        for index, declaration in enumerate(declarations):
            pointer = f"/resources/{index}"
            validate_resource_fields(declaration, manifest_path=manifest_path, pointer=pointer)
            resource_id = declaration.get("id")
            path = validate_logical_path(declaration.get("path"))
            media_type = declaration.get("media_type")
            digest = declaration.get("sha256")
            if not isinstance(resource_id, str) or not resource_id or resource_id in ids:
                raise MethodFailure(MethodError("DUPLICATE_RESOURCE_ID", "resource ID is invalid or duplicated", path=manifest_path, pointer=f"{pointer}/id"))
            validate_resource_values(declaration, manifest_path=manifest_path, pointer=pointer)
            path_key = unicodedata.normalize("NFC", path).casefold()
            if path_key in paths:
                raise MethodFailure(MethodError("RESOURCE_PATH_COLLISION", f"path collides with resource {paths[path_key]}", resource_id=resource_id, path=path))
            ids.add(resource_id)
            paths[path_key] = resource_id
            raw = _read(reader, source, path, limits.resource_bytes)
            budget.account(raw, path)
            actual_digest = hashlib.sha256(raw).hexdigest()
            if actual_digest != digest:
                raise MethodFailure(MethodError("RESOURCE_DIGEST_MISMATCH", "resource bytes do not match manifest digest", resource_id=resource_id, path=path))
            captured = ResourceBytes(path, media_type, raw)
            value = parse_document(raw, media_type, path, depth_limit=limits.structure_depth)
            loaded[resource_id] = CapturedResource(resource_id, captured)
            parsed_resources[resource_id] = ParsedResource(resource_id, ParsedContent(captured, value))

        entry = manifest.get("entry")
        validate_entry_structure(entry, manifest_path=manifest_path)
        entry_resource = loaded.get(entry["resource"])
        if entry_resource is None or next(item for item in declarations if item["id"] == entry["resource"]).get("kind") != "workflow":
            raise MethodFailure(MethodError("MANIFEST_ENTRY_INVALID", "manifest entry must reference a declared workflow resource", resource_id=entry.get("resource"), path=manifest_path, pointer="/entry/resource"))

        capability_ids: set[str] = set()
        requires = manifest.get("requires")
        validate_requires_structure(requires, manifest_path=manifest_path)
        for index, requirement in enumerate(requires):
            validate_requirement_structure(requirement, manifest_path=manifest_path, pointer=f"/requires/{index}")
            capability_id = requirement.get("capability_id")
            if not isinstance(capability_id, str) or not capability_id or capability_id in capability_ids:
                raise MethodFailure(MethodError("DUPLICATE_CAPABILITY", "capability ID is invalid or duplicated", path=manifest_path, pointer=f"/requires/{index}/capability_id"))
            capability_ids.add(capability_id)

        bundle_lock, compiled_golden, bundle_lock_bytes, compiled_golden_bytes = _load_optional_lock(
            reader, source, manifest_bytes, manifest, loaded, limits, budget,
        )
        ordered_resources = tuple(loaded[key] for key in sorted(loaded))
        source_bundle = SourceBundle(ResourceBytes(manifest_path, "application/yaml", manifest_bytes), ordered_resources, limits)
        parsed_source = ParsedSourceBundle(source_bundle, ParsedContent(source_bundle.manifest_capture, manifest),
            tuple(parsed_resources[key] for key in sorted(parsed_resources)))
        verification = None if bundle_lock_bytes is None and compiled_golden_bytes is None else VerificationInputs(
            ParsedContent(ResourceBytes("bundle-lock.json", "application/json", bundle_lock_bytes), bundle_lock) if bundle_lock_bytes is not None else None,
            ParsedContent(ResourceBytes(bundle_lock["compiled_plan_path"], "application/json", compiled_golden_bytes), compiled_golden) if compiled_golden_bytes is not None else None,
        )
        return MethodResult.success(LoadedMethod(source, source_bundle, parsed_source, verification))
    except MethodFailure as exc:
        return MethodResult.failure(exc.error)
    except (AttributeError, OSError, ValueError, TypeError, KeyError):
        return MethodResult.failure(MethodError("METHOD_LOAD_FAILED", "method bundle could not be loaded safely", path=source.manifest_path))

"""The sole strict JSON/YAML resource parser; no file IO."""
from __future__ import annotations
import json
from typing import Any
import yaml
from yaml.events import (AliasEvent, MappingEndEvent, MappingStartEvent, ScalarEvent, SequenceEndEvent, SequenceStartEvent)
from ordessa_infrastructure.encoding import decode_json
from ..definitions.errors import MethodError, MethodFailure
from ..validation.values import validate_json_value

class _StrictLoader(yaml.SafeLoader):
    pass


def _construct_mapping(loader: _StrictLoader, node: yaml.MappingNode, deep: bool = False) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key_node, value_node in node.value:
        if key_node.tag == "tag:yaml.org,2002:merge":
            raise MethodFailure(MethodError("YAML_MERGE_KEY", "YAML merge keys are not supported"))
        key = loader.construct_object(key_node, deep=deep)
        if not isinstance(key, str):
            raise MethodFailure(MethodError("YAML_NON_STRING_KEY", "mapping keys must be strings"))
        if key in result:
            raise MethodFailure(MethodError("DUPLICATE_KEY", f"duplicate mapping key: {key}"))
        result[key] = loader.construct_object(value_node, deep=deep)
    return result


_StrictLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, _construct_mapping)


def _reject_aliases_anchors(text: str, path: str, depth_limit: int) -> None:
    container_depth = 0
    try:
        for event in yaml.parse(text, Loader=_StrictLoader):
            if isinstance(event, AliasEvent) or getattr(event, "anchor", None) is not None:
                raise MethodFailure(MethodError("YAML_ALIAS_OR_ANCHOR", "YAML aliases and anchors are not supported", path=path))
            # Root values are depth zero, matching validate_json_value. Count
            # containers before construction, including the depth of leaves.
            if isinstance(event, (MappingStartEvent, SequenceStartEvent, ScalarEvent)):
                if container_depth > depth_limit:
                    raise MethodFailure(MethodError("STRUCTURE_TOO_DEEP", "resource exceeds the nesting limit", path=path))
            if isinstance(event, (MappingStartEvent, SequenceStartEvent)):
                container_depth += 1
            elif isinstance(event, (MappingEndEvent, SequenceEndEvent)):
                container_depth -= 1
    except yaml.YAMLError as exc:
        mark = getattr(exc, "problem_mark", None)
        raise MethodFailure(MethodError(
            "METHOD_PARSE_ERROR", "YAML could not be parsed", path=path,
            line=(mark.line + 1) if mark else None,
            column=(mark.column + 1) if mark else None,
        )) from exc


def parse_document(raw: bytes, media_type: str, path: str, *, depth_limit: int = 64) -> Any:
    try:
        text = raw.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise MethodFailure(MethodError("METHOD_ENCODING_ERROR", "resource must be UTF-8", path=path)) from exc
    try:
        if media_type in {"application/json", "application/schema+json"} or path.endswith(".json"):
            value = decode_json(text)
        elif media_type in {"application/yaml", "text/yaml", "application/x-yaml"} or path.endswith((".yaml", ".yml")):
            _reject_aliases_anchors(text, path, depth_limit)
            value = yaml.load(text, Loader=_StrictLoader)
        else:
            return text
    except MethodFailure:
        raise
    except RecursionError as exc:
        raise MethodFailure(MethodError(
            "STRUCTURE_TOO_DEEP", "resource exceeds the parser nesting limit", path=path,
        )) from exc
    except (yaml.YAMLError, ValueError, json.JSONDecodeError) as exc:
        mark = getattr(exc, "problem_mark", None)
        raise MethodFailure(MethodError(
            "METHOD_PARSE_ERROR", "resource could not be parsed", path=path,
            line=(mark.line + 1) if mark else None,
            column=(mark.column + 1) if mark else None,
        )) from exc
    validate_json_value(value, path=path, depth_limit=depth_limit)
    return value

"""Bundle and injected host-catalog compatibility validation."""
from __future__ import annotations

from collections.abc import Mapping

from ..definitions.contracts.validation import ValidationReport
from ..definitions.models.identity import method_digest
from ..definitions.errors import Diagnostic
from ..definitions.models import CapabilityDescriptor, CompilationCapabilities, LoadedMethod, LoadLimits
from .structure import validate_manifest_sections, validate_resource_structure
from .workflow import validate_workflow
from .schema import (
    validate_document_schemas, validate_question_sets, validate_resources,
    validate_standard_resources,
)
from .policies import validate_policies


def _capability_map(capabilities: CompilationCapabilities) -> tuple[dict[str, CapabilityDescriptor], list[Diagnostic]]:
    result: dict[str, CapabilityDescriptor] = {}
    diagnostics: list[Diagnostic] = []
    for descriptor in capabilities.capabilities:
        if descriptor.capability_id in result:
            diagnostics.append(Diagnostic(
                "DUPLICATE_HOST_CAPABILITY", "error",
                "host catalog contains a duplicate capability ID",
                pointer=f"/capabilities/{descriptor.capability_id}",
            ))
            continue
        if descriptor.kind not in {"operation", "check"}:
            diagnostics.append(Diagnostic(
                "CAPABILITY_KIND_INVALID", "error", "capability kind must be operation or check",
                pointer=f"/capabilities/{descriptor.capability_id}/kind",
            ))
        if not descriptor.capability_id or not descriptor.interface_version:
            diagnostics.append(Diagnostic(
                "CAPABILITY_DESCRIPTOR_INVALID", "error", "capability ID and interface version are required",
            ))
        if not isinstance(descriptor.contract, Mapping):
            diagnostics.append(Diagnostic(
                "CAPABILITY_CONTRACT_INVALID", "error", "capability contract must be a JSON object",
                pointer=f"/capabilities/{descriptor.capability_id}/contract",
            ))
            result[descriptor.capability_id] = descriptor
            continue
        try:
            actual = method_digest("capability-contract", descriptor.contract)
        except (TypeError, ValueError):
            actual = ""
        if actual != descriptor.contract_digest:
            diagnostics.append(Diagnostic(
                "CAPABILITY_CONTRACT_DIGEST_MISMATCH", "error",
                "host capability descriptor contract digest is invalid",
                pointer=f"/capabilities/{descriptor.capability_id}/contract_digest",
            ))
        result[descriptor.capability_id] = descriptor
    return result, diagnostics


def validate_compatibility(loaded: LoadedMethod, capabilities: CompilationCapabilities,
                           limits: LoadLimits | None = None) -> ValidationReport:
    limits = limits or loaded.load_limits
    diagnostics = validate_manifest_sections(loaded.manifest, loaded.resources)
    for resource_id, resource in loaded.resources.items():
        diagnostics.extend(validate_resource_structure(resource.value, resource.declaration["kind"], resource.captured.logical_path, resource_id))
    if diagnostics:
        return ValidationReport(False, "structural", tuple(diagnostics), registry_snapshot_ref=capabilities.registry_snapshot_ref)
    catalog, catalog_errors = _capability_map(capabilities)
    diagnostics.extend(catalog_errors)

    requirements = loaded.manifest.get("requires", [])
    required_ids: set[str] = set()
    for index, requirement in enumerate(requirements if isinstance(requirements, list) else []):
        if not isinstance(requirement, dict):
            continue
        capability_id = requirement.get("capability_id")
        if not isinstance(capability_id, str):
            continue
        required_ids.add(capability_id)
        descriptor = catalog.get(capability_id)
        pointer = f"/requires/{index}"
        if descriptor is None:
            diagnostics.append(Diagnostic(
                "UNKNOWN_CAPABILITY", "error", f"required capability is unavailable: {capability_id}",
                path="method.yaml", pointer=pointer,
            ))
            continue
        for key, actual in (("kind", descriptor.kind), ("interface_version", descriptor.interface_version),
                            ("contract_digest", descriptor.contract_digest)):
            if requirement.get(key) != actual:
                diagnostics.append(Diagnostic(
                    "CAPABILITY_REQUIREMENT_MISMATCH", "error",
                    f"required capability {key} differs from the injected host descriptor",
                    path="method.yaml", pointer=f"{pointer}/{key}",
                ))

    # Resource declarations that reference a capability are checked against the
    # injected catalog too; the design-fixture catalog is never loaded as trust.
    for resource_id, resource in loaded.resources.items():
        value = resource.value
        if resource.declaration.get("kind") == "standard" and isinstance(value, dict):
            for criterion_index, criterion in enumerate(value.get("criteria", []) if isinstance(value.get("criteria"), list) else []):
                checks = criterion.get("checks", []) if isinstance(criterion, dict) else []
                for check_index, check in enumerate(checks if isinstance(checks, list) else []):
                    capability_id = check.get("capability_id") if isinstance(check, dict) else None
                    if not isinstance(capability_id, str) or capability_id not in catalog:
                        diagnostics.append(Diagnostic(
                            "UNKNOWN_CAPABILITY", "error", f"standard check capability unavailable: {capability_id}",
                            resource_id, resource.captured.logical_path,
                            f"/criteria/{criterion_index}/checks/{check_index}/capability_id",
                        ))
                    else:
                        pointer = f"/criteria/{criterion_index}/checks/{check_index}"
                        descriptor = catalog[capability_id]
                        if capability_id not in required_ids:
                            diagnostics.append(Diagnostic(
                                "CAPABILITY_NOT_DECLARED", "error", "standard check capability must be declared in method.yaml requires",
                                resource_id, resource.captured.logical_path,
                                f"{pointer}/capability_id",
                            ))
                        if descriptor.kind != "check":
                            diagnostics.append(Diagnostic(
                                "CAPABILITY_KIND_MISMATCH", "error", "standard check points to a non-check capability",
                                resource_id, resource.captured.logical_path,
                                f"{pointer}/capability_id",
                            ))
                        version = check.get("interface_version")
                        if not isinstance(version, str) or not version:
                            diagnostics.append(Diagnostic(
                                "CHECK_INTERFACE_VERSION_INVALID", "error", "standard check requires a non-empty interface version",
                                resource_id, resource.captured.logical_path,
                                f"{pointer}/interface_version",
                            ))
                        elif version != descriptor.interface_version:
                            diagnostics.append(Diagnostic(
                                "CHECK_INTERFACE_VERSION_MISMATCH", "error", "standard check interface version differs from the injected capability",
                                resource_id, resource.captured.logical_path,
                                f"{pointer}/interface_version",
                            ))

    diagnostics.extend(validate_resources(loaded))
    diagnostics.extend(validate_document_schemas(loaded))
    diagnostics.extend(validate_standard_resources(loaded))
    diagnostics.extend(validate_policies(loaded))
    diagnostics.extend(validate_question_sets(loaded, limits))
    diagnostics.extend(validate_workflow(loaded, catalog, limits))
    if capabilities.trust_class not in {"host", "fixture"}:
        diagnostics.append(Diagnostic("TRUST_CLASS_INVALID", "error", "unknown capability catalog trust class"))
    elif capabilities.trust_class == "fixture":
        diagnostics.append(Diagnostic(
            "FIXTURE_CAPABILITIES_ONLY", "warning",
            "fixture capability bindings are not production host trust",
        ))
    errors = any(item.severity == "error" for item in diagnostics)
    return ValidationReport(
        valid=not errors,
        phase="compatibility",
        diagnostics=tuple(diagnostics),
        registry_snapshot_ref=capabilities.registry_snapshot_ref,
    )

"""Safety semantics of finite standards; declaration shapes live in definitions."""
from __future__ import annotations

from decimal import Decimal

from ..definitions.errors import Diagnostic
from ..definitions.models import LoadedMethod
from .nominal import nominal_declaration_error


def validate_policies(loaded: LoadedMethod) -> list[Diagnostic]:
    diagnostics: list[Diagnostic] = []
    for resource_id, resource in loaded.resources.items():
        if resource.declaration.get("kind") != "standard":
            continue
        path = resource.captured.logical_path

        def error(code: str, message: str, pointer: str) -> None:
            diagnostics.append(Diagnostic(code, "error", message, resource_id, path, pointer))

        for index, criterion in enumerate(resource.value["criteria"]):
            pointer = f"/criteria/{index}"
            if criterion["policy"]["unknown"] == "pass":
                error("UNKNOWN_CANNOT_PASS", "unknown check results cannot pass", f"{pointer}/policy/unknown")
            vocabulary = criterion.get("answer_vocabulary")
            nominal = False
            for check_index, check in enumerate(criterion['checks']):
                bindings = check['bindings']
                if 'nominal_answer_conversion' in bindings or 'quality_admission' in bindings:
                    nominal = True
                    options = tuple(o['option_id'] for o in vocabulary['options']) if vocabulary and vocabulary['kind']=='choice' else ()
                    code = nominal_declaration_error(bindings, options)
                    if code:
                        error(code, 'nominal conversion requires a complete finite choice map and independent manual quality gate',
                            f'{pointer}/checks/{check_index}/bindings')
            if nominal and (len(criterion['checks']) != 1 or criterion.get('decision_policy') is not None):
                error('NOMINAL_PROBABILITY_POLICY_CONFLICT', 'nominal conversion cannot replace or mix with probability policy', pointer)
            if vocabulary:
                kind = vocabulary["kind"]
                if kind == "choice":
                    ids = [item["option_id"] for item in vocabulary["options"]]
                    if len(ids) != len(set(ids)):
                        error("ANSWER_VOCABULARY_INVALID", "choice options require unique IDs", f"{pointer}/answer_vocabulary/options")
                elif kind == "score":
                    indexes = [item["index"] for item in vocabulary["levels"]]
                    ids = [item["level_id"] for item in vocabulary["levels"]]
                    if sorted(indexes) != list(range(len(indexes))) or len(ids) != len(set(ids)):
                        error("ANSWER_VOCABULARY_INVALID", "score levels require unique IDs and contiguous indices", f"{pointer}/answer_vocabulary/levels")
            policy = criterion.get("decision_policy")
            if policy is None:
                continue
            pp = f"{pointer}/decision_policy"
            if not vocabulary:
                error("DECISION_VOCABULARY_REQUIRED", "decision policy requires a finite answer vocabulary", pp)
                continue
            kind = vocabulary["kind"]
            thresholds = {key for key in policy if key.startswith("minimum_") or key == "maximum_p_true"}
            allowed = {"choice": {"minimum_selected_probability"}, "score": {"minimum_expected_index", "minimum_top_level_probability"}, "noul": {"maximum_p_true"}}[kind]
            if not thresholds or not thresholds.issubset(allowed):
                error("DECISION_POLICY_THRESHOLD_INVALID", "thresholds must match the answer vocabulary", pp)
            irrelevant = {"choice": {"above_threshold"}, "score": {"selected_option", "option_statuses", "above_threshold"}, "noul": {"selected_option", "option_statuses", "below_threshold"}}[kind]
            if irrelevant.intersection(policy):
                error("DECISION_POLICY_KIND_MISMATCH", "decision policy contains fields for another answer kind", pp)
            for key in thresholds:
                number = Decimal(policy[key])
                maximum = Decimal(len(vocabulary["levels"]) - 1) if key == "minimum_expected_index" and kind == "score" else Decimal(1)
                if number < 0 or number > maximum:
                    error("THRESHOLD_OUT_OF_RANGE", "threshold exceeds its finite answer range", f"{pp}/{key}")
            if policy["missing_evaluation"] == "pass":
                error("MISSING_EVALUATION_CANNOT_PASS", "missing evaluation cannot pass", f"{pp}/missing_evaluation")
            for key in ("above_threshold", "below_threshold"):
                if policy.get(key) == "pass":
                    error("UNSATISFIED_THRESHOLD_CANNOT_PASS", "failed threshold cannot pass", f"{pp}/{key}")
            if kind == "choice":
                option_ids = {item["option_id"] for item in vocabulary["options"]}
                statuses = policy.get("option_statuses", {})
                selected = policy.get("selected_option")
                if (selected not in option_ids or set(statuses) != option_ids
                        or statuses.get(selected) != "threshold_dependent"
                        or any(status == "threshold_dependent" for option, status in statuses.items() if option != selected)):
                    error("DECISION_OPTION_POLICY_INVALID", "choice policy must cover every option and bind the threshold to the selected option", pp)
                if "below_threshold" not in policy:
                    error("DECISION_THRESHOLD_DISPOSITION_MISSING", "choice policy must declare below-threshold disposition", pp)
            elif kind == "score":
                if "below_threshold" not in policy:
                    error("DECISION_THRESHOLD_DISPOSITION_MISSING", "score policy must declare below-threshold disposition", pp)
            elif "above_threshold" not in policy:
                error("DECISION_THRESHOLD_DISPOSITION_MISSING", "noul policy must declare above-threshold disposition", pp)
    return diagnostics

"""Path and reference checks shared by loading and validation."""
from __future__ import annotations

import re
import unicodedata
from pathlib import PurePosixPath
from urllib.parse import urldefrag, unquote, urljoin

from ..definitions.errors import MethodError, MethodFailure


def validate_logical_path(raw: str) -> str:
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        raise MethodFailure(MethodError("RESOURCE_PATH_INVALID", "resource path is empty or contains NUL"))
    if "\\" in raw or raw.startswith("/") or re.match(r"^[A-Za-z]:", raw) or "://" in raw:
        raise MethodFailure(MethodError("RESOURCE_PATH_INVALID", "resource path must be relative POSIX path", path=raw))
    path = PurePosixPath(raw)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in raw.split("/")):
        raise MethodFailure(MethodError("RESOURCE_ESCAPE", "resource path escapes the method root", path=raw))
    if unicodedata.normalize("NFC", raw) != raw:
        # Canonical paths prevent visually equivalent identities and make the
        # collision check stable across filesystems.
        raise MethodFailure(MethodError("RESOURCE_PATH_NOT_NORMALIZED", "resource path must use NFC Unicode", path=raw))
    return raw


def validate_resource_references(value: object, known: dict[str, dict], *, path: str) -> list[MethodError]:
    errors: list[MethodError] = []

    def walk(item: object, pointer: str) -> None:
        if isinstance(item, dict):
            resource_id = item.get("resource")
            if isinstance(resource_id, str):
                declaration = known.get(resource_id)
                if declaration is None:
                    errors.append(MethodError("UNKNOWN_RESOURCE", f"unknown resource reference: {resource_id}", path=path, pointer=pointer))
                elif "sha256" in item and item["sha256"] != declaration.get("sha256"):
                    errors.append(MethodError("RESOURCE_REFERENCE_DIGEST_MISMATCH", "resource reference digest does not match its declaration", resource_id=resource_id, path=path, pointer=pointer))
            resource_id = item.get("resource_id")
            if isinstance(resource_id, str) and resource_id not in known:
                errors.append(MethodError("UNKNOWN_RESOURCE", f"unknown resource reference: {resource_id}", path=path, pointer=pointer))
            for key, child in item.items():
                escaped = str(key).replace("~", "~0").replace("/", "~1")
                walk(child, f"{pointer}/{escaped}")
        elif isinstance(item, list):
            for index, child in enumerate(item):
                walk(child, f"{pointer}/{index}")

    walk(value, "")
    return errors


def validate_schema_refs(schema: object, *, resource_id: str, path: str,
                         schemas: dict[str, tuple[str, object]] | None = None) -> list[MethodError]:
    """Resolve bundled JSON Schema references without retrieval.

    ``schemas`` maps another bundle resource ID to its logical path and parsed
    schema. References may resolve within this document or to another supplied
    schema resource. No URI is fetched; an unresolved URI is always rejected.
    Nested ``$id`` values establish nested resources, and both anchors and
    JSON Pointer fragments are checked before validation proceeds.
    """
    errors: list[MethodError] = []
    supplied = schemas or {}
    # A private, deterministic URI namespace gives relative refs meaningful
    # semantics while preventing accidental resolution through the network.
    roots: dict[str, object] = {}
    anchors: dict[tuple[str, str], object] = {}
    identifiers: dict[int, str] = {}
    locations = {resource_id: (path, schema), **supplied}

    def register_tree(item: object, inherited_base: str, owner_id: str,
                      owner_path: str, pointer: str = "", *, root: bool = False) -> None:
        if isinstance(item, dict):
            base = inherited_base
            identifier = item.get("$id")
            if isinstance(identifier, str):
                absolute = urljoin(inherited_base, identifier)
                absolute, fragment = urldefrag(absolute)
                if fragment:
                    return
                base = absolute
                previous = roots.get(base)
                if previous is not None and previous is not item:
                    errors.append(MethodError(
                        "SCHEMA_ID_DUPLICATE", "schema resource identifier is duplicated",
                        resource_id=owner_id, path=owner_path,
                        pointer=f"{pointer}/$id",
                    ))
                    return
                roots[base] = item
                identifiers[id(item)] = base
            if root:
                roots[inherited_base] = item
                base = identifiers.get(id(item), inherited_base)
            for key_name in ("$anchor", "$dynamicAnchor"):
                anchor = item.get(key_name)
                if isinstance(anchor, str):
                    anchors[(base, anchor)] = item
            for key, child in item.items():
                if isinstance(child, (dict, list)):
                    escaped = str(key).replace("~", "~0").replace("/", "~1")
                    register_tree(child, base, owner_id, owner_path, f"{pointer}/{escaped}")
        elif isinstance(item, list):
            for index, child in enumerate(item):
                register_tree(child, inherited_base, owner_id, owner_path, f"{pointer}/{index}")

    bases: dict[str, str] = {}
    for schema_id, (schema_path, schema_value) in locations.items():
        location = "https://ordessa.invalid/method/" + schema_path
        # Root $id takes precedence as the JSON Schema base; retain the bundle
        # location as an alias so a sibling can explicitly reference it.
        roots[location] = schema_value
        declared_id = schema_value.get("$id") if isinstance(schema_value, dict) else None
        base = urljoin(location, declared_id) if isinstance(declared_id, str) else location
        base, fragment = urldefrag(base)
        if fragment:
            errors.append(MethodError("SCHEMA_ID_INVALID", "schema $id must not contain a fragment", resource_id=schema_id, path=schema_path, pointer="/$id"))
            base = location
        previous = roots.get(base)
        if previous is not None and previous is not schema_value:
            errors.append(MethodError(
                "SCHEMA_ID_DUPLICATE", "schema resource identifier is duplicated",
                resource_id=schema_id, path=schema_path, pointer="/$id",
            ))
        else:
            roots[base] = schema_value
        bases[schema_id] = base
        # Walk from the bundle location so a relative root $id is resolved
        # exactly once, as required by URI-reference semantics.
        register_tree(schema_value, location, schema_id, schema_path, root=True)

    def pointer_target(root_value: object, fragment: str) -> object | None:
        if fragment == "":
            return root_value
        if not fragment.startswith("/"):
            return None
        current = root_value
        # URI-fragment decoding already occurred in resolves. A second pass
        # would turn a literal percent sequence into a different pointer.
        for raw_token in fragment[1:].split("/"):
            if re.search(r"~(?:[^01]|$)", raw_token):
                return None
            token = raw_token.replace("~1", "/").replace("~0", "~")
            if isinstance(current, dict) and token in current:
                current = current[token]
            elif (isinstance(current, list) and re.fullmatch(r"0|[1-9][0-9]*", token)
                  and int(token) < len(current)):
                current = current[int(token)]
            else:
                return None
        return current

    def resolves(reference: str, base: str) -> bool:
        # urllib's relative URL joining drops non-hierarchical URN bases for
        # fragment-only references. Fragments keep the resource identity.
        absolute = urldefrag(base)[0] + reference if reference.startswith("#") else (base if reference == "" else urljoin(base, reference))
        document_uri, fragment = urldefrag(absolute)
        root_value = roots.get(document_uri)
        if root_value is None:
            return False
        if not fragment:
            return True
        decoded = unquote(fragment)
        if decoded.startswith("/"):
            return pointer_target(root_value, decoded) is not None
        return (document_uri, decoded) in anchors

    def walk(item: object, pointer: str, base: str, schema_id: str, schema_path: str) -> None:
        if isinstance(item, dict):
            node_base = identifiers.get(id(item), base)
            for ref_key in ("$ref", "$dynamicRef"):
                ref = item.get(ref_key)
                if ref is not None and (not isinstance(ref, str) or not resolves(ref, node_base)):
                    errors.append(MethodError(
                        "REMOTE_SCHEMA_REF",
                        "schema reference is unresolved in the supplied offline bundle",
                        resource_id=schema_id, path=schema_path,
                        pointer=f"{pointer}/{ref_key}",
                    ))
            for key, child in item.items():
                escaped = str(key).replace("~", "~0").replace("/", "~1")
                walk(child, f"{pointer}/{escaped}", node_base, schema_id, schema_path)
        elif isinstance(item, list):
            for index, child in enumerate(item):
                walk(child, f"{pointer}/{index}", base, schema_id, schema_path)

    for schema_id, (schema_path, schema_value) in locations.items():
        walk(schema_value, "", bases[schema_id], schema_id, schema_path)
    return errors

"""Static JSON Schema checks; no schema resolver may access the network."""
from __future__ import annotations

from typing import Any
from urllib.parse import unquote, urlsplit

from jsonschema import Draft202012Validator, SchemaError

from ..definitions.errors import Diagnostic
from ..definitions.models import LoadedMethod
from ..definitions.schemas import DRAFT_2020_12
from .references import validate_schema_refs


_SCHEMA_MAP_KEYWORDS = frozenset({"$defs", "properties", "patternProperties", "dependentSchemas"})
_SCHEMA_SINGLE_KEYWORDS = frozenset({
    "additionalProperties", "unevaluatedProperties", "propertyNames",
    "contains", "not", "if", "then", "else", "contentSchema", "items",
    "unevaluatedItems",
})
_SCHEMA_ARRAY_KEYWORDS = frozenset({"allOf", "anyOf", "oneOf", "prefixItems"})


def _schema_nodes(schema: object, pointer: str = ""):
    """Yield actual subschemas, skipping arbitrary example/default payloads."""
    if not isinstance(schema, dict):
        return
    yield schema, pointer
    for keyword in _SCHEMA_MAP_KEYWORDS:
        children = schema.get(keyword)
        if isinstance(children, dict):
            for name, child in children.items():
                if isinstance(child, dict):
                    escaped = str(name).replace("~", "~0").replace("/", "~1")
                    yield from _schema_nodes(child, f"{pointer}/{keyword}/{escaped}")
    for keyword in _SCHEMA_SINGLE_KEYWORDS:
        child = schema.get(keyword)
        if isinstance(child, dict):
            yield from _schema_nodes(child, f"{pointer}/{keyword}")
    for keyword in _SCHEMA_ARRAY_KEYWORDS:
        children = schema.get(keyword)
        if isinstance(children, list):
            for index, child in enumerate(children):
                if isinstance(child, dict):
                    yield from _schema_nodes(child, f"{pointer}/{keyword}/{index}")


def _is_reserved_core_id(identifier: str) -> bool:
    if identifier.lower().startswith("urn:ordessa:schema:"):
        return True
    try:
        parts = urlsplit(identifier)
    except ValueError:
        return False
    try:
        hostname = (parts.hostname or "").lower()
        port = parts.port
    except ValueError:
        # An invalid explicit port does not make a core host namespace safe
        # to claim; continue with the parsed host and path checks below.
        hostname = (parts.hostname or "").lower()
        port = -1
    if parts.scheme.lower() != "https" or hostname != "ordessa.invalid":
        return False
    path = unquote(parts.path)
    reserved_path = path.startswith(("/interfaces/", "/design/interfaces/"))
    return reserved_path and (port in (None, 443) or port == -1)


def validate_document_schemas(loaded: LoadedMethod) -> list[Diagnostic]:
    diagnostics: list[Diagnostic] = []
    for resource_id, resource in loaded.resources.items():
        if resource.declaration.get("kind") != "document_schema":
            continue
        schema = resource.value
        if not isinstance(schema, dict):
            diagnostics.append(Diagnostic("SCHEMA_INVALID", "error", "document schema must be an object", resource_id, resource.captured.logical_path))
            continue
        for schema_node, pointer in _schema_nodes(schema):
            dialect = schema_node.get("$schema")
            if dialect is not None and dialect != DRAFT_2020_12:
                diagnostics.append(Diagnostic(
                    "SCHEMA_DRAFT_UNSUPPORTED", "error",
                    "document schemas use JSON Schema Draft 2020-12",
                    resource_id, resource.captured.logical_path,
                    f"{pointer}/$schema",
                ))
            identifier = schema_node.get("$id")
            if isinstance(identifier, str) and _is_reserved_core_id(identifier):
                diagnostics.append(Diagnostic(
                    "SCHEMA_ID_RESERVED", "error",
                    "document schema IDs cannot occupy Ordessa core interface namespaces",
                    resource_id, resource.captured.logical_path,
                    f"{pointer}/$id",
                ))
        bundled_schemas = {
            other_id: (other.captured.logical_path, other.value)
            for other_id, other in loaded.resources.items()
            if other.declaration.get("kind") == "document_schema"
        }
        for error in validate_schema_refs(
            schema, resource_id=resource_id,
            path=resource.captured.logical_path, schemas=bundled_schemas,
        ):
            diagnostics.append(Diagnostic(error.code, "error", error.message, error.resource_id, error.path, error.pointer))
        try:
            Draft202012Validator.check_schema(schema)
        except SchemaError as exc:
            path = "/" + "/".join(str(part) for part in exc.absolute_path)
            diagnostics.append(Diagnostic("SCHEMA_INVALID", "error", "document schema is invalid", resource_id, resource.captured.logical_path, path))

    document_types: set[str] = set()
    for index, document in enumerate(loaded.manifest.get("documents", [])):
        pointer = f"/documents/{index}"
        document_type = document["document_type"]
        if document_type in document_types:
            diagnostics.append(Diagnostic("DUPLICATE_DOCUMENT_TYPE", "error", "document_type is duplicated", path="method.yaml", pointer=f"{pointer}/document_type"))
        document_types.add(document_type)
        for field, expected_kind in (("schema", "document_schema"), ("template", "document_template")):
            if field not in document:
                continue
            resource_id = document[field]["resource"]
            resource = loaded.resources.get(resource_id)
            if resource is None or resource.declaration.get("kind") != expected_kind:
                diagnostics.append(Diagnostic("DOCUMENT_SCHEMA_REF_INVALID" if field == "schema" else "DOCUMENT_TEMPLATE_REF_INVALID", "error", f"document {field} must reference a {expected_kind} resource", resource_id, path="method.yaml", pointer=f"{pointer}/{field}"))
    for role, reference in loaded.manifest.get("skills", {}).items():
        resource_id = reference["resource"]
        resource = loaded.resources.get(resource_id)
        if resource is None or resource.declaration.get("kind") != "skill":
            diagnostics.append(Diagnostic("SKILL_REF_INVALID", "error", "role must reference a skill resource", resource_id, path="method.yaml", pointer=f"/skills/{role}"))

    return diagnostics


def validate_resources(loaded: LoadedMethod) -> list[Diagnostic]:
    from ..validation.references import validate_resource_references

    diagnostics: list[Diagnostic] = []
    declarations = {key: dict(value.declaration) for key, value in loaded.resources.items()}
    for resource_id, resource in loaded.resources.items():
        if resource.value is None:
            continue
        for error in validate_resource_references(resource.value, declarations, path=resource.captured.logical_path):
            diagnostics.append(Diagnostic(error.code, "error", error.message, resource_id, error.path, error.pointer))
    for error in validate_resource_references(loaded.manifest, declarations, path="method.yaml"):
        diagnostics.append(Diagnostic(error.code, "error", error.message, error.resource_id, error.path, error.pointer))
    return diagnostics


def validate_standard_resources(loaded: LoadedMethod) -> list[Diagnostic]:
    """Check local identity uniqueness; shapes are defined in definitions."""
    diagnostics: list[Diagnostic] = []
    standard_ids: set[str] = set()
    for resource_id, resource in loaded.resources.items():
        if resource.declaration.get("kind") != "standard":
            continue
        standard = resource.value
        if standard["standard_id"] in standard_ids:
            diagnostics.append(Diagnostic("DUPLICATE_STANDARD_ID", "error", "standard identity is duplicated", resource_id, resource.captured.logical_path))
        standard_ids.add(standard["standard_id"])
        ids: set[str] = set()
        for index, criterion in enumerate(standard["criteria"]):
            if criterion["criterion_id"] in ids:
                diagnostics.append(Diagnostic("DUPLICATE_CRITERION", "error", "criterion ID is duplicated", resource_id, resource.captured.logical_path, f"/criteria/{index}"))
            ids.add(criterion["criterion_id"])
        for index, criterion in enumerate(standard["criteria"]):
            for check_index, check in enumerate(criterion["checks"]):
                bindings = check["bindings"]
                if "question_set" not in bindings:
                    continue
                pointer = f"/criteria/{index}/checks/{check_index}/bindings"
                ref = bindings["question_set"]
                resource_ref = ref.get("resource") if isinstance(ref, dict) else None
                question_resource = loaded.resources.get(resource_ref) if isinstance(resource_ref, str) else None
                if question_resource is None or question_resource.declaration.get("kind") != "question_set":
                    diagnostics.append(Diagnostic("QUESTION_SET_REF_INVALID", "error", "check binding must reference a question_set", resource_id, resource.captured.logical_path, pointer))
                    continue
                question_set = question_resource.value
                question_ids = bindings.get("question_ids")
                available = {question["question_id"] for question in question_set["questions"]}
                if question_ids is not None and (not isinstance(question_ids, list) or not question_ids or any(not isinstance(item, str) or item not in available for item in question_ids) or len(question_ids) != len(set(question_ids))):
                    diagnostics.append(Diagnostic("QUESTION_BINDING_INVALID", "error", "bound question IDs must exist and be unique", resource_id, resource.captured.logical_path, pointer))
                if "iteration" in bindings and bindings["iteration"] != question_set["iteration"]:
                    diagnostics.append(Diagnostic("QUESTION_ITERATION_MISMATCH", "error", "check iteration must match its question set", resource_id, resource.captured.logical_path, pointer))
                selected = question_ids if isinstance(question_ids, list) else available
                for question in question_set["questions"]:
                    if question["question_id"] not in selected:
                        continue
                    answer = question["answer_definition"]["from_criterion"]
                    if (answer["resource"], answer["criterion_id"]) != (resource_id, criterion["criterion_id"]):
                        diagnostics.append(Diagnostic("QUESTION_CRITERION_BINDING_MISMATCH", "error", "decision check must bind questions using its own criterion vocabulary", resource_id, resource.captured.logical_path, pointer))
    return diagnostics


def validate_question_sets(loaded: LoadedMethod, limits) -> list[Diagnostic]:
    diagnostics: list[Diagnostic] = []
    criteria: dict[tuple[str, str], dict[str, Any]] = {}
    for resource_id, resource in loaded.resources.items():
        if resource.declaration.get("kind") == "standard" and isinstance(resource.value, dict):
            for criterion in resource.value.get("criteria", []):
                if isinstance(criterion, dict) and isinstance(criterion.get("criterion_id"), str):
                    criteria[(resource_id, criterion["criterion_id"])] = criterion
    threshold_keys = {"threshold", "decision_policy", "minimum_selected_probability", "minimum_top_level_probability", "minimum_expected_index", "maximum_p_true"}

    def inspect_thresholds(value: Any, resource_id: str, path: str, pointer: str = "") -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                if key in threshold_keys:
                    diagnostics.append(Diagnostic("THRESHOLD_IN_QUESTION_SET", "error", "decision thresholds belong to standards, not question sets", resource_id, path, f"{pointer}/{key}"))
                inspect_thresholds(child, resource_id, path, f"{pointer}/{key}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                inspect_thresholds(child, resource_id, path, f"{pointer}/{index}")

    for resource_id, resource in loaded.resources.items():
        if resource.declaration.get("kind") != "question_set":
            continue
        question_set = resource.value
        path = resource.captured.logical_path
        questions = question_set["questions"]
        if len(questions) > limits.question_count:
            diagnostics.append(Diagnostic("QUESTION_COUNT_EXCEEDED", "error", "question set exceeds its static question limit", resource_id, path, "/questions"))
        inspect_thresholds(question_set, resource_id, path)
        ids: set[str] = set()
        for index, question in enumerate(questions):
            pointer = f"/questions/{index}"
            if question["question_id"] in ids:
                diagnostics.append(Diagnostic("DUPLICATE_QUESTION_ID", "error", "question IDs must be unique in a set", resource_id, path, f"{pointer}/question_id"))
            ids.add(question["question_id"])
            for criterion_ref in question.get("criterion_refs", []):
                if not isinstance(criterion_ref, dict) or (criterion_ref.get("resource"), criterion_ref.get("criterion_id")) not in criteria:
                    diagnostics.append(Diagnostic("UNKNOWN_CRITERION", "error", "question references an unknown criterion", resource_id, path, f"{pointer}/criterion_refs"))
            refs = {(ref["resource"], ref["criterion_id"]) for ref in question["criterion_refs"]}
            source = question["answer_definition"]["from_criterion"]
            if (source["resource"], source["criterion_id"]) not in refs:
                diagnostics.append(Diagnostic("ANSWER_CRITERION_NOT_DECLARED", "error", "answer source must be among the question criterion references", resource_id, path, f"{pointer}/answer_definition"))
            answer_from = question.get("answer_definition", {}).get("from_criterion") if isinstance(question.get("answer_definition"), dict) else None
            if isinstance(answer_from, dict):
                criterion = criteria.get((answer_from.get("resource"), answer_from.get("criterion_id")))
                if criterion is None:
                    diagnostics.append(Diagnostic("UNKNOWN_CRITERION", "error", "answer definition references an unknown criterion", resource_id, path, f"{pointer}/answer_definition/from_criterion"))
                else:
                    vocabulary = criterion.get("answer_vocabulary", {})
                    if not isinstance(vocabulary, dict) or vocabulary.get("kind") != question.get("kind"):
                        diagnostics.append(Diagnostic("QUESTION_VOCABULARY_MISMATCH", "error", "question and criterion answer types differ", resource_id, path, f"{pointer}/kind"))
    return diagnostics


# Pure content checking, using application-supplied program projection.
from copy import deepcopy
from collections.abc import Mapping
from urllib.parse import urljoin
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012
from referencing.exceptions import Unresolvable
from jsonschema.exceptions import SchemaError
from ..definitions.errors import MethodError, MethodFailure, MethodResult
from ..definitions.models import MethodSnapshot
from .values import validate_json_value

def _no_retrieval(uri):
    raise ValueError("external schema retrieval is unavailable")


def validate_document_content_data(snapshot: MethodSnapshot, document_type: str, method_content: Mapping, program: dict) -> MethodResult[None]:
    """The argument is a neutral wrapper; only its value is schema-validated."""
    try:
        matches = [item for item in program["documents"] if item["document_type"] == document_type]
        if len(matches) != 1:
            raise MethodFailure(MethodError("DOCUMENT_TYPE_UNAVAILABLE", "document type has no unique method binding"))
        if matches[0]["validation_target"] != "method_content":
            raise MethodFailure(MethodError("VALIDATION_TARGET_UNSUPPORTED", "only method_content.value is supported"))
        if not isinstance(method_content, Mapping) or "value" not in method_content:
            raise MethodFailure(MethodError("METHOD_CONTENT_INVALID", "method content must carry a value"))
        value = method_content["value"]
        validate_json_value(value, path="method_content.value")
        registry = Registry(retrieve=_no_retrieval)
        locations = {item.resource_id: item.logical_path for item in snapshot.resources}
        selected = None
        for item in program["schema_resources"]:
            location = "https://ordessa.invalid/method/" + locations[item["schema_resource"]["resource_id"]]
            schema = deepcopy(item["value_schema"])
            schema["$id"] = urljoin(location, schema.get("$id", location))
            resource = Resource.from_contents(schema, default_specification=DRAFT202012)
            registry = registry.with_resource(location, resource).with_resource(schema["$id"], resource)
            if item["schema_resource"] == next(doc["schema_resource"] for doc in program["documents"] if doc["document_type"] == document_type):
                selected = schema
        if not Draft202012Validator(selected, registry=registry.crawl()).is_valid(value):
            raise MethodFailure(MethodError("METHOD_CONTENT_INVALID", "method_content.value violates its document schema"))
        return MethodResult.success(None)
    except MethodFailure as exc:
        return MethodResult.failure(exc.error)
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError, LookupError, Unresolvable, SchemaError):
        return MethodResult.failure(MethodError("METHOD_SCHEMA_INVALID", "document content could not be validated safely"))

"""Local format checks; no loading dependency or source access."""
from typing import Any
import re
from jsonschema import Draft202012Validator
from ..definitions.errors import Diagnostic, MethodError, MethodFailure
from ..definitions.schemas import (MANIFEST_FIELDS_V1, MANIFEST_REQUIRED_FIELDS_V1, MANIFEST_SCHEMA_VERSION_V1, COMPILER_CONTRACT_V1, RESOURCE_FIELDS_V1, RESOURCE_KINDS_V1, RESOURCE_DIGEST_PATTERN_V1, MANIFEST_SECTIONS_SCHEMA_V1, RESOURCE_STRUCTURES_V1)
_RESOURCE_DIGEST_V1 = re.compile(RESOURCE_DIGEST_PATTERN_V1)

def valid_resource_digest(value: Any) -> bool:
    """V1 source declaration digest syntax (not content verification)."""
    return isinstance(value, str) and _RESOURCE_DIGEST_V1.fullmatch(value) is not None


def validate_manifest_structure(value: Any) -> dict[str, Any]:
    """Check the existing V1 envelope, returning the same unmodified mapping.

    Nested declarations are checked at their original loading stages so an
    invalid later declaration cannot move ahead of earlier read/path failures.
    """
    if not isinstance(value, dict):
        raise MethodFailure(MethodError("MANIFEST_INVALID", "method manifest must be an object", path="method.yaml"))
    extra = set(value) - MANIFEST_FIELDS_V1
    missing = MANIFEST_REQUIRED_FIELDS_V1 - set(value)
    if extra or missing:
        raise MethodFailure(MethodError("MANIFEST_FIELDS_INVALID", f"unknown fields={sorted(extra)} missing={sorted(missing)}", path="method.yaml"))
    if value.get("schema_version") != MANIFEST_SCHEMA_VERSION_V1 or type(value.get("schema_version")) is not int:
        raise MethodFailure(MethodError("METHOD_SCHEMA_UNSUPPORTED", "unsupported method manifest schema", path="method.yaml"))
    for field in ("method_id", "release_version", "compiler_contract"):
        if not isinstance(value.get(field), str) or not value[field]:
            raise MethodFailure(MethodError("MANIFEST_FIELD_INVALID", f"{field} must be a non-empty string", path="method.yaml", pointer=f"/{field}"))
    if value["compiler_contract"] != COMPILER_CONTRACT_V1:
        raise MethodFailure(MethodError("COMPILER_CONTRACT_UNSUPPORTED", "method bundle compiler contract is unsupported", path="method.yaml", pointer="/compiler_contract"))
    return value


def validate_resource_fields(declaration: Any, *, manifest_path: str, pointer: str) -> None:
    if not isinstance(declaration, dict):
        raise MethodFailure(MethodError("RESOURCE_DECLARATION_INVALID", "resource declaration must be an object", path=manifest_path, pointer=pointer))
    if set(declaration) != RESOURCE_FIELDS_V1:
        raise MethodFailure(MethodError("RESOURCE_DECLARATION_FIELDS_INVALID", "resource declaration fields must be exactly id, kind, path, media_type, and sha256", path=manifest_path, pointer=pointer))


def validate_resource_values(declaration: dict[str, Any], *, manifest_path: str, pointer: str) -> None:
    """Called after path/ID checks to preserve loading error precedence."""
    resource_id = declaration.get("id")
    kind = declaration.get("kind")
    media_type = declaration.get("media_type")
    if not isinstance(kind, str) or not isinstance(media_type, str) or not media_type:
        raise MethodFailure(MethodError("RESOURCE_DECLARATION_INVALID", "resource kind and media type are required", resource_id=resource_id, path=manifest_path, pointer=pointer))
    if kind not in RESOURCE_KINDS_V1:
        raise MethodFailure(MethodError("RESOURCE_KIND_UNSUPPORTED", "resource kind is not supported", resource_id=resource_id, path=manifest_path, pointer=f"{pointer}/kind"))
    if not valid_resource_digest(declaration.get("sha256")):
        raise MethodFailure(MethodError("RESOURCE_DIGEST_INVALID", "resource digest must be lowercase SHA-256", resource_id=resource_id, path=manifest_path, pointer=f"{pointer}/sha256"))


def validate_entry_structure(entry: Any, *, manifest_path: str) -> None:
    if (not isinstance(entry, dict) or set(entry) != {"resource"}
            or not isinstance(entry.get("resource"), str)):
        raise MethodFailure(MethodError("MANIFEST_ENTRY_INVALID", "manifest entry must name exactly one workflow resource", path=manifest_path, pointer="/entry"))


def validate_requires_structure(requires: Any, *, manifest_path: str) -> None:
    if not isinstance(requires, list):
        raise MethodFailure(MethodError("REQUIRES_INVALID", "requires must be a list", path=manifest_path, pointer="/requires"))


def validate_requirement_structure(requirement: Any, *, manifest_path: str, pointer: str) -> None:
    if not isinstance(requirement, dict):
        raise MethodFailure(MethodError("REQUIRES_INVALID", "capability requirement must be an object", path=manifest_path, pointer=pointer))


def _structure_errors(value: Any, schema: dict, *, path: str, resource_id: str | None = None) -> list[Diagnostic]:
    result = []
    for error in sorted(Draft202012Validator(schema).iter_errors(value), key=lambda e: str(list(e.absolute_path))):
        pointer = "/" + "/".join(str(part).replace("~", "~0").replace("/", "~1") for part in error.absolute_path)
        code = "METHOD_STRUCTURE_INVALID"
        parts = list(error.absolute_path)
        if ("checks" in parts and (parts[-1:] == ["interface_version"]
                or (error.validator == "required" and isinstance(error.instance, dict)
                    and "interface_version" not in error.instance))):
            code = "CHECK_INTERFACE_VERSION_INVALID"
            if error.validator == "required":
                pointer += "/interface_version"
        # Do not echo resource data, secret keys or schema values into diagnostics.
        result.append(Diagnostic(code, "error", "method declaration violates the supported structure",
                                 resource_id, path, pointer))
    return result


def validate_manifest_sections(manifest: Any, resources: Any) -> list[Diagnostic]:
    """Validate current declarations; resource relationships are checked elsewhere."""
    return _structure_errors(manifest, MANIFEST_SECTIONS_SCHEMA_V1, path="method.yaml")


def validate_resource_structure(value: Any, kind: str, path: str, resource_id: str) -> list[Diagnostic]:
    schema = RESOURCE_STRUCTURES_V1.get(kind)
    return _structure_errors(value, schema, path=path, resource_id=resource_id) if schema else []

