"""Explicit SQL source registration and the original per-file migration runner.

The registry holds deployment configuration, not a database. Connections,
source directories, namespace/version-table names and source ordering belong to
the caller. No default source, global registry or connection is created here.
Importing this module performs no discovery or filesystem/database operations.

Applying retains native executescript/commit behavior: version-table setup
commits first, then each script and ledger insertion commits individually.
This is not an atomic migration batch; failed scripts can leave partial effects.
"""
from dataclasses import dataclass
from pathlib import Path
import re
import sqlite3
import threading
from typing import Iterable

__all__ = [
    "MigrationSource", "MigrationRegistry", "register_migration_source",
    "registered_migration_sources", "apply_migration_source",
    "apply_registered_migrations",
]

_MIGRATION_NAME = re.compile(r"^(\d{3})_.*\.sql$")


@dataclass(frozen=True)
class MigrationSource:
    namespace: str
    directory: Path
    version_table: str


def _validate_source(source: MigrationSource) -> None:
    if not re.fullmatch(r"[a-z0-9_.-]+", source.namespace):
        raise ValueError(f"invalid migration namespace: {source.namespace!r}")
    if not re.fullmatch(r"[a-z0-9_]+", source.version_table):
        raise ValueError(f"invalid version table: {source.version_table!r}")


class MigrationRegistry:
    """Caller-owned ordered sources, followed by explicit reserved sources.

    trailing_sources preserves a caller's assembly-first/history-last policy
    without teaching the mechanism any historical namespace or SQL directory.
    Metadata conflicts are rejected; no SQL is read or executed at registration.
    """

    def __init__(self, *, trailing_sources: Iterable[MigrationSource] = ()) -> None:
        trailing = tuple(trailing_sources)
        for index, source in enumerate(trailing):
            _validate_source(source)
            for prior in trailing[:index]:
                if prior.namespace == source.namespace:
                    raise ValueError(f"migration namespace {source.namespace!r} is already reserved")
                if prior.version_table == source.version_table:
                    raise ValueError(f"migration version table {source.version_table!r} is already reserved")
        self._trailing = trailing
        self._assembly: list[MigrationSource] = []
        self._lock = threading.RLock()

    def register(self, source: MigrationSource) -> bool:
        _validate_source(source)
        with self._lock:
            for existing in self._assembly:
                if existing.namespace == source.namespace:
                    if (Path(existing.directory).resolve() != Path(source.directory).resolve()
                            or existing.version_table != source.version_table):
                        raise ValueError(
                            f"migration namespace {source.namespace!r} is already "
                            "registered with a different source"
                        )
                    return False
                if existing.version_table == source.version_table:
                    raise ValueError(
                        f"migration version table {source.version_table!r} is already "
                        f"owned by namespace {existing.namespace!r}"
                    )
            if any(source.namespace == tail.namespace for tail in self._trailing):
                raise ValueError("the historical migration namespace is reserved")
            if any(source.version_table == tail.version_table for tail in self._trailing):
                raise ValueError("the historical version table is reserved")
            self._assembly.append(source)
            return True

    def registered(self) -> tuple[MigrationSource, ...]:
        with self._lock:
            return (*self._assembly, *self._trailing)


def register_migration_source(source: MigrationSource, *, registry: MigrationRegistry) -> bool:
    return registry.register(source)


def registered_migration_sources(*, registry: MigrationRegistry) -> tuple[MigrationSource, ...]:
    return registry.registered()


def _ensure_version_table(conn: sqlite3.Connection, version_table: str) -> None:
    conn.execute(
        f"CREATE TABLE IF NOT EXISTS {version_table} "
        "(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (datetime('now')))"
    )
    conn.commit()


def apply_migration_source(conn: sqlite3.Connection, source: MigrationSource) -> None:
    _validate_source(source)
    _ensure_version_table(conn, source.version_table)
    current = conn.execute(
        f"SELECT MAX(version) FROM {source.version_table}"
    ).fetchone()[0] or 0
    directory = Path(source.directory)
    if not directory.is_dir():
        return
    files = sorted(
        (f for f in directory.iterdir() if _MIGRATION_NAME.match(f.name)),
        key=lambda f: f.name,
    )
    for path in files:
        version = int(_MIGRATION_NAME.match(path.name).group(1))
        if version <= current:
            continue
        conn.executescript(path.read_text(encoding="utf-8"))
        conn.execute(f"INSERT INTO {source.version_table} (version) VALUES (?)", (version,))
        conn.commit()


def apply_registered_migrations(conn: sqlite3.Connection, *, registry: MigrationRegistry) -> None:
    for source in registered_migration_sources(registry=registry):
        apply_migration_source(conn, source)

"""Business-neutral compare-and-swap record contracts for existing stores.

This module defines the shape and semantics of an optional technical store
capability. It opens no connection and owns no backend, transaction manager,
record lifecycle, authorization policy, or interpretation of stored values.
The existing store owner remains responsible for making request-result
idempotency and all supplied record writes atomic in its existing transaction.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping, Protocol, runtime_checkable

from ..identifiers import RequestKey

DOMAIN_STORE_VERSION = "domain-records/1"


class DomainRevisionConflict(RuntimeError):
    """A generic record CAS did not match the currently stored revision."""

    code = "DOMAIN_REVISION_CONFLICT"


@dataclass(frozen=True)
class DomainWrite:
    """One opaque value replacement guarded by its expected record revision.

    ``expected_revision == 0`` means that the record must be absent;
    a positive value must match the revision on the existing record. ``value``
    is retained as supplied. This declaration neither interprets nor freezes
    its mapping.
    """

    namespace: str
    record_id: str
    expected_revision: int
    value: Mapping[str, Any]

    def __post_init__(self) -> None:
        if not isinstance(self.namespace, str) or not self.namespace:
            raise ValueError("record namespace must be a non-empty string")
        if not isinstance(self.record_id, str) or not self.record_id:
            raise ValueError("record id must be a non-empty string")
        if type(self.expected_revision) is not int or self.expected_revision < 0:
            raise ValueError("expected revision must be a nonnegative integer; 0 means absent")
        if not isinstance(self.value, Mapping):
            raise TypeError("record value must be a Mapping")


@runtime_checkable
class DomainStorePort(Protocol):
    """Optional generic record capability on the caller's existing store.

    ``environment`` is an opaque persistence partition label. Implementations
    perform compare-and-swap for each ``DomainWrite`` (zero requires absence;
    positive revisions require an exact match) and commit those writes together
    with the request result in the same existing transaction. The request key
    and digest identify an idempotent request/result according to the store
    owner's contract. This port grants no authority, performs no ACL checks,
    and assigns no business meaning to namespace, key, value, or result.
    """

    def read_domain(
        self, environment: str, namespace: str, record_id: str
    ) -> Mapping[str, Any] | None: ...

    def list_domain(
        self, environment: str, namespace: str
    ) -> tuple[Mapping[str, Any], ...]: ...

    def read_domain_result(
        self, request: RequestKey, digest: str
    ) -> Mapping[str, Any] | None: ...

    def commit_domain_change(
        self,
        request: RequestKey,
        digest: str,
        writes: tuple[DomainWrite, ...],
        result: Mapping[str, Any],
    ) -> Mapping[str, Any]: ...


__all__ = [
    "DOMAIN_STORE_VERSION",
    "DomainRevisionConflict",
    "DomainStorePort",
    "DomainWrite",
]

"""Canonical JSON bytes with explicit immutable acceptance profiles.

Profiles preserve historical wire acceptance without adding another encoder.
The default remains signed-int64, no-float JSON with a depth bound of 64.
"""
from __future__ import annotations

from dataclasses import dataclass
import json
import math
from collections.abc import Mapping

MAX_INTEGER = 2**63 - 1

@dataclass(frozen=True)
class JSONProfile:
    max_depth: int
    max_integer: int | None
    allow_finite_floats: bool = False

STRICT_JSON_PROFILE = JSONProfile(64, MAX_INTEGER)
LIBRARY_JSON_PROFILE = JSONProfile(32, None, True)

class CanonicalJSONError(ValueError):
    def __init__(self, reason: str, *, stage: str = "validation", message: str = "noncanonical_json_value"):
        self.reason = reason
        self.stage = stage
        super().__init__(message)

def _validate(value: object, depth: int = 0, *, profile: JSONProfile = STRICT_JSON_PROFILE) -> None:
    if depth > profile.max_depth:
        raise CanonicalJSONError("depth", message="json_depth")
    if value is None or type(value) in (str, bool):
        return
    if type(value) is int:
        if profile.max_integer is None or -profile.max_integer - 1 <= value <= profile.max_integer:
            return
        raise CanonicalJSONError("type")
    if type(value) is float and profile.allow_finite_floats:
        if math.isfinite(value):
            return
        raise CanonicalJSONError("non_finite")
    if isinstance(value, (list, tuple)):
        for item in value:
            _validate(item, depth + 1, profile=profile)
        return
    if isinstance(value, Mapping):
        if any(type(key) is not str for key in value):
            raise CanonicalJSONError("key_type")
        for item in value.values():
            _validate(item, depth + 1, profile=profile)
        return
    raise CanonicalJSONError("type")

def canonical_text(value: object, *, profile: JSONProfile = STRICT_JSON_PROFILE) -> str:
    _validate(value, profile=profile)
    try:
        encoded = json.dumps(value, ensure_ascii=False, sort_keys=True,
                             separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError) as exc:
        if profile == STRICT_JSON_PROFILE:
            raise
        raise CanonicalJSONError("encode", stage="encode", message="json_encode") from exc
    return encoded

def canonical_bytes(value: object, *, profile: JSONProfile = STRICT_JSON_PROFILE) -> bytes:
    return canonical_text(value, profile=profile).encode("utf-8")

def _pairs(items: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate_json_key")
        result[key] = value
    return result

def decode_json(raw: bytes | str) -> object:
    value = json.loads(raw, object_pairs_hook=_pairs,
                       parse_constant=lambda _: (_ for _ in ()).throw(ValueError("json_nonfinite")))
    _validate(value)
    return value

"""Pure byte digest mechanism. Record prefixes and projections belong to owners."""
import hashlib


def sha256(data: bytes) -> bytes:
    if type(data) is not bytes:
        raise TypeError("digest_requires_bytes")
    return hashlib.sha256(data).digest()

"""Neutral process/framing primitives.

Pure technical line framing and the typed frame-failure contract. No Agent,
provider, lease, writer-admission, receipt or instance semantics live here.
Business owners keep leases, writer admission, receipts and instance state.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping

MAX_FRAME_BYTES = 8 * 1024 * 1024


class ChannelFailure(Exception):
    """Typed transport failure. Callers must not blanket-retry these."""

    def __init__(self, code: str, detail: str):
        super().__init__(f"{code}: {detail}")
        self.code = code
        self.detail = detail


class FramingError(ChannelFailure):
    """Frame stream violated the framing contract (G5)."""

    def __init__(self, detail: str):
        super().__init__("FRAMING_ERROR", detail)


@dataclass(frozen=True)
class Message:
    """One decoded protocol message. ``raw`` is preserved verbatim (G4)."""

    raw: Mapping[str, Any]

    @property
    def kind(self) -> str:
        if "method" in self.raw and "id" in self.raw:
            return "request"
        if "method" in self.raw:
            return "notification"
        return "response"

    @property
    def method(self) -> str | None:
        value = self.raw.get("method")
        return value if isinstance(value, str) else None

    @property
    def id(self) -> Any:
        return self.raw.get("id")


class FrameReader:
    """Byte-safe line framing for protocol streams (G5)."""

    def __init__(self, *, max_frame_bytes: int = MAX_FRAME_BYTES):
        self._max = max_frame_bytes
        self._buffer = bytearray()

    def feed(self, data: bytes) -> list[str]:
        """Consume bytes, return every complete frame decoded so far.

        Raises FramingError on oversize frames, invalid UTF-8 or a truncated
        final frame at EOF (via :meth:`close`).
        """
        self._buffer += data
        frames: list[str] = []
        while True:
            index = self._buffer.find(b"\n")
            if index < 0:
                if len(self._buffer) > self._max:
                    raise FramingError(f"frame exceeded {self._max} bytes")
                break
            if index > self._max:
                raise FramingError(f"frame exceeded {self._max} bytes")
            chunk = bytes(self._buffer[:index])
            del self._buffer[: index + 1]
            frames.append(self._decode(chunk.rstrip(b"\r")))
        return frames

    def close(self) -> None:
        """EOF. Any undecoded remainder is a truncated frame (G5 counter-example:
        silently accepting a half frame would corrupt the message boundary)."""
        if self._buffer:
            raise FramingError("truncated frame at EOF")

    def _decode(self, chunk: bytes) -> str:
        try:
            # Each LF-delimited frame must contain complete UTF-8. Chunk
            # boundaries are buffered above; frame boundaries cannot borrow
            # continuation bytes from another native message.
            return chunk.decode('utf-8',errors='strict')
        except UnicodeDecodeError as exc:
            raise FramingError(f"invalid UTF-8 in frame: {exc.reason}") from exc


__all__ = ["MAX_FRAME_BYTES", "ChannelFailure", "FramingError", "Message", "FrameReader"]

"""Neutral process-spawn primitive: one real OS process with real byte streams.

Nothing here knows about agents, environments, leases, writer admission,
receipts or instances. Business owners keep those and bind them over this
primitive — the environment provider owns the process, the transport owns
framing and fencing, the records owner owns the receipts.

Importing this module opens nothing; only :func:`spawn_process` starts a
process. This module must not import any product package.
"""
from __future__ import annotations

import subprocess
from typing import Any, Mapping, Sequence


class SubprocessHandle:
    """One real OS process with piped, bidirectional byte streams.

    The surface is deliberately ``Popen``-compatible, because the existing
    transport binds to exactly these attributes and the termination evidence
    records the real PID:

    - ``stdin`` / ``stdout`` / ``stderr`` — the real pipe objects (with real
      descriptors), never wrapped or replaced;
    - ``poll`` / ``wait`` / ``terminate`` / ``kill`` / ``send_signal`` — the OS
      lifecycle. ``wait`` propagates :class:`subprocess.TimeoutExpired`
      unchanged, so a caller's terminate/kill escalation keeps its semantics;
    - ``pid`` / ``returncode`` — the OS-level identity and outcome.

    No environment, lease, receipt or instance semantics live on this class.
    """

    __slots__ = ("_popen",)

    def __init__(self, popen: "subprocess.Popen[bytes]"):
        self._popen = popen

    @property
    def popen(self) -> "subprocess.Popen[bytes]":
        """The underlying process object (owner-side access only)."""
        return self._popen

    @property
    def pid(self) -> int:
        return self._popen.pid

    @property
    def returncode(self) -> int | None:
        return self._popen.returncode

    @property
    def stdin(self):
        return self._popen.stdin

    @property
    def stdout(self):
        return self._popen.stdout

    @property
    def stderr(self):
        return self._popen.stderr

    def poll(self) -> int | None:
        return self._popen.poll()

    def wait(self, timeout: float | None = None) -> int:
        return self._popen.wait(timeout=timeout)

    def terminate(self) -> None:
        self._popen.terminate()

    def kill(self) -> None:
        self._popen.kill()

    def send_signal(self, sig: int) -> None:
        self._popen.send_signal(sig)

    def close_streams(self) -> None:
        """Close this process's own pipes. Never touches another process."""
        for stream in (self._popen.stdin, self._popen.stdout, self._popen.stderr):
            if stream is None:
                continue
            try:
                stream.close()
            except OSError:
                pass

    def __repr__(self) -> str:  # pragma: no cover - diagnostics only
        return f"<SubprocessHandle pid={self._popen.pid} rc={self._popen.returncode}>"


def spawn_process(
    argv: Sequence[str],
    *,
    cwd: str,
    env: Mapping[str, str],
) -> SubprocessHandle:
    """Start one real process with piped stdio.

    Raises :class:`OSError` when the process cannot be started; the caller maps
    that onto its own typed failure. Nothing is created or cleaned up here beyond
    the process itself: directory provisioning is the caller's responsibility.
    """
    popen = subprocess.Popen(  # noqa: S603 - argv is caller-resolved and validated
        list(argv),
        cwd=cwd,
        env=dict(env),
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return SubprocessHandle(popen)


__all__ = ["SubprocessHandle", "spawn_process"]
